#include<iostream>
#include<string>
using namespace std;

string triangle_type(float a,float b,float c){
    // Checks if the triangle is not possible
    if(a + b <= c || b + c <= a || a + c <= b){
        return "Not a triangle";
    }
    // Checks if all sides are equal
    else if(a == b && b == c){
        return "Equilateral";
    } 
    // Checks if two sides are equal
    else if(a == b || b == c || c == a){
        return "Isosceles";
    }
    // If no sides are equal
