// Function to get the smallest even node recursively
pair<int, int> SmallestNode(vector<vector<int>> arr, int idx=0, int minE = INT_MAX, int minI = -1) {
    for(auto &vec : arr) {
        for(int &item : vec) {
            if(item % 2 == 0 && item <= minE) {
                minE= item;
                minI = idx;
            }
            idx++;
        }
    }
    return make_pair(minE, minI);
}

