using namespace std;

// Structure of a Node in Doubly Linked List
struct Node {
    int data;
    Node* next;
    Node* prev;
};

// Function to insert a node at the end of the Doubly Linked List
void insertNode(Node** head_ref, int new_data) {
    Node* new_node = new Node();
    Node* last = *head_ref;
    new_node->data = new_data;
    new_node->next = NULL;
    if (*head_ref == NULL) {
        new_node->prev = NULL;
        *head_ref = new_node;
        return;
    }
    while (last->next != NULL)
        last = last->next;
    last->next = new_node;
    new_node->prev = last;
}

// Function to delete a certain value from the Doubly Linked List
void deleteNode(Node** head_ref, int val) {
    Node* current = *head_ref;
    while (current != NULL) {
        // If node to be deleted is head node
        if (current->data == val && current->prev == NULL) {
            *head_ref = current->next;
            delete current;
            return;
        }
        // If node to be deleted is not head or last node
        else if (current->data == val) {
            current->prev->next = current->next;
            if(current->next != NULL) current->next->prev = current->prev;
            delete current;
            return;
        }
        current = current->next;
    }
}

