```c++
#include <stdio.h>
#include <vector>
#include <string>
#include <typeinfo>
using namespace std;

string Strongest_Extension(string class_name, vector<string> extensions){
    // Check for invalid inputs
    if(typeid(class_name).name() != "string" or typeid(extensions).name() != "vector"){
        throw invalid_argument("Invalid inputs. Expected a string and a vector of strings.");
    }

    string strongest_extension = "";
    int max_strength = -2147483648; // initialised with smallest possible integer value

    for (auto extension : extensions){
        int CAP = 0, SM = 0;
        for(char& c : extension){
            if(isupper(c))
                CAP++;
            else if(islower(c))
                SM++;
        }
        int strength = CAP - SM;
        if(strength > max_strength){
            max_strength = strength;
            strongest_extension = extension;
        }
    }
    return class_name + '.' + strongest_extension;
}
