Here's a basic example of how to do template matching in OpenCV using C++:

```cpp
#include "opencv2/imgcodecs.hpp"
#include "opencv2/highgui.hpp"
#include "opencv2/imgproc.hpp"
#include <iostream>

using namespace cv;
using namespace std;

// source image, template image, result image
Mat img, templ, result;

// for template matching function 
int match_method; 
int max_Trackbar = 5;

// function prototype for TemplateMatching
void TemplateMatching(int, void*);

int main(int, char** argv)
{
    // Load source image and template
    img = imread(argv[1], IMREAD_COLOR);
    templ = imread(argv[2], IMREAD_COLOR);

    // Create Trackbar
    namedWindow(image_window, WINDOW_NORMAL);
    createTrackbar("Method: \n 0: SQDIFF \n 1: SQDIFF NORMED \n 2: TM CCORR \n 3: TM CCORR NORMED \n 4: TM COEFF \n 5: TM COEFF NORMED", image_window, 
    &match_method, max_Trackbar, TemplateMatching);

    TemplateMatching(0, 0);

    waitKey(0);
    return 0;
}

void TemplateMatching(int, void*)
{
    // source image to display
    Mat img_display;
    img.copyTo(img_display);

    // create the result matrix
    int result_cols = img.cols - templ.cols + 1;
    int result_rows = img.rows - templ.rows + 1;

    result.create(result_rows, result_cols, CV_32FC1);

    // do the matching 
    matchTemplate(img, templ, result, match_method);

    // localizing the best match
    double minVal, maxVal; 
    Point minLoc, maxLoc, matchLoc;

    minMaxLoc(result, &minVal, &maxVal, &minLoc, &maxLoc, Mat());

    // for SQDIFF and SQDIFF_NORMED, the best matches are lower values. For all the other methods, the higher the better
    if (match_method == TM_SQDIFF || match_method == TM_SQDIFF_NORMED) {
        matchLoc = minLoc;
    } else {
        matchLoc = maxLoc;
    }

    // show the source image with the matched area.
    rectangle(img_display, matchLoc, Point(matchLoc.x + templ.cols, matchLoc.y + templ.rows), Scalar::all(0), 2, 8, 0);
    rectangle(result, matchLoc, Point(matchLoc.x + templ.cols , matchLoc.y + templ.rows), Scalar::all(0), 2, 8, 0);

    imshow(image_window, img_display);
    imshow(result_window, result);
}
```

