    /* swap next and prev for all nodes of  
       doubly linked list */
    while (current !=  nullptr)
    {
       temp = current->prev;
       current->prev = current->next;
       current->next = temp;             
       current = current->prev;
    }

    /* Before changing head, check for the cases like empty  
        list and list with only one node */
    if(temp != nullptr )
        *head_ref = temp->prev;
}

// Function to insert a node at the beginning of the list
void push(Node** head_ref, int new_data) {
    Node* new_node = new Node();
    new_node->data = new_data;
    new_node->prev = nullptr;
    new_node->next = (*head_ref);   
    if((*head_ref) != nullptr)
    (*head_ref)->prev = new_node ;
    (*head_ref) = new_node;
}

// Function to print nodes in a given doubly linked list
void printList(Node *node) {
    while(node!=nullptr) {
        cout << node->data << " ";
        node = node->next;
    }
}

// Driver program to test above functions
int main() {
    Node* head = nullptr;

    push(&head, 2);
    push(&head, 4);
    push(&head, 8);
    push(&head, 10);

    cout << "Original List: ";
    printList(head);

    reverse(&head);

    cout << "\nReversed List: ";
    printList(head);         

    return 0;
}
```
This program will output:
```
Original List: 10 8 4 2 
Reversed List: 2 4 8 10
```
This function reverses a doubly linked list in place, i.e., it doesn't require any extra storage space. The function takes a pointer to the head of the list as input. The function iterates through the list, reversing the next and previous pointers for each node. The head of the list is then updated to the last node visited in the original list.

