```c++
#include<iostream>
#include<vector>
using namespace std;

bool palindrome(vector<float> l){
    int start = 0;
    int end = l.size() - 1;
    while (start < end)
    {
        if(l[start] != l[end]) {
            return false;
        }
        start++;
        end--;
    }
    return true;
}

int main(){
    vector<float> v1 = {1, 2, 3, 2, 1};
    if(palindrome(v1)){
        cout << "It's a palindrome." << endl;
    }
    else {
        cout << "It's not a palindrome." << endl;
    }

    vector<float> v2 = {1, 2, 3, 4, 5};
    if(palindrome(v2)){
        cout << "It's a palindrome." << endl;
    }
    else {
        cout << "It's not a palindrome." << endl;
    }

    return 0;
}
```

In this implementation, the function `palindrome` checks if array's elements are the same when read from left to right or from right to left. It starts from the first (leftmost) and last (rightmost) elements and compares them. If they are not equal, function immediately returns `false` as it is not a palindrome. If they are equal, function moves one step towards center from both ends and repeats the comparison. The process continues until it checks all pairs of elements (from ends towards center). 

If none of the pairs of elements were found to be unequal, then the function returns `true`, indicating that the tested sequence is indeed a palindrome.

