    Aws::InitAPI(options);

    {
        Aws::S3::S3Client s3_client;

        const Aws::String old_bucket_name("my-old-bucket-name");
        const Aws::String new_bucket_name("my-new-bucket-name");

        // Create new bucket
        s3_client.CreateBucket(new_bucket_name);

        // Get list of all objects from old bucket
        Aws::S3::Model::ListObjectsV2Request old_bucket_request;
        old_bucket_request.SetBucket(old_bucket_name);

        auto old_bucket_objects_outcome = s3_client.ListObjectsV2(old_bucket_request);
        // Check if the request was successful
        if(!old_bucket_objects_outcome.IsSuccess())
        {
            std::cout << "Error listing objects from the old bucket" << std::endl;
            return -1;
        }

        auto old_bucket_objects = old_bucket_objects_outcome.GetResult().GetContents();
        for (const auto &object : old_bucket_objects)
        {
            Aws::S3::Model::CopyObjectRequest copy_request;
            copy_request.WithCopySource(old_bucket_name + "/" + object.GetKey())
                        .WithBucket(new_bucket_name)
                        .WithKey(object.GetKey());

            auto copy_object_outcome = s3_client.CopyObject(copy_request);

            if (!copy_object_outcome.IsSuccess())
            {
                std::cout << "Failed to copy object " << object.GetKey() << std::endl;
                return -1;
            }
        }

        // For deleting the old bucket, first we need to delete all object in it
        for (const auto &object : old_bucket_objects)
        {
            Aws::S3::Model::DeleteObjectRequest delete_request;
            delete_request.WithBucket(old_bucket_name)
                          .WithKey(object.GetKey());

            auto delete_object_outcome = s3_client.DeleteObject(delete_request);

            if(!delete_object_outcome.IsSuccess())
            {
                std::cout << "Failed to delete object " << object.GetKey() << std::endl;
                return -1;
            }
        }

        // Now we can delete the old bucket
        Aws::S3::Model::DeleteBucketRequest delete_bucket_request;
        delete_bucket_request.SetBucket(old_bucket_name);

        auto delete_bucket_outcome = s3_client.DeleteBucket(delete_bucket_request);

        if(!delete_bucket_outcome.IsSuccess())
        {
            std::cout << "Failed to delete bucket " << old_bucket_name;
            return -1;
        }

        std::cout << "Rename successful";
    }

    Aws::ShutdownAPI(options);

    return 0;
}
