```cpp
#include <cmath>

class Point3D {
public:
    double x, y, z;

    // Constructor to initialize point coordinates
    Point3D(double x, double y, double z) : x(x), y(y), z(z) {}

    // Function to calculate distance
    double distanceTo(const Point3D &p) {
        return sqrt(pow(x - p.x, 2) + pow(y - p.y, 2) + pow(z - p.z, 2));
    }

    // Function to calculate angle between three points (p1, this, p2)
    static double angleBetween(Point3D &p1, Point3D &p2, Point3D &p3) {
        double distance1= p2.distanceTo(p1);
        double distance2= p2.distanceTo(p3);
        double distance3= p1.distanceTo(p3);

        // Apply the cosine rule
        double cosValue= (pow(distance1,2) + pow(distance2,2) - pow(distance3,2)) / (2 * distance1 * distance2);

        // Convert to degree and return
        double angle= acos(cosValue);
        return angle * 180 / M_PI;
    }
};
```

