```C++
#include <iostream>
#include <vector>
#include <map>
#include <algorithm>
using namespace std;

double findMean(vector<int>& arr) {
    double sum = 0;
    for(int i=0; i<arr.size(); i++)
        sum += arr[i];
    return sum/arr.size();
}

double findMedian(vector<int>& arr) {
    sort(arr.begin(), arr.end());

    // If size of the given array is even
    if(arr.size() % 2 == 0)
        return (arr[arr.size()/2 - 1] + arr[arr.size()/2]) / 2;

    // If size of the array is odd
    else
        return arr[arr.size()/2];
}

int findMode(vector<int>& arr) {
    map<int, int> frequency;
    for(int i=0; i<arr.size(); i++) {
        frequency[arr[i]]++;
    }

    int mode = -1, maxCount = -1;
    for(auto i : frequency) {
        if(i.second > maxCount) {
            maxCount = i.second;
            mode = i.first;
        }
    }

    if(maxCount <= 1)
        return -1; // No mode
    else
        return mode;
}

int main() {
    int size;
    cout << "Enter the size of the array: ";
    cin >> size;

    vector<int> arr(size);
    cout << "Enter elements of the array: ";
    for(int i=0; i<size; i++) {
        cin >> arr[i];
    }

    cout << "Mean: " << findMean(arr) << endl;
    cout << "Median: " << findMedian(arr) << endl;

    int mode = findMode(arr);
    if(mode == -1)
        cout << "Mode: No mode" << endl;
    else
        cout << "Mode: " << mode << endl;

    return 0;
}
```

In this code, we're first getting the size of the array (number of elements) and all elements from the user. Them we're using different functions to calculate mean (sum divided by total number), median (mid-element after sorting) and mode (most frequent number). For mode, we're checking the frequency of all numbers and the number with the highest frequency is our mode. We're handling the case where there's no mode (i.e., no number with frequency more than 1) by returning -1 and displaying "No mode".

