void swapAndReverse(int arr[], int n) {
    // Swapping the first and last elements
    int temp = arr[0];
    arr[0] = arr[n-1];
    arr[n-1] = temp;

    // Reversing the elements in the middle
    for(int i=1, j=n-2; i < j; i++, j--) {
        temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

int main() {
