#include <iostream>
#include <string>

int countNestedNamespaces(const std::string& codeSnippet) {
    int count = 0;
    int maxDepth = 0;
    int currentDepth = 0;
    bool inNamespace = false;

    for (char c : codeSnippet) {
        if (c == '{') {
            if (inNamespace) {
                currentDepth++;
                if (currentDepth > maxDepth) {
                    maxDepth = currentDepth;
                }
            }
            inNamespace = true;
        } else if (c == '}') {
            if (inNamespace) {
                if (currentDepth == maxDepth) {
                    count++;
                }
                currentDepth--;
            }
            if (currentDepth == 0) {
                inNamespace = false;
            }
        }
    }

    return count;
}
```

