Pseudocode:
```c++
#include <iostream>
#include <vector>
#include <thread>
#include <algorithm>
#include <mutex>

using namespace std;

vector<unsigned long long> fibSeries;
mutex mtx;

void printFib(int start, int end) {
    unique_lock<mutex> lock(mtx);

    for (int n = start; n <= end; ++n) {
        if (n <= 1)
            fibSeries[n] = n;
        else
            fibSeries[n] = fibSeries[n-1] + fibSeries[n-2];
    }
}

void correctFib(int n) {
    unique_lock<mutex> lock(mtx);

    if (n > 1 && fibSeries[n] != fibSeries[n-1] + fibSeries[n-2]) {
        fibSeries[n] = fibSeries[n-1] + fibSeries[n-2];
    }
}

int main() {
    int n = 20;
    fibSeries.resize(n+1, 0);

    int numOfThreads = thread::hardware_concurrency() != 0 ? thread::hardware_concurrency() : 2;

    int perThread = n / numOfThreads;
    vector<thread> threads;

    for (int i = 0; i < numOfThreads; ++i) {
        threads.push_back(thread(printFib, i*perThread+1, min((i+1)*perThread, n)));
    }

    for_each(threads.begin(), threads.end(), mem_fn(&thread::join));

    for (int i = 0; i <= n; ++i) {
        correctFib(i);
    }

    for (const auto& num : fibSeries) {
        cout << num << " ";
    }
    cout << endl;

    return 0;
}
``` 

