#include <condition_variable>
#include <stdexcept>

std::mutex mtx;
std::condition_variable cv;
char thread_status[] = {'-', '-', '-'};

void readFile(const std::string &file_name) {
    std::unique_lock<std::mutex> ul(mtx);

    std::ifstream file(file_name);
    if (file.fail()){
        thread_status[0] = 'F';  // failure
    } else {
        thread_status[0] = 'S';  // success
    }

    cv.notify_all();
}

void writeFile(const std::string &file_name) {
    std::unique_lock<std::mutex> ul(mtx);
    cv.wait(ul, []{return thread_status[0] != '-';});
    if (thread_status[0] == 'F') {
        throw std::runtime_error("Read file operation failed");
    }

    std::ofstream file(file_name);
    if (file.fail()){
        thread_status[1] = 'F';
    } else {
        thread_status[1] = 'S';
    }

    cv.notify_all();
}

void performMathOperation() {
    std::unique_lock<std::mutex> ul(mtx);
    cv.wait(ul, []{return thread_status[1] != '-';});
    if (thread_status[1] == 'F') {
        throw std::runtime_error("Write file operation failed");
    }

    try {
        int value = 123*456;  // Replace with an actual calculation
        thread_status[2] = 'S';
    } catch (...) {
        thread_status[2] = 'F';
    }
}

int main() {
    std::thread t1(readFile, "sample.txt");
    std::thread t2(writeFile, "sample2.txt");
    std::thread t3(performMathOperation);

    t1.join();
    t2.join();
    t3.join();

    for (int i = 0; i < 3; ++i) {
        if (thread_status[i] == 'F') {
            std::cerr << "Thread " << i+1 << " failed\n";
        } else {
            std::cerr << "Thread " << i+1 << " succeeded\n";
        }
    }

    return 0;
}
```
This program has three global variables (mtx, cv, thread_status) that are shared across the threads. The mtx mutex is used to protect the condition variable cv and the shared data thread_status. The cv condition variable is used to signal the different threads when it is their turn to run, and thread_status is an array that holds the status of the different threads.

