Below is a simple implementation of a binary search tree using C++. This includes insertion, searching for a node, and inorder traversal to check if elements are sorted correctly. 

Note: This implementation does not consider deletion of a node.

```C++
#include <iostream>

struct Node {
    int data;
    int key;
    Node* left;
    Node* right;
};

// Function to create a new Node in heap
Node* GetNewNode(int data) {
    Node* newNode = new Node();
    if (!newNode) {
        std::cout << "Memory error\n";
        return NULL;
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// To insert data in BST, returns address of root node 
Node* Insert(Node* root, int data) {
    //if tree is empty
    if (root == NULL) {
        root = GetNewNode(data);
    }
    //else, recur down the tree
    else if (data <= root->data) {
        root->left = Insert(root->left, data);
    }
    else {
        root->right = Insert(root->right, data);
    }
    return root;
}

// Function to search a node in BST, returns true if node is found
bool Search(Node* root, int data) {
    while (root != NULL) {
        // pass right subtree as new tree
        if (data > root->data) {
            root = root->right;
        }
        // pass left subtree as new tree
        else if (data < root->data) {
            root = root->left;
        }
        else {
            return true; // if the key is found return true
        }
    }
    return false;
}

//Function to do inorder traversal
void inorder(Node* temp) {
    if (temp == NULL)
        return;

    inorder(temp->left);
    std::cout << temp->data << " ";
    inorder(temp->right);
}

int main() {
    Node* root = NULL;
    //Inserting nodes in binary tree
    root = Insert(root, 20);
    root = Insert(root, 15);
    root = Insert(root, 25);
    root = Insert(root, 10);
    root = Insert(root, 30);

    // Print inoder traversal of the BST
    inorder(root);

    // Search node in BST
    std::cout<<"\nSearching 30 in BST: ";
    if (Search(root, 30))
        std::cout << "Found\n";
    else
        std::cout << "Not Found\n";

    return 0;
}
```
When run, this code should produce the following output:

10 15 20 25 30 
Searching 30 in BST: Found

