In C++, you would do something like this:

```cpp
#include <string>

std::string restructure(const std::string& s) {
    std::string result = "";

    for (auto& i : s) {
        // upper case
        if ('A' <= i && i <= 'Z') {
            result += char((i - 'A' - 5 + 26) % 26 + 'A');
        }
        // lower case
        else if ('a' <= i && i <= 'z') {
            result += char((i - 'a' - 3 + 26) % 26 + 'a');
        }
        // numbers and other characters remain intact
        else {
            result += i;
        }
    }

    return result;
}
```

