The below C++ program will solve the problem efficiently with O(n) time complexity. Here are the steps we are following:

1. Initialize two variables, first_max and second_max, to INT_MIN (minimum possible integer value in C++). They are used to store the largest and second largest elements found so far, respectively.
2. Traverse the array. For every array element, check if it's greater than first_max. If true, update both first_max and second_max. If the array element is not greater than first_max but greater than second_max, update second_max.
3. At the end of the traversal, second_max will hold our answer. If no second maximum distinct element exists, second_max will be INT_MIN, and we will return a unique error code in this case.

Here is how the corrected C++ program looks:

```C++
#include <iostream>
#include <limits.h>
using namespace std;

// function to find the second maximum element
int findSecondMax(int arr[], int n) {
    // initialize two largest numbers
    int max1 = INT_MIN, max2 = INT_MIN;

    // traverse the array elements
    for (int i = 0; i < n; i++) {
        // if current element is greater than max1, update max1 and max2
        if (arr[i] > max1) {
            max2 = max1;
            max1 = arr[i];
        }
        // if arr[i] is in between max1 and max2 then update max2
        else if (arr[i] > max2 && arr[i] < max1) {
            max2 = arr[i];
        }
    }

    // if there was no second maximum distinct element, return a unique error code
    if (max2 == INT_MIN)
        return -1;

    // return second max distinct number
    return max2;
}

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    int n = sizeof(arr)/sizeof(arr[0]);
    int answer = findSecondMax(arr, n);
    if(answer == -1) {
        cout << "No second maximum distinct element.";
    }
    else
        cout << "Second maximum element is " << answer;
    return 0;
}
```
This code is optimized and solves the problem by traversing the array only once. Hence, it satisfies the condition of O(n) time complexity.

