```cpp
#include<cmath>
bool isPrime(int n) {
    if(n <= 1)
        return false;
    if(n == 2)
        return true;
    if(n % 2 == 0)
        return false;
    int sqrtN = sqrt(n);
    for(int i = 3; i <= sqrtN; i += 2)
        if(n % i == 0)
            return false;
    return true;
}

int findSmallestLongestPrimeNumberDigits(vector<int> lst) {
    vector<int> primes;
    // find all prime numbers
    for(int n : lst)
        if(isPrime(n))
            primes.push_back(n);
    if(primes.empty())
        return -1; // return -1 if no prime numbers found

    int maxDigitCount = 0;
    int smallestPrimeWithMaxDigits = 0;
    for(int p : primes){
        int digitCount = to_string(p).size();
        if(digitCount > maxDigitCount){
            maxDigitCount = digitCount;
            smallestPrimeWithMaxDigits= p;
        }
        else if(digitCount == maxDigitCount){
            if(p < smallestPrimeWithMaxDigits)
