```cpp
#include <cctype>
#include <string>

class NaturalCmp {
public:
    static bool isSpace(char c) {
        return std::isspace(static_cast<unsigned char>(c));
    }

    static int naturalCompare(const std::string& str1, const std::string& str2) {
        const char *s1 = str1.c_str();
        const char *s2 = str2.c_str();

        while (*s1 && *s2) {
            skipSpaces(s1);
            skipSpaces(s2);

            if (std::isdigit(*s1) && std::isdigit(*s2)) {
                // Compare numbers
                int num1 = 0, num2 = 0;
                while (std::isdigit(*s1)) {
                    num1 = num1 * 10 + (*s1 - '0');
                    s1++;
                }
                while (std::isdigit(*s2)) {
                    num2 = num2 * 10 + (*s2 - '0');
                    s2++;
                }
                if (num1 != num2) {
                    return (num1 < num2) ? -1 : 1;
                }
            } else {
                if (*s1 != *s2) {
                    return (*s1 < *s2) ? -1 : 1;
                }
                s1++;
                s2++;
            }
        }

        if (*s1) {
            return 1; // str1 is longer
        } else if (*s2) {
            return -1; // str2 is longer
        } else {
            return 0; // strings are equal
        }
    }

    static void skipSpaces(const char *&s) {
        while (isSpace(*s)) s++;
    }
};
```

