    running_ = true;
    while (running_) {
      if (!message_queue_.empty()) {
        std::function<void()> message = message_queue_.front();
        message_queue_.pop();
        message();
      }
    }
  }

  void Stop() {
    running_ = false;
  }

  void AddMessage(std::function<void()> message) {
    message_queue_.push(message);
  }

private:
