// Function to sort an array in ascending order using Bubble Sort
void sortArray(int arr[], int n) {
    for(int i = 0; i < n-1; i++) {     // Loop for pass
       for(int j = 0; j < n-i-1; j++) {  // Loop for each comparison and swap in each pass
           if(arr[j] > arr[j+1]) {
              // Swap arr[j] and arr[j+1] if arr[j] is greater
              int temp = arr[j];
              arr[j] = arr[j+1];
              arr[j+1] = temp;
           }
       }
    }
}

int main() {
   srand(time(0));  // Seed random number generator

   int arr[1000];   // Declare an array of size 1000

   // Loop to fill array with random numbers from 1 to 1000
   for(int i = 0; i < 1000; i++) {
      arr[i] = (rand() % 1000) + 1;
