#include<iostream>
using namespace std;

// BubbleSort function 
void BubbleSort(int arr[], int n) {
  for(int i = 0; i < n; i++) {
    for(int j = 0; j < n - i - 1; j++) {
      if(arr[j] > arr[j + 1]) {
        int temp = arr[j];
        arr[j] = arr[j + 1];
        arr[j + 1] = temp;
      }
    }
  }
}

// Binary Search Function
int BinarySearch(int arr[], int l, int r, int x) {
  if (r >= l) {
    int mid = l + (r - l) / 2;

    if (arr[mid] == x)
      return mid;

    if (arr[mid] > x)
      return BinarySearch(arr, l, mid - 1, x);

    return BinarySearch(arr, mid + 1, r, x);
  }
  return -1;
}

// Main function
int main() {
  int arr[] = {5, 3, 1, 9, 8, 2, 4, 7};
  int n = sizeof(arr)/sizeof(arr[0]);

  BubbleSort(arr, n);

  cout<<"Sorted array: ";
  for(int i = 0; i < n; i++) {
    cout<<arr[i]<<" ";
  }
