```python
import re

def extract_license_info(license_text):
    # Extracting license name
    license_name_match = re.search(r'SPDX-License-Identifier\s*:\s*(\w+-\w+)', license_text)
    license_name = license_name_match.group(1) if license_name_match else "Unknown"

    # Extracting permissions
    permissions_match = re.findall(r'(\d+\.\s+)?(.*?)are permitted', license_text, re.DOTALL)
    permissions = [permission[1].strip() for permission in permissions_match]

    # Extracting conditions
    conditions_match = re.findall(r'(\d+\.\s+)?(.*?)\.', license_text, re.DOTALL)
    conditions = [condition[1].strip() for condition in conditions_match if condition[1].strip()]

    # Printing extracted information
    print(f"License Name: {license_name}")
    print("Permissions:")
    for permission in permissions:
        print(f"- {permission}")
    print("Conditions:")
    for condition in conditions:
        print(f"- {condition}")

