// Function to perform element-wise multiplication on two input arrays
std::vector<std::vector<std::vector<std::vector<float>>>>
elementwise_multiplication(
    const std::vector<std::vector<std::vector<std::vector<float>>>>& input1,
    const std::vector<std::vector<std::vector<std::vector<float>>>>& input2) {

    // Ensure the input arrays have the same dimensions
    if (input1.size() != input2.size() ||
        input1[0].size() != input2[0].size() ||
        input1[0][0].size() != input2[0][0].size() ||
        input1[0][0][0].size() != input2[0][0][0].size()) {
        std::cerr << "Input arrays must have the same dimensions." << std::endl;
        return {};
    }

    // Initialize the output array with the same dimensions as the input arrays
    std::vector<std::vector<std::vector<std::vector<float>>>>
    output(input1.size(), std::vector<std::vector<std::vector<float>>>(
        input1[0].size(), std::vector<std::vector<float>>(
            input1[0][0].size(), std::vector<float>(
                input1[0][0][0].size(), 0.0f))));

    // Perform element-wise multiplication
    for (size_t b = 0; b < input1.size(); ++b) {
        for (size_t c = 0; c < input1[0].size(); ++c) {
            for (size_t h = 0; h < input1[0][0].size(); ++h) {
                for (size_t w = 0; w < input1[0][0][0].size(); ++w) {
                    output[b][c][h][w] = input1[b][c][h][w] * input2[b][c][h][w];
                }
            }
        }
    }

    return output;
}

