```C++
class LinkedList {
public:
    struct Node {
        int data;
        Node* next;
    };

    // function to merge two sorted linked lists
    Node* mergeLists(Node* l1, Node* l2) {
        if (l1 == NULL) return l2;
        if (l2 == NULL) return l1;

        Node* head = NULL; 
        if (l1->data < l2->data) {
            head = l1;
            l1 = l1->next;
        } else {
            head = l2;
            l2 = l2->next;
        }

        Node* tail = head;

        while (l1 != NULL && l2 != NULL) {
            if (l1->data < l2->data) {
                tail->next = l1;
                l1 = l1->next;
            } else {
                tail->next = l2;
                l2 = l2->next;
            }
            tail = tail->next;
        }

        if (l1 != NULL) tail->next = l1;
        else tail->next = l2;

        return head;    
    }

    // function to create a linked list from an array
    Node* createLinkedList(int arr[], int size) {
        Node *head = NULL, *tail = NULL;
        for (int i = 0; i < size; i++) {
            Node* newNode = new Node();
            newNode->data = arr[i];
            newNode->next = NULL;

            if (i == 0) {
                head = newNode;
                tail = newNode;
            } else {
                tail->next = newNode;
                tail = newNode;
            }
        }
        return head;
    }

   // function to split a linked list into two equal halves
   void splitList(Node* head, Node** firstHalf, Node** secondHalf) {
       Node* fast;
       Node* slow;
       slow = head;
       fast = head->next;

       // Fast advances two nodes, and slow advances one node
       while (fast != NULL) {
           fast = fast->next;
           if (fast != NULL) {
               slow = slow->next;
               fast = fast->next;
           }
       }

       // slow is before the midpoint in the list, so split it in two at that point.
       *firstHalf = head;
       *secondHalf = slow->next;
       slow->next = NULL;
   }
};
```

Now the new node is created only when a new element is inserted into the linked list. This uses memory more efficiently. Also, the linked list is now being split into two equal halves. If the length of the linked list is odd, the first half will contain one more node than the second half. Finally, the edge case of one of the lists being NULL is also appropriately handled.

