Certainly, here's a working example of a C++ function that does what you've described. It's called `mergeLists` and is implemented as a member function of simple `LinkedList` class for basic singly-linked list operations.

The `mergeLists` function loops over the nodes in both input lists, taking the smallest each time and putting that on the end of a new list, which is then returned. Lists are merged recursively to keep the code simple and concise.

```cpp
#include <iostream>
using namespace std;

// Defining node structure
struct Node {
    int data;
    struct Node *next;
};

// LinkedList class
class LinkedList {
public:
    Node *head;

    // Constructor to initialize head
    LinkedList(): head(NULL) {}

    // Adds new node to the end of this list
    void push(int newData) {
        Node *newNode = new Node;
        newNode->data = newData;
        newNode->next = head;
        head = newNode;
    }
    static Node * mergeLists(Node *list1, Node* list2) {
        Node *mergedList = nullptr;

        if (list1 == nullptr) return list2;
        else if (list2 == nullptr) return list1;

        // Select smallest list node first
        if (list1->data <= list2->data) {
            mergedList = list1;
            mergedList->next = mergeLists(list1->next, list2);
        }
        else {
            mergedList = list2;
            mergedList->next = mergeLists(list1, list2->next);
        }
        return mergedList;
    }
};

int main() {
    LinkedList list1, list2;

    // Insert nodes into list1
    list1.push(10);
    list1.push(20);
    list1.push(30);

    // Insert nodes into list2
    list2.push(5);
    list2.push(15);
    list2.push(25);

    Node *mergedList = LinkedList::mergeLists(list1.head, list2.head);

    cout << "Merged Linked List:\n";
    while (mergedList != nullptr) {
        cout << mergedList->data << " ";
        mergedList = mergedList->next;
    }

    return 0;
}
```
In this code, two linked lists are created with the `push` method. They are then merged in ascending order by the `mergeLists` method. The resulting merged list is printed out in the main function. The implementation is memory-efficient because it re-uses nodes from the input lists rather than unnecessarily creating new nodes for the output list.

