```cpp
#include <vector>
#include <cmath>

namespace challenges {

    class Challenge10 {
    public:
        using Type_t = unsigned long long;

        Challenge10(unsigned long long limit) : limit(limit) {}

        Type_t solve() {
            std::vector<bool> sieve(limit, true);
            sieve[0] = sieve[1] = false;

            for (unsigned long long i = 2; i * i < limit; ++i) {
                if (sieve[i]) {
                    for (unsigned long long j = i * i; j < limit; j += i) {
                        sieve[j] = false;
                    }
                }
            }

            Type_t sum = 0;
            for (unsigned long long i = 2; i < limit; ++i) {
                if (sieve[i]) {
                    sum += i;
                }
            }

            return sum;
        }

    private:
        unsigned long long limit;
    };

    extern "C" unsigned long long solveChallenge10(unsigned long long limit) {
        return std::any_cast<Challenge10::Type_t>(Challenge10(limit).solve());
    }

}  // namespace challenges
```

