Here is a function in C++ for solving a cubic equation ax^3 + bx^2 + cx + d = 0 taken into account all possible real and complex roots:

```cpp
#include <iostream>
#include <cmath>
#include <complex>

void solveCubic(double a, double b, double c, double d) {
    b /= a;
    c /= a;
    d /= a;
    double q = (3.0*c - (b*b))/9.0;
    double r = -(27*d) + b*(9*c - 2*(b*b));
    r /= 54.0;

    double discriminant = q*q*q + r*r;
    double term1 = b/3.0;

    if (discriminant > 0) { // one root real, two are complex
        double s = r + sqrt(discriminant);
        s = s < 0 ? -pow(-s, (1.0/3.0)) : pow(s, (1.0/3.0));
        double t = r - sqrt(discriminant);
        t = t < 0 ? -pow(-t, (1.0/3.0)) : pow(t, (1.0/3.0));

        double realPart = -term1 + s + t;
        term1 += (s + t)/2.0;
        double imaginaryPart = sqrt(3.0) * (s - t)/2;
        // print real root and complex one
        std::cout << "Real Root : " << realPart << std::endl;
        std::cout << "Complex Roots : " << term1 << " ± " << imaginaryPart << "i" << std::endl;
    } 
    else if(discriminant == 0){ // All roots are real and at least two are equal.
        double s = r < 0 ? -pow(-r, (1.0/3.0)) : pow(r, (1.0/3.0));
        // print real root
        std::cout << "Real Roots : " << (-term1 + s) << " and " << (-term1 - s/2) << std::endl;
    }
    else { // All roots are real and unequal (discriminant < 0).
        q = -q;
        double dum1 = q*q*q;
        dum1 = acos(r/sqrt(dum1));
        double r13 = 2.0*sqrt(q);
        // print real root
        std::cout << "Real Roots : " << (-term1 + r13*cos(dum1/3.0)) << ", "
                   << (-term1 + r13*cos((dum1 + 2.0*M_PI)/3.0)) << " and "
                   << (-term1 + r13*cos((dum1 + 4.0*M_PI)/3.0)) << std::endl;
    }
}
```
Please note that this implementation assumes `a` is not equal to `0`. If `a` equals `0`, it is not a cubic equation anymore.

