int maxSumPath(std::vector<std::vector<int>>& grid, int k) {
    int N = grid.size();
    if (k > N*N) return std::numeric_limits<int>::min(); 

    std::vector<std::vector<std::vector<int>>> dp_table(N, std::vector<std::vector<int>>(N, std::vector<int>(k, std::numeric_limits<int>::min())));
    dp_table[0][0][0] = grid[0][0];

    for (int total_count = 1; total_count < k; ++total_count) {
        for (int x = 0; x < N; ++x) {
            for (int y = 0; y < N; ++y) {
                if (total_count < x + y) continue;

                int prevMax = std::numeric_limits<int>::min();

                if (x > 0)
                    prevMax = std::max(prevMax, dp_table[x-1][y][total_count-1]);
                if (y > 0)
                    prevMax = std::max(prevMax, dp_table[x][y-1][total_count-1]);
                if (x > 0 && y > 0)
                    prevMax = std::max(prevMax, dp_table[x-1][y-1][total_count-1]);

                dp_table[x][y][total_count] = prevMax + grid[x][y];
            }
        }
    }

    std::vector<int> maxValues;
    for (auto& row : dp_table[N - 1])
        maxValues.push_back(*std::max_element(row.begin(), row.end()));

    return maxValues.empty() ? std::numeric_limits<int>::min() : *std::max_element(maxValues.begin(), maxValues.end());
}
```

