#include "ThreadSafeMap.h"

int main() {
    ThreadSafeMap<int, std::string> safeMap;

    // Insert key-value pairs
    safeMap.insert(1, "One");
    safeMap.insert(2, "Two");

    // Retrieve value for a key
    std::string value = safeMap.get(1);
    std::cout << "Value for key 1: " << value << std::endl;

    // Check if a key exists
    bool exists = safeMap.contains(3);
    std::cout << "Key 3 exists: " << (exists ? "true" : "false") << std::endl;

    // Erase a key
