class DynamicArray {
private:
    std::unique_ptr<int[]> data;
    int size;

public:
    // Constructor to allocate memory for the array
    DynamicArray(int initialSize) : size(initialSize), data(new int[initialSize]) {}

    // Method to access and modify elements of the array
    int& operator[](int index) {
        if (index < 0 || index >= size) {
            throw std::out_of_range("Index out of range");
        }
        return data[index];
    }

    // Method to resize the array
    void resize(int newSize) {
        if (newSize == size) {
            return;  // No need to resize
        }
        std::unique_ptr<int[]> newData(new int[newSize]);
        int elementsToCopy = (newSize < size) ? newSize : size;
        for (int i = 0; i < elementsToCopy; ++i) {
            newData[i] = data[i];
        }
        data = std::move(newData);
        size = newSize;
    }

    // Destructor to release the memory
    ~DynamicArray() {
        data.reset();  // Memory deallocation
    }
};

int main() {
    DynamicArray arr(10);  // Create a dynamic array of size 10
    arr[5] = 42;  // Modify element at index 5
    std::cout << arr[5] << std::endl;  // Access element at index 5

