```cpp
vector<int> unique(vector<int> l){
    // size of the vector
    int n = l.size();

    // selection sort algorithm
    for(int i = 0; i < n-1; i++){
        int min_idx = i;
        for(int j = i+1; j < n; j++){
            if(l[j] < l[min_idx])
                min_idx = j;
        }
        // swap
        int temp = l[min_idx];
        l[min_idx] = l[i];
        l[i] = temp;
    }

    // removing duplicates
    vector<int> unique_vec;
    unique_vec.push_back(l[0]);

    for(int i = 1; i < n; i++){
        if(l[i]!=l[i-1])
            unique_vec.push_back(l[i]);
    }

    return unique_vec;
}
```
