```cpp
#include <iostream>
#include <cstring>

class String {
private:
    char* data;
    int* refCount;

public:
    String(const char* str) {
        data = new char[strlen(str) + 1];
        strcpy(data, str);
        refCount = new int(1);  // Initialize reference count to 1 for the new object
    }

    String(const String& other) {
        data = other.data;
        refCount = other.refCount;
        (*refCount)++;  // Increment reference count for the copied object
    }

    ~String() {
        (*refCount)--;
        if (*refCount == 0) {
            delete[] data;
            delete refCount;
        }
    }

    int getRefCount() const {
        return *refCount;
    }
};

void test() {
