    String s2 = s1;  // Copy constructor, reference count should be 2
    std::cout << s1.getRefCount() << std::endl;  // Output: 2
    std::cout << s2.getRefCount() << std::endl;  // Output: 2
}

int main() {
    test();
    return 0;
}
