```cpp
#include<iostream>
using namespace std;

void sortArray(int unsorted_arr[], int n) {
   for(int i = 0; i<n; i++) {
      for (int j = i+1; j<n; j++){
         if(unsorted_arr[i]>unsorted_arr[j]) {
            // Swapping of elements
            int temp = unsorted_arr[i];
            unsorted_arr[i] = unsorted_arr[j];
            unsorted_arr[j] = temp;
