void deleteNode(Node** headRef, Node* del) {

    if (*headRef == NULL || del == NULL) {
        return;
    }

    if (*headRef == del) {
        *headRef = del->next;
    }

    if (del->next != NULL) {
        del->next->prev = del->prev;
