        *headRef = del->next;
    }

    if (del->next != NULL) {
        del->next->prev = del->prev;
    }

    if (del->prev != NULL) {
        del->prev->next = del->next;
    }

    delete del;

    return;
}
```

This function only deletes a node given as `del`. To delete all nodes with a specific value, we need to traverse the list and call this function when we find the value. Here's a possible solution for this problem:

```cpp
