    eventQueue.Enqueue(e1);
    eventQueue.Enqueue(e2);
    eventQueue.Enqueue(e3);

    Event removedEvent = eventQueue.RemoveFromTop();
    removedEvent.Delete(); // Caller takes ownership and calls Delete on the removed event

    return 0;
}
