// Node definition
struct Node {
  int data;
  Node *next;
};

// function to create a new node
Node* newNode(int data) {
    Node* newNode = new Node();
    if (!newNode) {
        cout << "Memory error\n";
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to insert node at the end
Node* insertNode(Node* head, int data) {
    if (head == NULL)
        head = newNode(data);
    else
        head->next = insertNode(head->next, data);

    return head;
}

// Recursive function to merge two sorted linked list
Node* mergeSorted(Node* a, Node* b) {
    Node* result = NULL;

    if(a == NULL)
        return b;
    else if(b == NULL)
        return a;

    if(a->data <= b->data){
        result = a;
        result->next = mergeSorted(a->next, b);
    }
    else{
        result = b;
        result->next = mergeSorted(a, b->next);
    }
    return result;
}

