```C++
#include<iostream>
using namespace std;

// Node Structure
struct Node {
    int data;
    Node* next;
    Node* prev;
};

// Class for Doubly LinkedList
class DoublyLinkedList {
    Node* head;

public:
    DoublyLinkedList() : head(NULL) {}

    void insert(int val) {
        Node* newNode = new Node;
        newNode->data = val;
        newNode->next = NULL;
        newNode->prev = NULL;

        if(head == NULL) { //if list is empty, make new node the head
            head = newNode;
            return;
        }

        Node* temp = head; //otherwise, traverse to end of list and insert
        while(temp->next) {
            temp = temp->next;
        }

        temp->next = newNode;
        newNode->prev = temp;
    }

    void deleteItem(int val) {
        Node* temp = head;
        while(temp) {
            if(temp->data == val) { //node to be deleted found
                if(temp->prev) //node is not head
                    temp->prev->next = temp->next;
                else //node is head
                    head = temp->next;

                if(temp->next) //node is not tail
                    temp->next->prev = temp->prev;

                delete temp;
                return;
            }
            temp = temp->next;
        }
    }

    Node* search(int val) {
        Node* temp = head;
        while(temp) {
            if(temp->data == val) 
                return temp; //return the node if found

            temp = temp->next;
        }
        return NULL; //return NULL if not found
    }

    void display() {
        Node* temp = head;
        while(temp) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << endl;
    }
};

int main() {
    DoublyLinkedList dll;
    dll.insert(10);
    dll.insert(20);
    dll.insert(30);
    dll.display();
    dll.deleteItem(20);
    dll.display();
    if(dll.search(10))
        cout << "10 Found" << endl;
    else
        cout << "10 Not Found" << endl;

    return 0;
}
