from typing import List

def minCostTravel(matrix: List[List[int]]) -> int:
    n = len(matrix)
    if n == 1:
        return min(matrix[0])

    dp = [[0, 0, 0] for _ in range(n)]
    dp[0] = matrix[0]

    for i in range(1, n):
