class CallbackManager:
    def __init__(self):
        self.callbacks = {
            'particlescraper': None,
            'particleloader': None,
            'beforestep': None,
            'afterstep': None,
            'afterrestart': None
        }

    def register_callback(self, stage, callback_func):
        if stage.lower() in self.callbacks:
            self.callbacks[stage.lower()] = callback_func
        else:
            raise ValueError(f"Invalid stage: {stage}. Supported stages are particlescraper, particleloader, beforestep, afterstep, and afterrestart.")

    def execute_callback(self, stage):
        if stage.lower() in self.callbacks and self.callbacks[stage.lower()]:
            self.callbacks[stage.lower()]()
        else:
            print(f"No callback registered for stage: {stage}")


# Demonstration of usage
def sample_particlescraper_callback():
    print("Executing particle scraper callback")

def sample_particleloader_callback():
    print("Executing particle loader callback")

def sample_beforestep_callback():
    print("Executing before step callback")

def sample_afterstep_callback():
    print("Executing after step callback")

def sample_afterrestart_callback():
    print("Executing after restart callback")

