callback_manager.register_callback('particleloader', sample_particleloader_callback)
callback_manager.register_callback('beforestep', sample_beforestep_callback)
callback_manager.register_callback('afterstep', sample_afterstep_callback)
callback_manager.register_callback('afterrestart', sample_afterrestart_callback)

# Execute the registered callback functions at appropriate stages
