```C++
#include<iostream>
#include<string>
using namespace std;

int sum_lower(string s) {
    int sum = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s[i];
        if (i % 2 != 0 && c >= 'a' && c <= 'z' && c != 'a' && c != 'e' && c != 'i' && c != 'o' && c != 'u') {
            sum += (int)c;
        }
    }
    return sum;
