struct Node {
  int data;
  Node* next;
};

class LinkedList {
  private:
    Node* head;
    Node* tail;
  public:
    LinkedList() : head(nullptr), tail(nullptr) {}

    void addNode(int n) {
        Node* newNode = new Node;
        newNode->data = n;
        newNode->next = nullptr;

        if(head == nullptr) {
            head = newNode;
            tail = newNode;
        }
        else {
            tail->next = newNode;
            tail = tail->next;
        }
    }

    void display() {
        Node* cur = head;
        while(cur != nullptr) {
            cout << cur->data << " ";
            cur = cur->next;
        }
        cout << endl;
    }
};

