#include <iostream>
#include <vector>
#include <string>

std::vector<std::string> ModifyArray(std::vector<std::string>& arr, int maxLen) {
    std::vector<std::string> output;
    std::string temp;

    for (const std::string& str : arr) {
        if (str.length() == 0) continue; // skip if empty string

        if ((temp.length() + str.length()) <= maxLen) { // concatenation does not exceed maxLen
            temp += str;
        }
        else {
            // if temp is non-empty, add it to output
            if (!temp.empty()) {
                output.push_back(temp);
            } 
            temp = str;
        }
    }
    if (!temp.empty()) {
        output.push_back(temp); // append the remaining string
    }
    return output;
}

int main() {
    std::vector<std::string> arr = {"", "stack", "overflow", "", "Programming", "test", "question"};
    int maxStringLength = 15;
    std::vector<std::string> result = ModifyArray(arr, maxStringLength);
    for (const auto& str : result) {
        std::cout << str << std::endl;
    }
    return 0;
}
