```C++
#include <vector>
#include <algorithm>
#include <map>

std::vector<std::tuple<double, double, int>> rolling_avg_median_mode(std::vector<int> numbers) {

    if (numbers.empty()) {
        return {};
    }

    std::vector<std::tuple<double, double, int>> my_list;

    for (size_t i = 1; i <= numbers.size(); ++i) {
        std::vector<int> curnumbers(numbers.begin(), numbers.begin()+i);

        // Calculating average
        double curavg = std::accumulate(curnumbers.begin(), curnumbers.end(), 0.0) / curnumbers.size();

        // Calculating median
        std::sort(curnumbers.begin(), curnumbers.end());
        double curmed = curnumbers.size() % 2 != 0 ? curnumbers[curnumbers.size()/2] 
                                         : (curnumbers[curnumbers.size()/2 - 1] + curnumbers[curnumbers.size()/2]) / 2.0;

        // Calculating mode        
        std::map<int, int> counter;
        for (const auto& elem: curnumbers) {
            ++counter[elem];
        }

        auto curmod = std::max_element(counter.begin(), counter.end(), 
                    [](const std::pair<int, int>& a, const std::pair<int, int>& b) { 
                        return a.second < b.second; 
                    })->first;

        // Checking for repeat tuple
        if (!my_list.empty()) {
            if (std::make_tuple(curavg, curmed, curmod) != my_list.back()) {
                my_list.emplace_back(curavg, curmed, curmod);
            }
        } else {
            my_list.emplace_back(curavg, curmed, curmod);
        }
    } 

    return my_list;
}
```

