Here is a simple function in C++ which will remove all occurrences of a specific value from a given bidirectional (doubly) linked list. The function takes the head pointer of the linked list and the value to be removed as input. It returns the updated head pointer.

The function works by traversing through the linked list, and for each node that matches the target value, it connects the previous node to the next node, effectively skipping over (and removing) the target node from the linked list. If the head node contains the target value, the function sets the head to the next node then deletes the old head node.

Here is the function:

```cpp 
#include <iostream>
using namespace std;

// Structure for a Node 
struct Node {
    int data;
    struct Node* prev;
    struct Node* next;
};

// Function to delete a given node from the list 
struct Node* deleteNode(struct Node **head_ref, struct Node *del) {

    // base case
    if (*head_ref == NULL || del == NULL)
        return NULL;

    // If node to be deleted is head node
    if (*head_ref == del)
        *head_ref = del->next;

    // Change next only if node to be deleted is NOT the last node
    if (del->next != NULL)
        del->next->prev = del->prev;

    // Change prev only if node to be deleted is NOT the first node
    if (del->prev != NULL)
        del->prev->next = del->next;

    // Finally, free the memory occupied by del
    free(del);

    return *head_ref;
}

// Function to remove all occurrences of element x from the linked list
struct Node* deleteAllOccurrencesOfX(struct Node* head, int x) {

    // If list is empty
    if (head == NULL)
        return NULL;

    struct Node* current = head;

    // Traverse the list up to end
    while (current != NULL) {

        // if node's data is equal to x, delete the node
        if (current->data == x) {
            Node* temp = current;
            current = current->prev;

            // delete the node pointed by 'temp'
            head = deleteNode(&head, temp);
        }

        // move to the next node
        if (current!= NULL)
            current = current->next ;
    }

    return head;
}
```
Please note that the above implementation assumes that the provided linked list is a doubly linked list.

