    SparseMatrix(int r, int c) : rows(r), cols(c) {}

    void insert(int i, int j, int val) {
        if (i > rows || j > cols) {
            cout << "Index out of bounds" << endl;
            return;
        }
        sm[make_pair(i, j)] = val;
    }

    SparseMatrix add(SparseMatrix b) {
        if (rows != b.rows || cols != b.cols) {
            cout << "Matrices of different size cannot be added" << endl;
            return *this;
        }

        SparseMatrix res(rows, cols);
        for(auto const &tuple : sm) {
            res.insert(tuple.first.first, tuple.first.second, tuple.second + b.sm[tuple.first]);
        }

        return res;
    }

    SparseMatrix transpose() {
        SparseMatrix res(cols, rows);
        for(auto const &tuple : sm) {
            res.insert(tuple.first.second, tuple.first.first, tuple.second);
        }

        return res;
    }

    void print() {
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if(sm[make_pair(i, j)] != 0) {
                    cout << sm[make_pair(i, j)] << " ";
                } else {
                    cout << "0 ";
                }
            }
            cout << endl;
        }
    }

    // Note: the multiplication function only works for matrices where multiplication is possible (number of columns in first matrix == number of rows in second matrix)
    SparseMatrix multiply(SparseMatrix b) {
        if (cols != b.rows) {
            cout << "These matrices cannot be multiplied" << endl;
            return *this;
        }

        SparseMatrix res(rows, b.cols);

        for(int i = 1; i <= rows; i++) {
            for(int j = 1; j <= b.cols; j++) {
                int mul = 0;
                for(int k = 1; k <= cols; k++) {
                    mul += sm[make_pair(i, k)] * b.sm[make_pair(k, j)];
                }
                if(mul != 0) {
                    res.insert(i, j, mul);
                }
            }
        }

        return res;
    }
};
