```cpp
#include <vector>
#include <queue>
#include <algorithm>

struct Edge {
    int src, dest, weight;
};

struct Graph {
    int V, E;
    std::vector<Edge> edges;
};

auto get_heap() noexcept {
    const auto compare = [](const Edge& lhs, const Edge& rhs) noexcept {
        return lhs.weight > rhs.weight;
    };

    return std::priority_queue<Edge, std::vector<Edge>, decltype(compare)>{compare};
}

int findParent(std::vector<int>& parent, int i) {
    if (parent[i] == -1)
        return i;
    return findParent(parent, parent[i]);
}

void unionSets(std::vector<int>& parent, int x, int y) {
    int xset = findParent(parent, x);
    int yset = findParent(parent, y);
    parent[xset] = yset;
}

std::vector<Edge> findMST(const Graph& graph) {
    std::vector<Edge> result;
    std::vector<int> parent(graph.V, -1);
    auto pq = get_heap();

    for (const auto& edge : graph.edges) {
        pq.push(edge);
    }

    while (!pq.empty() && result.size() < graph.V - 1) {
        Edge nextEdge = pq.top();
        pq.pop();

        int x = findParent(parent, nextEdge.src);
        int y = findParent(parent, nextEdge.dest);

        if (x != y) {
            result.push_back(nextEdge);
            unionSets(parent, x, y);
        }
    }

    return result;
}
```

The `findMST` function uses a priority queue created using the `get_heap` function to implement Kruskal's algorithm for finding the minimum spanning tree of the given graph. It initializes a vector `parent` to keep track of the subsets of vertices and iterates through the edges in non-decreasing order of weight, adding the minimum weight edges that do not form a cycle in the MST. Finally, it returns the minimum spanning tree as a vector of Edges.

