```cpp
bool check_if_last_char_is_unattached(string txt){
    if (txt.empty()) return false; 

    char lastChar = txt[txt.size()-1];
    if(!isalnum(lastChar)) return false;  

    if (txt.size() == 1) return true;

    char secondLastChar = txt[txt.size()-2];

    // If both last and second last are alphabets or both are digits then return false
