```cpp
#include <iostream>
#include<vector>
using namespace std;

// function to perform partition
int partition(vector<int>& arr, int low, int high) {
    int pivot = arr[high]; // considering rightmost element as pivot
    int i = (low - 1); // smaller element index

    for (int j = low; j <= high - 1; j++) {
        bool condition1 = (arr[j] % 2 == 0) && (pivot % 2 != 0); //arr[j] is even, pivot is odd
        bool condition2 = (arr[j] % 2 == arr[high] % 2) && (arr[j] > pivot); //both are even or both are odd
        // if current element is in correct sort position with pivot according to our custom comparator
        if (condition1 || condition2) {
            i++;
            swap(arr[i], arr[j]);
        }
    }
    swap(arr[i + 1], arr[high]);
    return (i + 1);
}

// function to perform quicksort
void quickSort(vector<int>& arr, int low, int high) {
    if (low < high) {
        // pi is partitioning index 
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1); // recursively sort elements before and after partition
        quickSort(arr, pi + 1, high);
    }
}

