```c++
#include <aws/core/Aws.h>
#include <aws/s3/S3Client.h>
#include <aws/s3/model/GetObjectRequest.h>

bool AWSS3GetFile(char *BucketName, char *FileName, char *LocalFileName)
{
    Aws::SDKOptions options;
    Aws::InitAPI(options);
    {
        Aws::S3::S3Client s3_client;
        Aws::S3::Model::GetObjectRequest object_request;
        object_request.WithBucket(BucketName).WithKey(FileName);

        auto get_object_outcome = s3_client.GetObject(object_request);

        if (get_object_outcome.IsSuccess())
        {
            std::ofstream output_file(LocalFileName, std::ios::binary);
            output_file << get_object_outcome.GetResult().GetBody().rdbuf();
        }
        else
        {
            std::cout << "GetObject error: " <<
            get_object_outcome.GetError().GetExceptionName() << " " <<
            get_object_outcome.GetError().GetMessage() << std::endl;
            return false;
        }
    }
    Aws::ShutdownAPI(options);
    return true;
}

