Here is a simple C++ program that does the asked job. This program uses STL `map` for storing and counting individual words and their frequencies. The sorting is achieved by copying the `map` to a `vector`, and then sorting the `vector`. 

```cpp
#include <bits/stdc++.h> 
using namespace std; 

bool sortbysec(const pair<string,int> &a, const pair<string,int> &b)
{ 
    if(a.second == b.second)
        return (a.first < b.first);

    return (a.second > b.second); 
} 

int main() 
{ 
    string str = "Today is a sunny day, isn't it a sunny day, today?"; 

    map<string, int> WordFrequency; 
    stringstream ss(str);  // Used for breaking words 
    string Word;  // To store individual words 

    while (ss >> Word) 
    { 
        // Remove all special characters from the word
        for(int i=0; i<Word.size(); i++)
            if(ispunct(Word[i]))
                Word.erase(i--);

        transform(Word.begin(), Word.end(), Word.begin(), ::tolower); //transform the word to lowercase 
        WordFrequency[Word]++; 
    } 

    vector<pair<string, int>> vec;

    copy(WordFrequency.begin(), WordFrequency.end(), back_inserter<vector<pair<string, int>>>(vec));

    sort(vec.begin(), vec.end(), sortbysec); 

    cout << "Words sorted by frequency and then lexicographically :\n";
    for (int i = 0; i < vec.size(); i++) 
        cout << vec[i].first << " : " << vec[i].second << '\n';

    return 0;
} 
```
This program first breaks the given string into individual words. For each word, it removes all special characters from the word and transforms the word to lowercase. It then counts the frequency of each word using a `map`. After counting the frequencies, it copies the `map` to a `vector`. It then sorts the `vector` based on the frequencies of the words and then lexicographically. After sorting, it prints the words along with their frequencies.

