class Solution {
public:
    int minPathSum(vector<vector<int>>& grid) {
        int m = grid.size();
        if (m == 0)
            return 0;
        int n = grid[0].size();
        if (n == 0)
            return 0;

        vector<vector<int>> dp(m, vector<int>(n, 0));
        dp[0][0] = grid[0][0];

        // Initialize the first row
        for (int i = 1; i < n; i++) {
            dp[0][i] = dp[0][i - 1] + grid[0][i];
        }

        // Initialize the first column
        for (int i = 1; i < m; i++) {
            dp[i][0] = dp[i - 1][0] + grid[i][0];
        }

        // Fill in the rest of the dp table
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = grid[i][j] + min(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        return dp[m - 1][n - 1];
    }
};
```

The solution uses dynamic programming to build a table `dp` where `dp[i][j]` represents the minimum sum of a path from the top-left cell to cell `(i, j)`. The minimum path sum to reach cell `(i, j)` is the sum of the value in cell `(i, j)` and the minimum of the path sum from the cell above `(i-1, j)` and the cell to the left `(i, j-1)`. Finally, the value at the bottom-right cell of the `dp` table is returned as the minimum path sum.

