#include<iostream>

// Function to implement the Euclidean algorithm
int gcd(int a, int b) {
    // Switch the order if a < b
    if (a < b) {
        return gcd(b, a);
    }

    // If b=0, a is the result
    if (b == 0) {
        return a;
    }

    // If not, repeat the process with b and the remainder of a/b
    else {
        return gcd(b, a % b);
    }
}

