```cpp
vector<int> topologicalSort(const vector<vector<int>>& graph) {
    int n = graph.size();
    vector<int> inDegree(n, 0);
    for (const auto& neighbors : graph) {
        for (int neighbor : neighbors) {
            inDegree[neighbor]++;
        }
    }

    queue<int> q;
    for (int i = 0; i < n; i++) {
        if (inDegree[i] == 0) {
            q.push(i);
        }
    }

    vector<int> result;
    while (!q.empty()) {
        int node = q.front();
        q.pop();
        result.push_back(node);
        for (int neighbor : graph[node]) {
            inDegree[neighbor]--;
            if (inDegree[neighbor] == 0) {
                q.push(neighbor);
            }
        }
    }

    if (result.size() != n) {
        return {};  // Graph contains a cycle
    }

    return result;
}
```

Here is the C++ program for the problem statement. This program uses vector and standard template library to solve the problem. It uses binary search to find the first and last occurrence of the specified value and calculates the minimum and maximum distances. Note that, the provided array should be sorted in ascending order as binary search operates on sorted arrays.

```cpp
#include<bits/stdc++.h>
using namespace std;

int binary_search_first(vector<int>& arr, int target) {
    int low = 0, high = arr.size() - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

int binary_search_last(vector<int>& arr, int target) {
    int low = 0, high = arr.size() - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] <= target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return high;
}

void solve(vector<int>& arr, int target) {
    int first = binary_search_first(arr, target);
    int last = binary_search_last(arr, target);
    if (first <= last) {
        cout << "Number " << target << " Found at indexes " << first << " to " << last << endl;
        cout << "Minimum distance: " << min(abs(target - arr[0]), abs(target - arr[last + 1])) << endl;
        cout << "Maximum distance: " << max(abs(target - arr[0]), abs(target - arr[arr.size() - 1])) << endl;
    } else {
        cout << "Number " << target << " not found" << endl;
    }
}

int main() {
    vector<int> arr = {2, 4, 6, 8, 8, 8, 10};
    int target = 8;
    solve(arr, target);
    return 0;
}
```

