using namespace std;

vector<string> separate_paren_groups(string paren_string)
{
    vector<string> paren_groups;
    int openParenCount = 0;
    size_t currentGroupStartPosition = 0;

    for(size_t i=0; i<paren_string.length(); i++)
    {
        if(paren_string[i] == '(')
