Here is the equivalent C++ code using a double pointer and a custom memory allocator:

```cpp
#include <iostream>
#include <cstdlib>

class CustomAllocator{
public:
    void* allocate(size_t size){
        void* memory = malloc(size* sizeof(int));
        if(!memory){
            std::cerr << "Memory allocation failed!\n";
            std::exit(EXIT_FAILURE);
        }
        return memory;
    }
    void deallocate(void* memory){
        free(memory);
    }
};

int main(){
    const int N=4;
    CustomAllocator allocator;
    int** arr = (int**)allocator.allocate(N* sizeof(int*));
    int* prod = (int*)allocator.allocate(sizeof(int));
    *prod = 1;
    for(int i=0;i<N;i++){
        arr[i] = (int*)allocator.allocate(sizeof(int));
        *arr[i] = (i+1)*5;
    }
    for(int i=0;i<N;i++){
        *prod *= *arr[i];
    }
    std::cout<<"The product is: "<<*prod<<std::endl;

    for(int i=0;i<N;i++){
        allocator.deallocate(arr[i]);
    }
    allocator.deallocate(arr);
    allocator.deallocate(prod);
    return 0;
}
```

