Here is a C++ program that simulate a doubly linked list data structure, with additional functions to merge two lists and reverse a list in-place:

```cpp
#include<iostream>
using namespace std;

struct Node {
    int val;
    Node *next, *prev;

    Node(int val) : val(val), next(NULL), prev(NULL) {}
};

class DoublyLinkedList {
public:
    Node *head, *tail;
    DoublyLinkedList() : head(NULL), tail(NULL) {}

    void append(int val) {
        if(head == NULL) {
            head = tail = new Node(val);
        } else {
            Node *node = new Node(val);
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    DoublyLinkedList* merge(DoublyLinkedList* list) {
        if(head == NULL) return list;
        if(list->head == NULL) return this;

        tail->next = list->head;
        list->head->prev = tail;
        tail = list->tail;

        delete list;
        return this;
    }

    void reverse() {
        Node *cur = head, *prevNode = NULL, *nextNode = NULL;

        while(cur != NULL) {
            nextNode = cur->next;
            cur->next = prevNode;
            cur->prev = nextNode;

            prevNode = cur;
            cur = nextNode;
        }

        tail = head;
        head = prevNode;
    }

    void printList() {
        if(head == NULL) return;
        Node* temp=head;
        while(temp)
        {
            cout<<temp->val<<" ";
            temp = temp->next;
        }
        cout<<endl;
    }
};

int main() {
    DoublyLinkedList list1;
    DoublyLinkedList list2;

    // Append data to the two lists
    for(int i = 1; i <= 5; i++) {
        list1.append(i);
    }
    for(int i = 6; i <= 10; ++i) {
        list2.append(i);
    }

    // Merge list1 and list2
    cout << "Merged Doubly Linked List: ";
    list1.merge(&list2);
    list1.printList();

    // Reverse the merged list in-place
    list1.reverse();
    cout << "Reversed Doubly Linked List: ";
    list1.printList();
    return 0;
}
```

This program defines a Node structure and a DoublyLinkedList class. The DoublyLinkedList class includes methods for appending values to the end of the list, merging two lists, and reversing a list in-place. Each operation maintains a time complexity of O(n), where n is the number of elements in the list. The reverse() method achieves this by using three pointers (cur, prevNode, and nextNode) to iteratively reverse the list. The main() function demonstrates these operations.

