#define SMALL_NUMBER 1e-10

std::vector<double> normalize(std::vector<double>& vec) {
   double length = 0.0;
   for(auto val : vec) {
      length += val * val;
   }

   length = sqrt(length);

   if(length < SMALL_NUMBER){
       throw std::invalid_argument("The given vector cannot be normalized, its length is zero.");
   }

   std::vector<double> result(vec.size());
   try{
       for(size_t i = 0; i < vec.size(); ++i) {
           result[i] = vec[i] / length;
       }
   } catch(std::bad_alloc& ba){
       throw std::runtime_error("Out of memory. Failed to allocate memory for the normalized vector.");
   } catch(...) {
       throw std::runtime_error("Unknown error occurred while generating normalized vector.");
   }

   return result;
}

