```c++
#include <iostream>
#include <stdexcept>

class Date {
    private:
        int day;
        int month;
        int year;
    public:
        Date(int d, int m, int y) : day(d), month(m), year(y) {
            if (!isValid()) 
                throw std::invalid_argument("Invalid date");
        }

        int getDay() { return day; }
        int getMonth() { return month; }
        int getYear() { return year; }

        static bool isLeapYear(int year) {
            // Leap year is exactly divisible by 4 except for end of century years.
            // They also must be divisible by 400. Hence, the year is a leap year if:
            // (Year is not divisible by 100 and is divisible by 4)
            // OR
            // (Year is divisible by 400)

            return ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0);
        }

        bool isValid() {
            if (day < 1 || day > 31) return false;
            if (month < 1 || month > 12) return false;
            // February can have 29 days in a leap year:
            if (month == 2) {
                return day <= (isLeapYear(year) ? 29 : 28);
            }
            // For April, June, September, and November, 
            // the number of days is 30:
            if (month == 4 || month == 6 || month == 9 || month == 11) {
                return day <= 30;
            }
            return true;
        }
};

int main() {
    int d, m, y;
    std::cout << "Enter day, month, year: ";
    std::cin >> d >> m >> y;
    try {
        Date date(d, m, y);
        std::cout << "Date is valid.\n";
        if (Date::isLeapYear(y)) {
            std::cout << y << " is a leap year.\n";
        } else {
            std::cout << y << " is not a leap year.\n";
        }

    } catch (const std::invalid_argument &e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    return 0;
}
```

