```cpp
#include<iostream>
#include<vector>

using namespace std;

int linearSearch(const vector<int>& arr, int val, int boundary)
{
    for (int i = 0; i < arr.size(); ++i)
    {
        if (arr[i] == val)
            return i; // return index of the found element
        if (arr[i] > boundary) 
            return -2; // array elements have crossed boundary, break the search
    }
    return -1; // return -1 if element not found
}

int main()
{
    int n;
    cout << "Enter the number of elements: ";
    cin >> n;
    vector<int> arr(n);
    cout << "Enter elements of array in ascending order:" << endl;
    for (int& el : arr)
        cin >> el;

    int val;
    cout << "Enter the element to be searched: ";
    cin >> val;

    int boundary;
    cout << "Enter the boundary value: ";
    cin >> boundary;

    int res = linearSearch(arr, val, boundary);

    if(res == -1)
        cout << "Element not found in array" << endl;
    else if(res == -2)
        cout << "Search stopped as array values exceeded boundary" << endl;
    else
        cout << "Element found at index: " << (res+1) << endl;

    return 0;
}
```

