int matrixSum(Cell const* M, int n) {
  int sum = 0;
  const Cell* currentRow = M;

  // Iterate through each row
  for (int i = 0; i < n; ++i) {
    const Cell* currentCell = currentRow;

    // Iterate through each cell in the row
    while (currentCell) {
      sum += currentCell->value;
      currentCell = currentCell->right;
