public class DijkstraAlgorithm {
    public static void dijkstra(int source, List<List<int[]>> adj, int[] dist) {
        int n = adj.size();
        boolean[] visited = new boolean[n];
        int[][] q = new int[n][3]; // {node, parent, distance}
        int r = 1;
        q[0][0] = source;
        q[0][1] = -1;
        q[0][2] = 0;

