using namespace std;

struct Node {
    int data;
    Node *left;
    Node *right;
    Node *random;
    Node(int val) : data(val), left(nullptr), right(nullptr), random(nullptr) {}
};

Node* newNode(int data)
{
    Node* temp = new Node(data);
    return temp;
}

Node* sortedArrayToBST(vector<int> &arr, int start, int end) {
    if (start > end) {
        return nullptr;
    }

    int mid = (start + end) / 2;
    Node* root = newNode(arr[mid]);

    root->left = sortedArrayToBST(arr, start, mid - 1);

    root->right = sortedArrayToBST(arr, mid + 1, end);

    return root;
}

Node* buildRandom(Node* root, unordered_map<Node*, Node*> &node_map)
{
    if (!root) {
        return nullptr;
    }

    Node* left = buildRandom(root->left, node_map);
    Node* right = buildRandom(root->right, node_map);

    Node* node = newNode(root->data);
    node->left = left;
    node->right = right;
    node->random = node_map[root->random];

    return node;
}

bool findPath(Node* root, vector<Node*> &path, int target)
{
    if (!root) {
        return false;
    }

    path.push_back(root);

    if (root->data == target) {
        return true;
    }

    if ((root->left && findPath(root->left, path, target)) || (root->right && findPath(root->right, path, target))) {
        return true;
    }

    path.pop_back();
    return false;
}

Node* findLCA(Node* root, int a, int b, int c)
{
    vector<Node*> path_a, path_b, path_c;

    if (!findPath(root, path_a, a) || !findPath(root, path_b, b) || !findPath(root, path_c, c)) {
        return nullptr;
    }

    Node* lca = nullptr;

    for (size_t i = 0; i < path_a.size() && i < path_b.size() && i < path_c.size(); ++i) {
        if (path_a[i] == path_b[i] && path_b[i] == path_c[i]) {
            lca = path_a[i];
        } else {
            break;
        }
    }

    return lca;
}

int main()
{
    srand(time(0));

    int arr[] = {1, 2, 3, 4, 5, 6, 7, 8, 9};

    int n = sizeof(arr) / sizeof(arr[0]);

    vector<int> vec(arr, arr + n);

    Node* root = sortedArrayToBST(vec, 0, vec.size() - 1);
    root->random = root->right;

    unordered_map<Node*, Node*> node_map;

    buildRandom(root, node_map);

    int a = 1;
    int b = 6;
    int c = 8;

    Node* lca = findLCA(root, a, b, c);

    cout << "LCA of " << a << ", " << b << ", and " << c << " is " << lca->data << endl;

    return 0;
}
