Here's a basic implementation of C++ program to classify data using k-Nearest Neighbors algorithm:

Assumptions are, we have a 2D data-set with 2 classes, and we use Euclidean distance for distance measure. 

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <queue>
#include <utility>

struct Point {
    double x, y;
    int group;
};

struct CompareDist {
    bool operator()(std::pair<Point, double> p1, std::pair<Point, double> p2) {
        return p1.second < p2.second;
    }
};

int ClassifyPoint(std::vector<Point>& points, int P, int k) {
    std::priority_queue<std::pair<Point, double>, std::vector<std::pair<Point, double>>, CompareDist> pq;
    for (int i = 0; i < points.size(); i++) {
        double distance = sqrt(powl(points[i].x - points[P].x, 2) + powl(points[i].y - points[P].y, 2));
        pq.push(std::make_pair(points[i], distance));
        if (pq.size() > k) {
            pq.pop();
        }
    }

    int freq1 = 0;  
    int freq2 = 0;  
    while (!pq.empty()) {
        if (pq.top().first.group == 0)
            freq1++;
        else if (pq.top().first.group == 1)
            freq2++;
        pq.pop();
    }

    return (freq1 > freq2 ? 0 : 1);
}

int main() {
    std::vector<Point> points = { {2.5, 7,  0}, {5.1, 2.2, 1}, {3.3, 3.3, 0}, {2.1, 2.9, 1}, {2.6, 1.6, 1}, 
                                  {7.4, 2.8, 0}, {5.7, 3.5, 1}, {9.2, 2.5, 0}, {7.8, 3.4, 1}, {7.9, 0.8, 1}, 
                                  {4.2, 7.2, 0}, {9.1, 3.1, 1}, {5.2, 4.5, 0}, {1.0, 2.5, 1}, {6, 0.5, 1} };
    Point unknown = { 4.3, 2.7, 0 };
    points.push_back(unknown);
    unknown.group = ClassifyPoint(points, points.size() - 1, 3);
    std::cout << "The predicted class of the point (" << unknown.x << ", " << unknown.y << ") is: " << unknown.group << '\n';
    return 0;
}
```
This program first calculates the distance between the input point and each point in the dataset, and it keeps a priority queue of a pair of point and distance. Then, it counts the number of points in each class within the closest "k" points in the queue. It finally says which class the point belongs to, depending on which class has the majority among the "k" closest points.

