Using purely C/C++ Windows APIs and without using any third-party libraries, you can create a ZIP file by using the `CreateFile` and `WriteFile` functions along with an understanding of the ZIP file format. But this would be awkward, tiresome and daunting as it would require you to manually implement a file compression algorithm.

Unluckily, Windows API does not have built-in functions specifically for creating ZIP files unlike VBScript or .NET. Working with compressed files usually involves third-party libraries like zip lib, minizip, libzip, etc.

However, there is a workaround. You can call Shell Objects like Shell.Application (used in VBScript) from C/C++ via COM interface. Shell32.dll actually exposes the compressing functionality. Here is an example:

```cpp
#include <windows.h>
#include <shlobj.h>
#include <exdisp.h>
#include <shldisp.h>
#pragma comment(lib, "shell32.lib")

void ZipFolder(LPWSTR pszFolderSrc, LPWSTR pszZipFile)
{
    IShellDispatch *pISD;
    Folder  *pToFolder = NULL;
    BSTR  bstrZipFile = SysAllocString(pszZipFile);
    VARIANT vDir, vFile, vOpt;
    HRESULT hr;

    CoInitialize(NULL);
    hr = CoCreateInstance(CLSID_Shell, NULL, CLSCTX_INPROC_SERVER, IID_IShellDispatch, (void **)&pISD);

    if (SUCCEEDED(hr))
    {
        VariantInit(&vDir);
        vDir.vt = VT_BSTR;
        vDir.bstrVal = SysAllocString(pszFolderSrc);

        hr = pISD->NameSpace(vDir, &pToFolder);

        if (SUCCEEDED(hr))
        {
            VariantInit(&vOpt);
            vOpt.vt = VT_I4;
            vOpt.lVal = 20; // compression option

            VariantInit(&vFile);
            vFile.vt = VT_BSTR;
            vFile.bstrVal = bstrZipFile;

            // From Folder to another (zip file)
            hr = pToFolder->CopyHere(vFile, vOpt);

            // handle errors
            if (FAILED(hr)) {
               // your error handling code here
            }
        }
        pISD->Release();
    }
    SysFreeString(bstrZipFile);
    CoUninitialize(); 
}

