#include <iostream>
#include <algorithm>
#include <vector>

// Function to perform Binary Search
int binarySearch(std::vector<int> &arr, int num) {
  int low = 0;
  int high = arr.size() - 1;

  while (low <= high) {
    int mid = low + (high - low) / 2;

    if (arr[mid] == num) {
      return mid; 
    }

    if (arr[mid] < num) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return -1;
}

int main() {
  std::vector<int> arr = {93, 7, 65, 100, 31, 2, 48, 75, 53, 200};

  // Sort the vector
  std::sort(arr.begin(), arr.end());

  int num = 65;  // Number to search in array
  int result = binarySearch(arr, num);

  if(result != -1) {
    std::cout << "Element found at index: " << result << std::endl;
  } else {
    std::cout << "Element not found in array" << std::endl;
  }

  return 0;
}
```

