public int shortestPath(boolean[][] maze) {
    int m = maze.length;
    int n = maze[0].length;

    int[][] distance = new int[m][n];
    for (int i = 0; i < m; i++) {
        Arrays.fill(distance[i], Integer.MAX_VALUE);
    }

    int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(new int[]{0, 0});
    distance[0][0] = 1;

    while (!queue.isEmpty()) {
        int[] curr = queue.poll();
        int x = curr[0];
        int y = curr[1];

        for (int[] dir : directions) {
            int newX = x + dir[0];
            int newY = y + dir[1];
            if (newX >= 0 && newX < m && newY >= 0 && newY < n && maze[newX][newY] && distance[newX][newY] > distance[x][y] + 1) {
                distance[newX][newY] = distance[x][y] + 1;
                queue.offer(new int[]{newX, newY});
            }
        }
    }

    return distance[m - 1][n - 1] == Integer.MAX_VALUE ? -1 : distance[m - 1][n - 1];
}
