// A function to factorize a number. It returns a pair: a map representing factors and their counts, 
// and bool to check if total product of computed factors equals n
pair<map<int, int>, bool> factorize(int n){
    map<int, int> factors;
    int total_product = 1;

    if(n % 2 == 0) factors[2] = 0;      
    while(n % 2 == 0){                 // Keep dividing n by 2 as long as it is divisible
        n /= 2;                       
        factors[2] += 1;               
    }
    total_product *= pow(2, factors[2]);  // multiply the product by 2 raised to the power of count of 2

    for(int i = 3; i <= sqrt(n); i += 2){  // Now check for odd factors starting from 3 till square root of n
        if(n % i == 0) factors[i] = 0;      
        while(n % i == 0){                  // Keep dividing n by i as long as it is divisible
            n /= i;                        
            factors[i] += 1;                
        }
        total_product *= pow(i, factors[i]); // multiply the product by i raised to the power of count of i
    }

    if(n > 1){                            // If n is still greater than 1, it means it itself is a prime number
        factors[n] = 1;
        total_product *= n;                // multiply the product by n
    }
    return make_pair(factors, total_product == n);    // return the pair of factors and the boolean
