```C++

#include <iostream>
using namespace std;


class Node {
public:
    int data;
    Node* next;
};

// Function to add node at the end of the list.
void append(Node** head_ref, int new_data) {
    //creating new node
    Node* new_node = new Node();
    new_node->data = new_data;

    //If Linked List is empty, then make the new node as head
    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }

    // Else traverse till the last node
    Node* last = *head_ref;
    while (last->next != NULL) {
        last = last->next;
    }

    // Insert the new_node at last node
    last->next = new_node;
}

// function to move searched node to the front of the list
void moveToFront(Node** head_ref, int x) {
    // Base case for the recursion
    if (*head_ref == NULL || (*head_ref)->data == x)
        return;

    // Else, keep searching recursively
    Node* prev = NULL;
    Node* curr = *head_ref;
    while (curr->next != NULL && curr->data != x){
        prev = curr;
        curr = curr->next;
    }

    // If the node with the value x is not found in the list
    if(curr->data != x) {
        append(head_ref, x);
    }
    // If node with value x is found, move it to the front
    else {
        prev->next = curr->next;
        curr->next = *head_ref;
        *head_ref = curr;
    }
}

// Function to print linked list
void printList(Node *node) {
    while (node != NULL){
        cout<<" "<<node->data;
        node = node->next;
    }
    cout << "\n";
}

