There are different ways to solve the problem of finding the median in a linked list. The most straight forward approach would be to first sort the linked list and then simply find the median. The following C++ program uses this approach by employing a priority queue for sorting:

```C++
#include <queue>
#include <iostream>

struct Node{
    int data;
    Node* next;
};

Node* sortedInsert(Node* head, int data){
    Node* newNode = new Node;
    newNode->data = data;

    if(head == NULL || head->data >= newNode->data){
        newNode->next = head;
        head = newNode;
    }else{
        Node* current = head;
        while(current->next != NULL && current->next->data < newNode->data ){
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
    return head;
}

double findMedian(Node* head){
    Node* temp = head;
    std::priority_queue<int> pq;

    while(temp != NULL){
        pq.push(temp->data);
        temp = temp->next;
    }

    int len = pq.size();
    for(int i = 0; i < len/2; i++)
        pq.pop();

    if(len%2 == 0){
        int a = pq.top();
        pq.pop();
        return (a + pq.top()) / 2.0;
    }else{
        return pq.top();
    }
}

int main(){
    Node* head = NULL;
    head = sortedInsert(head, 10);
    head = sortedInsert(head, 8);
    head = sortedInsert(head, 6);
    head = sortedInsert(head, 15);
    head = sortedInsert(head, 12);

    std::cout << "Median: " << findMedian(head) << std::endl;
    return 0;
}
```

Please, note that the C++ linked list implementation could be simplified, but in order to answer your question with sufficient context, I included a complete example of sorting and finding the median in a linked list.

This code first sorts the linked list by calling the `sortedInsert` function for each element in the list. Then it creates a priority queue with all the elements in the linked list. It then pops off half of the elements in the queue. If the linked list contains an odd number of elements, the top of the queue is the median. If the linked list contains an even number of elements, the median is the average of the top two elements in the queue. The function `findMedian` returns the median as a double.

