    DoublyLinkedList(){
        this->head = nullptr;
        this->tail = nullptr;
    }
    void addNode(int data){
        Node* newNode = new Node(data);
        if(this->head == nullptr){
            this->head = newNode;
            this->tail = newNode;
        }
        else{
            newNode->prev = this->tail;
            this->tail->next = newNode;
            this->tail = newNode;
        }
    }
