```c++
#include <cmath>

// Function to check number is prime or not
bool isPrime(int num) {
    if(num <= 1) {
        return false;
    }
    for(int i = 2; i <= sqrt(num); i++) {
        if(num % i == 0) {
            return false;
        }
    }
    return true;
}

// Function to check number is composite or not
bool isComposite(int num) {
    if(num <= 1) {
        return false;
    }
    for(int i = 2; i <= sqrt(num); i++) {
        if(num % i == 0) {
            return true;
        }
    }
    return false;
}

bool prime_composite_ascii_sum(string str1, string str2){
    int sum1 = 0, sum2 = 0;
    for(auto i : str1) {
        sum1 += i;
    }
    for(auto i : str2) {
        sum2 += i;
    }

    if(isPrime(sum1) && isComposite(sum2)) {
        return true;
    } else {
        return false;
    }
}
