C++ doesn't have built-in linked lists like python or java. We have to create our own node structure and supply the sorting operation which will be used on it.
Below is a simple implementation:

```C++
#include <iostream>
#include <fstream>
#include <cstdlib>

using namespace std;

struct Node {
    int data;
    Node* next;
};

Node* head;

void Insert(int data) {
    Node* tmp = new Node;
    tmp->data = data;
    tmp->next = head;
    head = tmp;
}

void BubbleSort(Node* &head) {
    if (head == NULL || head->next == NULL)
        return;

    for(Node *i = head; i != NULL; i = i->next) {
        for(Node *j = i->next; j != NULL; j = j->next) {
            if(i->data > j->data) {
                swap(i->data, j->data);
            }
        }
    }
}

void print() {
    Node* temp = head;
    while(temp != NULL) {
        cout << temp->data << " ";
        temp = temp->next;
    }
    cout << "\n";
}

void writeDataToFile(Node* head) {
    ofstream output_file;
    output_file.open("output.txt");
    Node* temp = head;
    while(temp != NULL) {
        output_file << temp->data << " ";
        temp = temp->next;
    }
    output_file << "\n";
    output_file.close();
}

int main() {
    head = NULL; // empty list
    ifstream file("input.txt");
    if(file.is_open()) {
        int value;
        while (file >> value) {
            Insert(value);
        }
        file.close();
    }
    else {
        cout << "Unable to open the file";
        return 0;
    }

    BubbleSort(head);
    print();
    writeDataToFile(head);

    // deallocate memory
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        delete temp;
    }

    return 0;
}
```

This program reads integers from a file named "input.txt", inserts them into a linked list, sorts the linked list using bubble sort, then prints the sorted list to the console and writes these values ​​to "output.txt". This program also tidies up the linked list nodes in order to not have memory leaks.

Note: Make sure the file "input.txt" is existing and contains the data you want to sort. However, this program still has a time complexity of O(n^2), which is the best complexity we can achieve with bubble sort.

