class Quaternion {
private:
    double a, b, c, d;
public:
    Quaternion(double a, double b, double c, double d) : a(a), b(b), c(c), d(d) {
        // Input validation
        if (std::isnan(a) || std::isnan(b) || std::isnan(c) || std::isnan(d)) {
            throw std::invalid_argument("Not valid quaternion coefficients!");
        }
    }

    Quaternion operator+(const Quaternion& q) const {
        return Quaternion(a + q.a, b + q.b, c + q.c, d + q.d);
    }

    Quaternion operator-(const Quaternion& q) const {
        return Quaternion(a - q.a, b - q.b, c - q.c, d - q.d);
    }

    Quaternion operator*(const Quaternion& q) const {
        return Quaternion(
            a * q.a - b * q.b - c * q.c - d * q.d,
            a * q.b + b * q.a + c * q.d - d * q.c,
            a * q.c - b * q.d + c * q.a + d * q.b,
            a * q.d + b * q.c - c * q.b + d * q.a
        );
    }

    Quaternion operator!() const {
        return Quaternion(a, -b, -c, -d);
    }

    Quaternion inverse() const {
        double magnitudeSquared = a * a + b * b + c * c + d * d;
        if (magnitudeSquared == 0) {
            throw std::invalid_argument("Cannot compute the inverse of a quaternion with zero magnitude");
        }
        return Quaternion(a / magnitudeSquared, -b / magnitudeSquared, -c / magnitudeSquared, -d / magnitudeSquared);
    }

    double magnitude() const {
        return std::sqrt(a * a + b * b + c * c + d * d);
    }

    std::string toString() const {
        return "(" + std::to_string(a) + ", " + std::to_string(b) + ", " + std::to_string(c) + ", " + std::to_string(d) + ")";
    }
};
```

