int findMinMax(int arr[], int n, bool whetherToFindMin) {
    // Initialize the result as first element
    int result = arr[0];

    // Do linear search for the find min/max in the array 
    for (int i = 1; i < n; i++) {
        if(whetherToFindMin) {
            // Find min from the array
            if(arr[i] < result) {
                result = arr[i];
            }
        } else {
            // Find max from the array
            if(arr[i] > result) {
                result = arr[i];
            }
        }
    }

    // Return the final result
    return result;
}
