```c++
#include<iostream>
#include<vector>
#include<algorithm>

using namespace std;

bool exceeds_limit_sum(vector<float> numbers, float limit)
{
    sort(numbers.begin(), numbers.end());

    int i = 0;
    int j = numbers.size() - 1;

    while (i < j)
    {
        if (numbers[i] + numbers[j] > limit)
            return true;
        (numbers[i] + numbers[j] > limit) ? j-- : i++;
    }
    return false;
}

int main()
{
    cout << exceeds_limit_sum({1.0, 2.8, 3.2, 4.5, 5.0, 2.0}, 4.5) << "\n"; // It should print 1
    cout << exceeds_limit_sum({1.0, 2.0, 3.0}, 5.0) << "\n"; // It should print 0
    return 0;
}
