using namespace std;

// Function to compute sum of digits 
int getSum(int n)
{
    int sum = 0;
    while (n != 0)
    {
        sum = sum + abs(n % 10);
        n = n / 10;
    }
    return sum;
}

// Function to implement sort
vector<int> sort_array(vector<int> arr)
{
    // Custom comparator to sort numbers 
