```C++
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int partition(vector<int>& arr, int low, int high) {
    int pivot = arr[high];
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(arr[i], arr[j]);
        }
    }
    swap(arr[i + 1], arr[high]);
    return (i + 1);
}

int quickselect(vector<int>& arr, int low, int high, int k) {
    if (low == high) 
        return arr[low];

    int pivot_index = partition(arr, low, high);

    if (k == pivot_index)
        return arr[k];
    else if (k < pivot_index)
        return quickselect(arr, low, pivot_index - 1, k);
    else
        return quickselect(arr, pivot_index + 1, high, k);
}

float median(vector<int> arr) {
    int size = arr.size();
    float median;
    if (size % 2 != 0)
        median = quickselect(arr, 0, size - 1, size / 2);
    else
        median = 0.5 * (quickselect(arr, 0, size - 1, size / 2 - 1) +
                        quickselect(arr, 0, size - 1, size / 2));
    return median;
}

