#include <string>
#include <algorithm>

std::vector<std::vector<size_t>> findPatternOccurrences(const std::string& text, const std::vector<std::string>& patterns, size_t chunkSize) {
    size_t strLen = text.length();
    size_t pattCnt = patterns.size();
    std::vector<std::vector<size_t>> occurrences(pattCnt);

    for (size_t chunk = 0; chunk < strLen; chunk += chunkSize) {
        size_t chunkEnd = std::min(chunk + chunkSize, strLen);
        std::string textChunked = text.substr(chunk, chunkEnd - chunk);

        for (size_t patt = 0; patt < pattCnt; patt++) {
            size_t pos = 0;
            while ((pos = textChunked.find(patterns[patt], pos)) != std::string::npos) {
                occurrences[patt].push_back(chunk + pos);
                pos += patterns[patt].length();
            }
        }
    }

    return occurrences;
}

int main() {
    std::string text = "abracadabra";
    std::vector<std::string> patterns = {"abr", "cad"};
    size_t chunkSize = 5;

    std::vector<std::vector<size_t>> result = findPatternOccurrences(text, patterns, chunkSize);

    for (size_t i = 0; i < result.size(); i++) {
        std::cout << "Occurrences of pattern " << patterns[i] << ": ";
        for (size_t j = 0; j < result[i].size(); j++) {
            std::cout << result[i][j] << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
```

