using namespace std;

bool hasPath(vector<vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    vector<pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    queue<pair<int, int>> q;
    q.push({0, 0});
    grid[0][0] = 1; // Mark the starting cell as visited

    while (!q.empty()) {
        pair<int, int> current = q.front();
        q.pop();

        if (current.first == m - 1 && current.second == n - 1) {
            return true; // Reached the bottom-right corner
        }

        for (const auto& direction : directions) {
            int nextRow = current.first + direction.first;
            int nextColumn = current.second + direction.second;

            if (nextRow >= 0 && nextRow < m && nextColumn >= 0 && nextColumn < n && grid[nextRow][nextColumn] == 0) {
                q.push({nextRow, nextColumn});
                grid[nextRow][nextColumn] = 1; // Mark the cell as visited
            }
        }
    }

    return false; // No path found to the bottom-right corner
}
