template <typename T> 
class DoublyLinkedList {
    Node<T>* head; 
    Node<T>* tail;
public:
    DoublyLinkedList() : head(NULL), tail(NULL) {}

    ~DoublyLinkedList() {
        while (head) {
            Node<T>* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void insertAtEnd(T value) {
        Node<T>* newNode = new Node<T>;
        newNode->data = value;
        newNode->next = NULL;
        newNode->prev = tail;

        if (tail) tail->next = newNode;
        else head = newNode;

        tail = newNode;
    }

    void insertAtBegin(T value) {
        Node<T>* newNode = new Node<T>;
        newNode->data = value;
        newNode->prev = NULL;
        newNode->next = head;

        if (head) head->prev = newNode;
        else tail = newNode;

        head = newNode;
    }

    void deleteFromBegin() {
        if (!head) throw "Error: list is empty!";
        Node<T>* temp = head;
        head = head->next;
        if (head) head->prev = NULL;
        else tail = NULL;
        delete temp;
    }

    void deleteFromEnd() {
        if (!tail) throw "Error: list is empty!";
        Node<T>* temp = tail;
        tail = tail->prev;
        if (tail) tail->next = NULL;
        else head = NULL;
        delete temp;
    }

    void displayForward() {
        Node<T>* temp = head;
        while (temp) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << endl;
    }

    void displayReverse() {
        Node<T>* temp = tail;
        while (temp) {
            cout << temp->data << " ";
            temp = temp->prev;
        }
        cout << endl;
    }
};
