string reverseWords(string str) {
    string reversed_str = "";
    string temp = "";
    for (int i = 0; i < str.length(); i++) {
        if (str[i] == ' ') {
            reversed_str += temp;
            temp = "";
        } else {
            temp = str[i] + temp;
        }
    }
    reversed_str += temp;
    return reversed_str;
