#include<iostream>
#include<string>
#include<vector>

std::string longest_common_substring(const std::string& a, const std::string& b) {
    std::vector<std::vector<int>> dp(a.length() + 1, std::vector<int>(b.length() + 1, 0));

    int max_len = 0;
    int end_pos = 0;

    for (int i = 1; i <= a.length(); i++) {
        for (int j = 1; j <= b.length(); j++) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if (dp[i][j] > max_len) {
                    max_len = dp[i][j];
                    end_pos = i - 1;
                }
            }
        }
    }

    return a.substr(end_pos - max_len + 1, max_len);
}

int main() {
    std::string a, b;
    std::cout << "Enter first string: ";
    std::cin >> a;
    std::cout << "Enter second string: ";
    std::cin >> b;

    std::string lcs = longest_common_substring(a, b);

    std::cout << "Longest common substring is: " << lcs << "\n";

    return 0;
}
