bool is_nested(std::string str) {
    std::stack<char> stack;
    std::unordered_map<char, char> mapping = {{')', '('}, {']', '['}, {'}', '{'}};

    for(auto& ch : str) {
        if(mapping[ch]) { // If it's a closing bracket
            if(stack.empty() || mapping[ch] != stack.top()) {
                return false;
            }
            stack.pop();
        } else { // If it's an opening bracket, push onto stack
            stack.push(ch);
        }
    }

    return stack.empty(); // If the stack is empty at the end, all brackets are properly matched
}

int main() {
