    std::cout << is_nested("{[[]]}") << std::endl;   // true
    std::cout << is_nested("[]{]]]]][[[[[]") << std::endl;   // false
    std::cout << is_nested("{[()]})") << std::endl;   // false
    std::cout << is_nested("(())") << std::endl;   // true
    std::cout << is_nested("[([])]") << std::endl;  // true
    std::cout << is_nested("([)]") << std::endl;  // false
    return 0;
}
