// Get the longest matching fruit
string getLongestString(vector<string> fruitList, vector<string> fruitNames){
    string longestFruit = "";
    set<string> fruitSet;

    // converting to set for faster lookup
    // also converting to lowercase for case insensitive comparison
    for (string fruit: fruitNames) 
        fruitSet.insert(toLowerCase(fruit));

    // iterating over the fruitList
    for (string fruit: fruitList) {
        // convert given fruit to lowercase
        fruit = toLowerCase(fruit);
        // check if the fruit is in the fruitNames set
        // also check if fruit without 's' is in the set to account for plurality
        if(fruitSet.count(fruit) || (fruit.back() == 's' && fruitSet.count(fruit.substr(0,fruit.length()-1)))){
            // update longestFruit if current fruit is longer
            if(fruit.length() > longestFruit.length()) 
                longestFruit = fruit;
        }
    }

    // if no match found return appropriate message
    if(longestFruit == "") 
        return "No matching fruit found!";
    else
        return longestFruit;
}

