class CustomString {
private:
    std::string* data;
    int* refCount;

public:
    CustomString(const std::string& str) : data(new std::string(str)), refCount(new int(1)) {}

    CustomString(const CustomString& other) : data(other.data), refCount(other.refCount) {
        (*refCount)++;
    }

    CustomString& operator=(const CustomString& other) {
        if (this != &other) {
            if (--(*refCount) == 0) {
                delete data;
                delete refCount;
            }
            data = other.data;
            refCount = other.refCount;
            (*refCount)++;
        }
        return *this;
    }

    ~CustomString() {
        if (--(*refCount) == 0) {
            delete data;
            delete refCount;
        }
    }

    int refs() const {
        return *refCount;
    }
};

