```cpp
#include <string>
#include <sstream>
#include <unordered_map>

std::string extractConfigValue(const std::string& configFile, const std::string& key) {
    std::unordered_map<std::string, std::string> configMap;
    std::istringstream iss(configFile);
    std::string line;

    while (std::getline(iss, line)) {
        size_t commentPos = line.find("//");
        if (commentPos != std::string::npos) {
            line = line.substr(0, commentPos); // Remove comments
        }

        size_t keyValuePos = line.find("=");
        if (keyValuePos != std::string::npos) {
            std::string configKey = line.substr(0, keyValuePos);
            std::string configValue = line.substr(keyValuePos + 1);
            configMap[configKey] = configValue;
        }
    }

    auto it = configMap.find(key);
    if (it != configMap.end()) {
        return it->second;
    } else {
        return ""; // Key not found
    }
}
```

