Here's a simple C++ implementation:

```cpp
#include <bits/stdc++.h>
using namespace std;

// A doubly linked list node
struct Node {
    int data;
    Node* next;
    Node* prev;
};

// adds a new node at the end of the linked list
void append(Node** head_ref, int new_data) {
    Node* new_node = new Node;
    Node* last = *head_ref;
    new_node->data = new_data;
    new_node->next = NULL;

    if (*head_ref == NULL) {
        new_node->prev = NULL;
        *head_ref = new_node;
        return;
    }

    while (last->next != NULL) {
        last = last->next;
    }

    last->next = new_node;
    new_node->prev = last;
}

// delete node from the list, here x is the value of the node to be deleted
void deleteNode(Node** head_ref, int x) {
    if (*head_ref == NULL) {
        return;
    }

    Node* temp = *head_ref;
    while (temp != NULL) {
        if (temp->data == x) {
            // this condition checks if the node to be deleted is the head node.
            if (temp == *head_ref) {
                *head_ref = temp->next;  // the head node is moved to next
            }

            // this condition checks if the node to be deleted has a previous node.
            if (temp->prev != NULL) {
                temp->prev->next = temp->next;
            }

            // this condition checks if the node to be deleted has a next node.
            if (temp->next != NULL) {
                temp->next->prev = temp->prev;
            }

            delete temp;
            return;
        }
        temp = temp->next;
    }
}

// display the list
void display(Node* node) {
    while (node != NULL) {
        cout << node->data << " ";
        node = node->next;
    }
}

int main() {
    Node* head = NULL;

    append(&head, 20);
    append(&head, 30);
    append(&head, 40);
    append(&head, 50);
    append(&head, 60);

    cout << "Original list: " << endl;
    display(head);
    cout << endl;

    int del_val = 30;
    deleteNode(&head, del_val);

    cout << "Modified list after deleting " << del_val << ": " << endl;
    display(head);

    return 0;
}
```
This code will remove the node with the value that you choose. When executing the deleteNode() function, the value of the node to be deleted should be given as an argument. Also, the append() function will add data at the end of your list. Display() will display your complete list.

Please note that we traverse the doubly linked list and whenever we find the node with the given value, we remove it. This operation takes O(n) time, where n is the number of nodes in doubly linked list. Since we need to modify previous and next for removing a node, doubly link list is a better suited data structure than singly linked list in this case.

This problem involves finding the median value from an explicit collection of 12 numbers. In C++, we can solve this problem easily by sorting the array of floats and then locating the median value.

The idea is to sort the numbers in ascending order. If the total number of numbers is even (like in your case), we take the average value of the two middle numbers. 

Here is a simple program to solve this problem. 

```C++
#include<iostream>
#include<algorithm>
using namespace std;

int main() {
    float vec[] = {1.2, 3.5, 4.1, 6.7, 7.9, 9.0, 11.2, 14.3, 15.8, 18.4, 22.5, 27.0};

    int n = sizeof(vec) / sizeof(vec[0]);

    //Sort the array
    sort(vec, vec+n);

    //Find the median
    float median = 0;
    if(n % 2 != 0)
        median = vec[n/2];
    else
        median = (vec[(n-1)/2] + vec[n/2])/2;

    cout<<"Median: "<<median<<endl;

    return 0;
}
```
This code will output: "Median: 10.6"
This result comes from average between 9.0 and 11.2 - the middle two numbers of sorted array.

