    Node* head = nullptr;

    insert(head, 5);
    insert(head, 2);
    insert(head, 7);
    insert(head, 1);
    insert(head, 9);
    insert(head, 0);

    printList(head); // Output: 0 1 2 5 7 9

    return 0;
}
```

