Here's an example C++ template function for removing a node from a doubly linked list by its value. I use a struct to define the node in the linked list. For unit tests, I use simple output comparison, however, more robust and comprehensive tests should be designed.

```cpp
#include<iostream>

template<typename T>
struct Node{
    T value;
    Node* next;
    Node* prev;
};

template<typename T>
class LinkedList{
    Node<T>* head;
public:
    LinkedList(): head(NULL) {};
    void push(T value);
    void remove(T value);
    void printList();
};

template<typename T>
void LinkedList<T>::push(T value){
    Node<T>* new_node = new Node<T>;
    new_node->value = value;
    new_node->next = head;
    new_node->prev = NULL;
    if(head != NULL)
        head->prev = new_node;
    head = new_node;
}

template<typename T>
void LinkedList<T>::remove(T value){
    Node<T>* temp = head;
    while(temp != NULL){
        if(temp->value == value){
            if(temp->prev != NULL)
                temp->prev->next = temp->next;
            if(temp->next != NULL)
                temp->next->prev = temp->prev;
            if(temp == head)
                head = temp->next;
            delete temp;
            remove(value);
            return;
        }
        temp = temp->next;
    }
}

template<typename T>
void LinkedList<T>::printList(){
    Node<T>* temp = head;
    while(temp != NULL){
        std::cout << temp->value << " ";
        temp = temp->next;
    }
    std::cout << std::endl;
}

