// Function prototype
double getRandomNumber();

int main() {
    // Seed the random number generator with the current time
    srand(static_cast<unsigned int>(time(0)));

    // Generate and print 10 random numbers
    for(int i=0; i<10; i++) {
        std::cout << getRandomNumber() << std::endl;
    }

    return 0;
}

