using namespace std;

double median(vector<float> numbers){
    size_t size = numbers.size();
    if(size == 0) return 0;    // Empty vector
    sort(numbers.begin(), numbers.end());
    if(size % 2 == 0) return (numbers[size / 2 - 1] + numbers[size / 2]) / 2;
    else return numbers[size / 2];
}

void calculate_deviations(vector<float> numbers){
    if(numbers.empty()){
        printf("Input Vector is Empty \n");
        return;
    }

    float sum = 0;
    float medianVal = median(numbers);

    for(int i=0; i<numbers.size(); i++){
        sum += numbers[i];
    }

    float mean = sum/numbers.size();

    float Mad = 0;
    vector<float> MedAD(numbers.size());

    for(int i=0; i<numbers.size(); i++){
        Mad += abs(numbers[i] - mean);
        MedAD[i] = abs(numbers[i] - medianVal);
    }

    Mad /= numbers.size();

