Here's a solution written in C++. It calculates each extension's strength by iterating over the characters in the extension, checking if each one is uppercase or lowercase, and incrementing/decrementing a count accordingly. It then checks if this strength is higher than the current highest strength, and updates the strongest extension if it is.

```cpp
#include <stdio.h>
#include <vector>
#include <string>
using namespace std;

string Strongest_Extension(string class_name, vector<string> extensions) {
    int maxStrength = -1000000;
    string strongestExtension = "";
    for (string extension : extensions) {
        int strength = 0;
        for (char c : extension) {
            if (isupper(c)) strength++;
            else if (islower(c)) strength--;
