vector<int> maximum(vector<int> arr, int k) {
    // Creation of a set from the vector.
    set<int> s(arr.begin(), arr.end());

    vector<int> result;

    // Getting the k maximum unique numbers.
    for(auto it = s.rbegin(); it != s.rend() && k > 0; ++it, --k) {
