    for (size_t i = 0, j = 0; i < text.size(); ++i)
    {
        char c = text[i];
        if (isalpha(c))
        {
            bool is_upper = isupper(c);
            c = toupper(c);
            c = ((c - 'A') - (toupper(keyword[j]) - 'A') + 26) % 26 + 'A';

            if (is_upper)
                output += c;
            else
                output += tolower(c);

            j = (j + 1) % keyword.size();
        }
        else{
            output += c;
        }
    }
    return output;
}

