#include <vector>

#pragma omp declare reduction (merge : std::vector<int> : omp_out.insert(omp_out.end(), omp_in.begin(), omp_in.end()))

std::vector<int> parallel_binary_search(const std::vector<int>& arr, int target) {
    int size = arr.size();
    std::vector<int> result;
    omp_set_num_threads(8); // setting the number of threads to 8

    #pragma omp parallel for reduction(merge: result)
    for(int i=0; i<size; i++){
        int lo = 0, hi = size -1;

        while(lo <= hi){
            int mid = lo + (hi - lo) / 2;

            if(arr[mid] == target){
                result.push_back(mid);  
                break;
            }
            if(arr[mid] < target){
                lo = mid + 1;
            }   
            else{
                hi = mid - 1;
            }
        }
    }
    return result;  
}


