#include <vector>
#include <algorithm> // for sort()

bool rearrangeThreeElements(std::vector<int>& arr) {
    // Check if the size of arr is 0, if so return true
    if(arr.size() == 0){
        return true;
    }

    // Sort the array and create its copy
    std::vector<int> arr_sorted(arr);
    std::sort(arr_sorted.begin(), arr_sorted.end());

    // Store the first element of array
    int arr_first = arr[0];

    // Count how many times the first element is in the sorted array
    int counts = std::count(arr_sorted.begin(), arr_sorted.end(), arr_first);

    // Create a vector of elements that are less than the first element
    std::vector<int> lesser_elements;
    for(int i = 0; i< arr_sorted.size(); i++){
        if(arr_sorted[i] < arr_first){
            lesser_elements.push_back(arr_sorted[i]);
        }
    }

    // If the amount of lesser elements is even
    if(lesser_elements.size() % 2 == 0){
        // When element count is more than 1
        if(counts > 1){
            // Find the next index of arr_first in arr after index 0
            auto idx = std::find(arr.begin() + 1 , arr.end(), arr_first) - arr.begin();
            // Add arr_first into lesser_elements
            lesser_elements.push_back(arr_first);
            // Replace the arr_first at idx in arr by the first element in lesser_elements
            arr[idx] = lesser_elements[0];
            // Sort arr again
            std::sort(arr.begin(), arr.end());
        }else{
            return false;
        }
    }

    // Find out how many swaps are needed to make arr the same as arr_sorted
    int swap_counts = 0;
    for( int i =0 ; i<arr.size(); i++){
        if(arr[i] != arr_sorted[i]) swap_counts++;
    }

    // If the amount of swaps divided by 2 is less than or equal to 3, return true. Else, return false.
    return swap_counts / 2 <= 3;
}
```
