Here is a C++ solution:

```C++
#include <sstream>
#include <string>
#include <vector>
#include <cctype>

std::vector<std::string> split_numbers(std::string txt) {
  // empty string condition
  if (txt.empty())
    return {"0"};

  // to store the numbers
  std::vector<std::string> nums;

  // string to store numbers temporarily
  std::string str;

  // iterate over all characters in string
  for (std::size_t i = 0; i < txt.length(); ++i) {
    // if character is digit
    if (std::isdigit(txt[i])) {
      str += txt[i];
    } else {  // if not a digit
      if (!str.empty()) {
        nums.push_back(str);
        str.clear();
      }
    }
  }

  // push last number in string to vector
  if (!str.empty()) {
    nums.push_back(str);
  }

  // if no numbers were found
  if (nums.empty()) {
    int sum = 0;
    for (char c : txt) {
      char lower_c = std::tolower(c);
      if (lower_c == 'a' || lower_c == 'e' || lower_c == 'i'
          || lower_c == 'o' || lower_c == 'u') {
        // add ASCII value to sum
        sum += static_cast<int>(c);
      }
    }
    nums.push_back(std::to_string(sum));
  }

  return nums;
}
```

Here, the function `split_numbers()` essentially splits the input string at every non-numeric character and gathers all numeric characters as a whole number. If a non-numeric character or end of string is encountered, the number formed so far is added to the vector.

In case no numbers are found, a sum of ASCII values of all vowels in the string is added to the vector instead. An empty string input will yield a vector containing the string "0".

