We can standardize this code by using Templates that allows to handle multiple datatypes. This will let us pass any type array(integer, float or string) to the sorting function.

```C++
#include <iostream>
#include <string>
using namespace std;

//Generic bubble sort function using Templates
template <class T> 
void bubbleSort(T arr[], int n){
   int i, j;
   bool swapped;
   for (i = 0; i < n-1; i++){    
      swapped = false;
      // Last i elements are already in place   
      for (j = 0; j < n-i-1; j++){ 
          if (arr[j] > arr[j+1]){
              swap(arr[j], arr[j+1]); //using built in swap function
              swapped = true;
          }
      }
      // If no two elements were swapped by inner loop, then break
      if (swapped == false)
        break;
   }
}

template <class T> 
void printArray(T arr[], int size) 
{ 
   for (int i=0; i < size; i++) 
       cout << arr[i] << " "; 
   cout << endl; 
} 

int main() 
{ 
   int arr[] = {64, 34, 25, 12, 22, 11, 90}; 
   int n = sizeof(arr)/sizeof(arr[0]); 
   bubbleSort(arr, n); 
   cout<<"Sorted array: \n"; 
   printArray(arr, n); 

   float arr2[] = {64.2, 34.5, 25.7, 12.6, 22.1, 11.9, 90.0}; 
