#include <cctype>

int countWordOccurrences(const std::string& text, const std::string& word) {
    std::string lowerText = text;
    std::string lowerWord = word;
    std::transform(lowerText.begin(), lowerText.end(), lowerText.begin(), ::tolower);
    std::transform(lowerWord.begin(), lowerWord.end(), lowerWord.begin(), ::tolower);

    std::istringstream iss(lowerText);
    std::string token;
    int count = 0;
    while (iss >> token) {
        if (token == lowerWord) {
            count++;
        }
    }
    return count;
}

int main() {
    std::string text = "The cat and the cattle are in the cathedral";
    std::string word = "cat";
    std::cout << countWordOccurrences(text, word) << std::endl;  // Output: 1
    return 0;
}
```

The `countWordOccurrences` function first converts both the input text and the word to lowercase using `std::transform` and `::tolower`. Then, it uses `std::istringstream` to tokenize the lowercased text and counts the occurrences of the lowercased word. The function returns the total count of whole word matches found in the text.

