The most efficient way to solve this in terms of time complexity involves using dynamic programming. Here is a C++ code to solve a 4-string Longest Common Subsequence problem.

```cpp
#include <iostream>
#include <algorithm>
using namespace std;

int lcs4(string X, string Y, string Z, string W) {
    int m = X.length();
    int n = Y.length();
    int o = Z.length();
    int p = W.length();

    int dp[m+1][n+1][o+1][p+1];

    for (int i=0; i<=m; i++) {
        for (int j=0; j<=n; j++) {
            for (int k=0; k<=o; k++) {
                for (int l=0; l<=p; l++) {
                    if (i == 0 || j == 0 || k == 0 || l == 0)
                        dp[i][j][k][l] = 0;

                    else if (X[i-1] == Y[j-1] && X[i-1] == Z[k-1] && X[i-1] == W[l-1])
                        dp[i][j][k][l] = dp[i-1][j-1][k-1][l-1] + 1;

                    else
                        dp[i][j][k][l] = max(max(max(dp[i-1][j][k][l], dp[i][j-1][k][l]), dp[i][j][k-1][l]), dp[i][j][k][l-1]);
                }
            }
        }
    }

    return dp[m][n][o][p];
}

int main() {
    string X = "tropicalfish";
    string Y = "tropicalthunder";
    string Z = "topicdiscussion";
    string W = "tropicparadise";
    cout << "Length of LCS is " << lcs4(X, Y, Z, W);
    return 0;
}
```
In this code, we created a 4-dimensional DP table to hold the LCS values for every combination of characters in the four input strings. For each character in the strings, we check if they are all equal. If they are, we increment the current LCS value by 1. If they're not, we take the maximum LCS value from considering all combinations of the previous characters.
This solution runs in O(mnloq) time where m, n, l, o and q are the lengths of the four strings, making it very efficient for long strings.

