Below is a basic multi-threaded C++ program which generates prime numbers in a range from 0 to 10,000. It uses the standard library's thread support and a simple prime-checking algorithm. Mutex is used for synchronization.

```C++
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <algorithm>

std::mutex mtx;

bool isPrime(int n)
{
    if (n <= 1)
        return false;

    if (n == 2)
        return true;

    if (n % 2 == 0)
        return false;

    for(int i = 3; i * i <= n; i += 2){
        if(n % i == 0)
            return false;
    }

    return true;
}

void findPrimes(int start, int end, std::vector<int>& primes)
{
    for(int i = start; i <= end; ++i)
    {
        if (isPrime(i)) {
            std::lock_guard<std::mutex> lock(mtx);
            primes.push_back(i);
        }
    }
}

int main()
{
    const int rangeStart = 0;
    const int rangeEnd   = 10000;
    const int numOfThreads = std::thread::hardware_concurrency();

    std::vector<int> primes;
    std::vector<std::thread> threads(numOfThreads);

    int batchSize = (rangeEnd - rangeStart + 1) / numOfThreads;

    for(int i = 0; i < numOfThreads; ++i){
        int batchStart = rangeStart + i * batchSize;
        int batchEnd   = (i != (numOfThreads - 1)) ? batchStart + batchSize - 1 : rangeEnd;

        threads[i] = std::thread(findPrimes, batchStart, batchEnd, std::ref(primes));
    }

    std::for_each(threads.begin(), threads.end(), [](std::thread &t) { t.join(); });

    // sort the prime numbers
    std::sort(primes.begin(), primes.end());

    // print the prime numbers
    for(const int prime : primes)
        std::cout << prime << " ";

    return 0;
}
```

In the main function we create as many threads as our hardware supports for optimal usage. Each thread will then calculate primes in a different range. The `std::mutex` is used to ensure that threads will not simultaneously push back primes to the vector.

Please note the C++11 standard or above version is necessary to compile and run the above code because it uses threads and mutex facilities introduced in C++11. This program will not work on compilers which do not support C++11 or above. Please make sure to enable C++11 while compiling the code by using the `-std=c++11` flag if you are using g++ or clang++ compilers.

