Also, note that the mode calculation assumes that it should return the smallest number with the most occurrences. If a data stream has multiple modes, this will return the smallest one.

```c++
#include <vector>
#include <algorithm>
#include <map>

class RollingAverage {
private:
    std::vector<int> numbers;
    std::map<int, int> freq;

public:
    void addNumber(int number) {
        numbers.push_back(number);
        freq[number]++;
    }

    double calculateAverage() {
        double sum = 0;
        for (int i : numbers) {
            sum += i;
        }
        return sum / numbers.size();
    }

    double calculateMedian() {
        std::vector<int> sortedNumbers = numbers;
        std::sort(sortedNumbers.begin(), sortedNumbers.end());

        int size = sortedNumbers.size();
        if (size % 2 == 0){
            return (sortedNumbers[size / 2 - 1] + sortedNumbers[size / 2]) / 2.0;
        } else {
            return sortedNumbers[size / 2];
        }
    }

    int calculateMode() {
        int mode = numbers[0];
        for (auto i : freq) {
            if (i.second > freq[mode]){
                mode = i.first;
            }
        }
        return mode;
    }
};
```

This class uses a vector to keep track of the numbers, which are sorted when calculating the median. The frequency of each number is tracked with a map to help calculate the mode. When numbers are added, they are simply appended to the numbers vector and the frequency map is updated. The average and median calculation follow standard mathematical rules.

