    vector<int> sumZero(int n) {
        vector<int> ans;
        if (n % 2 != 0) {
            ans.push_back(0);
            --n;
        }
        for (int i = 1; i <= n / 2; ++i) {
            ans.push_back(i);
            ans.push_back(-i);
        }
        return ans;
    }
};
