Here is a C++ program that finds the least common ancestor (LCA) of two provided nodes in a Binary Search Tree. The program assumes that the nodes are present in the BST.

```cpp
#include<iostream>
using namespace std;

// Binary tree node structure
struct Node
{
    int data;
    struct Node *left, *right;
};

// Function to create a new binary tree node
struct Node *newNode(int data)
{
    struct Node *node = new Node();
    node->data  = data;
    node->left  = node->right  = NULL;
    return (node);
}

// Function to find LCA of n1 and n2. 
struct Node *lca(Node* node, int n1, int n2)
{
    if (node == NULL) return NULL;

    // If both n1 and n2 are smaller than root, then LCA lies in left
    if (node->data > n1 && node->data > n2)
        return lca(node->left, n1, n2);

    // If both n1 and n2 are greater than root, then LCA lies in right
    if (node->data < n1 && node->data < n2)
        return lca(node->right, n1, n2);

    return node;
}

int main()
{
    // Let's create the binary search tree as given in the problem
    //       8
    //     /   \
    //    3     10
    //   / \    /
    //  1   6  14       
    Node *root  = newNode(8);
    root->left  = newNode(3);
    root->right = newNode(10);
    root->left->left = newNode(1);
    root->left->right = newNode(6);  
    root->right->left = newNode(14);

    int n1 = 14, n2 = 8;
    Node *lcaNode = lca(root, n1, n2);
    if (lcaNode != NULL)
        cout << "LCA of " << n1 << " and " << n2 << " is " << lcaNode->data;
    else
        cout << "Both nodes are not present in BST";

    return 0;
}
``` 

