std::string complex_custom_merge_strings(std::vector<std::string> strings) {

    // Arrange the strings by their length
    sort(strings.begin(), strings.end(), [](const std::string &a, const std::string &b) { return a.length() > b.length(); });

    // Ensure the shortest string is inserted between the chars of the longest string
    if (strings[0].length() > (strings[1].length() + strings[2].length())) {
        std::rotate(strings.begin(), strings.begin() + 1, strings.end());
    }

    // Merge the strings
    std::string merged_string = "";
    size_t i = 0;
    while (true) {
        bool addedChar = false;
        for(auto &str : strings){
            if(i < str.length()){
                merged_string += str[i];
                addedChar = true;
            }
        }
        ++i;
        if (!addedChar)
            break;
    }

    // Reverse the final string
    reverse(merged_string.begin(), merged_string.end());

    return merged_string;
}

int main() {
    std::cout << complex_custom_merge_strings({ "abc", "defg", "hij" }) << std::endl;
    return 0;
}
