```cpp
#include <iostream>
#include <ctime>
#include <cstdlib>

#define SIZE 10 // the size of the array

void bubbleSort(int array[], int size){
    int i, j;
    for(i = 0; i < size - 1; i++){
        for(j = 0; j < size - i - 1; j++){
            // Swap elements if current element is greater than next
            if(array[j] > array[j+1]){
                int temp = array[j];
                array[j] = array[j+1];
                array[j+1] = temp;
            }
        }
    }
}

int main(){
    srand((unsigned)time(NULL)); // seed for random number generation

    // Generate random data
    int array[SIZE];
    for(int i = 0; i < SIZE; i++) array[i] = rand() % 100 + 1;

    std::cout << "Before Sorting: " << std::endl;
    for(int i = 0; i < SIZE; i++) std::cout << array[i] << " ";
    std::cout << std::endl;

    // Call the bubble sort function
    bubbleSort(array, SIZE);

    std::cout << "After Sorting: " << std::endl;
    for(int i = 0; i < SIZE; i++) std::cout << array[i] << " ";
    std::cout << std::endl;

    return 0;
}
```

