```cpp
#include<vector>
#include<algorithm>
using namespace std;

vector<int> maxPath(vector<vector<int>> grid, int k) {
    if (grid.empty() || grid[0].empty())
        return {};

    size_t dimension = grid.size();
    int max_val = *max_element(grid, grid + dimension*dimension);
    int min_val = *min_element(grid, grid + dimension*dimension);
    vector<int> max_seq;

    void dfs(int i, int j, vector<int> seq) {
        if (seq.size() == k) {
            if (find(seq.begin(), seq.end(), min_val) != seq.end() 
                && find(seq.begin(), seq.end(), max_val) != seq.end() 
                && accumulate(seq.begin(), seq.end(), 0) > accumulate(max_seq.begin(), max_seq.end(), 0)) {
                max_seq = seq;
            }
            return;
        }

        vector<pair<int, int>> directions {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};
        for(auto& direction : directions) {
            int x = i + direction.first, y = j + direction.second;
            if (0 <= x && x < dimension && 0 <= y && y < dimension 
                && find(seq.begin(), seq.end(), grid[x][y]) == seq.end()) {
                seq.push_back(grid[x][y]);
                dfs(x, y, seq);
                seq.pop_back();  // backtrack
            }
        }
    }

    for (int i = 0; i < dimension; ++i)
        for (int j = 0; j < dimension; ++j) 
            dfs(i, j, {grid[i][j]});

    return max_seq;
}
