std::string extract_integer(double number) {
    // Check if number is not a number
    if (std::isnan(number)) {
        return "Error: Invalid input.";
    }

    // Check if number is infinity
    if (std::isinf(number)) {
        return "Error: Number too large.";
    }

    // Check if number is too large
    if (std::abs(number) > std::numeric_limits<double>::max()) {
        return "Error: Number too large.";
    }

    // Return the largest integer less than or equal to the given number
    return (number >= 0) ? std::to_string(static_cast<long long int>(number)) 
        : std::to_string(static_cast<long long int>(number) - 1);
}
