class Solution {
    public:
    std::vector<int> getOddCollatz(int n) {
        std::vector<int> oddNumbers;
        while(n != 1) {
            // If n is odd, add it to the list
            if(n % 2 != 0) {
                oddNumbers.push_back(n);
            }
            // Apply the Collatz operations
            n = n % 2 == 0 ? n/2 : 3*n + 1;
        }
