int removeElement(Node** head_ref, int val)
{
    Node* temp = *head_ref;
    int count = 0;
	while(temp)
	{
       if(temp->data == val)
       {  
         // Increment the counter
         count++;       
         // If the node to be deleted is the first node
         if(temp == *head_ref)
         {
            *head_ref = temp->next;
            if(*head_ref)
               (*head_ref)->prev = NULL;          
         }
         else
         {
            temp->prev->next = temp->next;
            if(temp->next)
            	temp->next->prev = temp->prev;
         }
         Node* temp_next = temp->next;
         delete temp;
         temp = temp_next;
       }      
       else
         temp = temp->next;     
    }
	return count;
}

// Function to validate the integrity of a doubly linked list
bool validateList(Node* node) 
{ 
	while (node != NULL) 
	{ 
		if(node->next && node->next->prev != node)
        	return false;
       if(node->prev && node->prev->next != node)
        	return false;
		node = node->next; 
	} 
	return true;
} 

//Function to insert node at the end of the List
void insertNode(Node** head_ref, int new_data)
{
	Node* new_node = new Node();
	Node* last = *head_ref;
	new_node->data = new_data;
	new_node->next = NULL;
	if (*head_ref == NULL)
	{
		new_node->prev = NULL;
		*head_ref = new_node;
		return;
	}
	while (last->next != NULL)
		last = last->next;
	last->next = new_node;
	new_node->prev = last;
	return;
}

