#include <vector>
#include <cmath>
#include <algorithm>

bool is_prime(int n){
    if(n < 2) return false;
    for(int i = 2; i <= static_cast<int>(std::sqrt(n)); ++i){
        if(n % i == 0) return false;
    }
    return true;
}

std::vector<int> unique_odd_prime_sum_elements(std::vector<int> x){
    std::vector<int> prime_digits = {2, 3, 5, 7}, result;
    for(const auto& num : x){
        if(std::find(result.begin(), result.end(), num) == result.end()){
            int digit_sum = 0;
            int tmp_num = num;
            while (tmp_num > 0) {
                if (std::find(prime_digits.begin(), prime_digits.end(), tmp_num % 10) != prime_digits.end()) {
                    ++digit_sum;
                }
                tmp_num /= 10;
            }
            if(digit_sum % 2 != 0) result.push_back(num);
        }
    }
    std::sort(result.begin(), result.end());
    return result;
}
```
