class Student {
private:
    std::string name, address;
    int age;
    std::map<std::string, int> courses; //course, grade
    std::map<std::string, float> creditHours; //course, credit hours

public:
    Student(std::string name, int age, std::string address) :
        name(name), age(age), address(address) {}

    void addCourse(std::string course, float creditHour) {
        courses[course] = 0; // grade initially set to 0
        creditHours[course] = creditHour;
    }

    void removeCourse(std::string course) {
        if(courses.find(course) == courses.end())
            throw std::invalid_argument("Course to be deleted not found.");
        courses.erase(course);
        creditHours.erase(course);
    }

    void updateGrade(std::string course, int grade) {
        if(courses.find(course) == courses.end())
            throw std::invalid_argument("Course to be updated not found.");
        if(grade < 0 || grade > 100)
            throw std::invalid_argument("Invalid grade. Enter value between 0 and 100.");
        courses[course] = grade;
    }

    double calculateGPA() {
        if(courses.empty())
            throw std::invalid_argument("No courses/grades found for calculating GPA.");
        double weightedSum = 0;
        float totalCreditHours = 0;
        for(auto &course : courses) {
            weightedSum += course.second * creditHours[course.first];
            totalCreditHours += creditHours[course.first];
        }
        double gpa = weightedSum / (totalCreditHours * 100);
        return gpa;
    }

    friend std::ostream &operator<<(std::ostream &os, const Student& student);

};

std::ostream &operator<<(std::ostream &os, const Student& student) {
    os << "Student: " << student.name << ", Age: " << student.age << ", Address: " << student.address;
    for(auto &course : student.courses) {
        os << "\nCourse: " << course.first << ", Grade: " << course.second 
           << ", Credit Hours: " << student.creditHours.at(course.first);
    }
    return os;
}
