// Assuming that List Node is structered as:
struct ListNode {
  int val;
  ListNode *next;
};

// Merge in Ascending Order
ListNode* mergeAscending(ListNode* l1, ListNode* l2){
    ListNode preHead(0);
    ListNode* pre = &preHead;
    while(l1 != NULL && l2 != NULL){
        if(l1->val < l2->val){
            pre->next = l1;
            l1 = l1->next;
        } else {
            pre->next = l2;
            l2 = l2->next;
        }
        pre = pre->next;
    }
    if(l1!=NULL) 
        pre->next = l1;
    if(l2!=NULL) 
        pre->next = l2;

    return preHead.next;
}

// Merge in Descending Order
ListNode* mergeDescending(ListNode* l1, ListNode* l2){
    if(l1 == NULL) 
        return l2;
    if(l2 == NULL)
        return l1;
    if(l1->val > l2->val){
        l1->next = mergeDescending(l1->next, l2);
        return l1;
    } else {
        l2->next = mergeDescending(l1, l2->next);
        return l2;
    }
}
```
