using namespace std;

int maxSumAfterPartitioning(vector<int>& nums, int days) {
    int n = nums.size();
    vector<int> best(n);
    priority_queue<pair<int, int>> pq;
    pq.push({0, -days});

    for (int i = 0; i < n; ++i) {
        while (pq.top().second < i - days) pq.pop();
        best[i] = pq.top().first;

        if (i - days - 1 >= 0)
            best[i] = best[i - days - 1] + nums[i] > best[i] ? best[i - days - 1] + nums[i] : best[i];
        else
            best[i] = nums[i] > best[i] ? nums[i] : best[i];

        if (i - 1 > 0) best[i] = best[i - 1] > best[i] ? best[i - 1] : best[i];
        pq.push({best[i], i});
    }

    return best[n - 1];
}
```

The `maxSumAfterPartitioning` function initializes a priority queue `pq` to store pairs of integers representing the maximum sum and the end index of the subarray. It then iterates through the input array `nums`, updating the `best` array to store the maximum sum of non-overlapping subarrays. Finally, it returns the maximum sum of non-overlapping subarrays after partitioning the array.

