Here's a C++ solution. In this implementation, the doubly linked list class is named LinkedList and the class for the node is named Node. The function named reverseAndAdd will first find the smallest and largest values and calculate their sum. Then the elements of the list will be reversed by swapping the node values. Finally, a new node will be created with a value equal to the sum, and it will be inserted at the middle position of the original list.

This solution handles edge cases such as empty lists (in which case, nothing will be added and the function will simply return) and lists with an odd or even number of nodes.

```cpp
#include <iostream>
#include <climits>

using namespace std;

class Node {
public:
    int val;
    Node* next;
    Node* prev;

    Node(int val) : val(val), next(NULL), prev(NULL) {}
};

class LinkedList {
public:
    Node* head;
    Node* tail;

    LinkedList() : head(NULL), tail(NULL) {}

    // Function to append node
    void append(int val) {
        Node* node = new Node(val);

        if(!head) {
            head = tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    // Function to reverse the list and add a node at middle
    void reverseAndAdd() {
        // Handle empty list
        if (!head)
            return;

        int smallest = INT_MAX, largest = INT_MIN;
        Node *p = head, *q = tail;

        // Calculate smallest and largest values
        while (p) {
            smallest = min(smallest, p->val);
            largest = max(largest, p->val);
            p = p->next;
        }

        int sum = smallest + largest;
        p = head, q = tail;

        // Swap node values
        while (p != q && q->next != p) {
            int temp = p->val;
            p->val = q->val;
            q->val = temp;

            p = p->next;
            q = q->prev;
        }

        Node *middle = new Node(sum);

        // Insert node at middle position
        if (!head->next) {
            head->prev = middle;
            middle->next = head;
            head = middle;
        } else {
            Node *slow = head, *fast = head;

            while (fast && fast->next && fast->next->next) {
                slow = slow->next;
                fast = fast->next->next;
            }

            middle->prev = slow;
            middle->next = slow->next;
            slow->next->prev = middle;
            slow->next = middle;
        }
    }

    // Function to print the list
    void printList() {
        Node* temp = head;

        while(temp) {
            cout << temp->val << " ";
            temp = temp->next;
        }
        cout << "\n";
    }
};
```

