Below is a C++ program that prints a given matrix in spiral form. It considers all four direction (right -> down -> left -> up).

```cpp
#include<iostream>
using namespace std;

// Function to print the matrix in spiral form.
void SpiarlPrint(int a[][3], int m, int n) {
    int i, k = 0, l = 0;

    while (k < m && l < n) {
        // Print the first row from the remaining rows.
        for (i = l; i < n; ++i) {
            cout << a[k][i] << " ";
        }
        k++;

        // Print the last column from the remaining columns.
        for (i = k; i < m; ++i) {
            cout << a[i][n - 1] << " ";
        }
        n--;

        // Print the last row from the remaining rows.
        if (k < m) {
            for (i = n - 1; i >= l; --i) {
                cout << a[m - 1][i] << " ";
            }
            m--;
        }

         // Print the first column from the remaining columns.
        if (l < n) {
            for (i = m - 1; i >= k; --i) {
                cout << a[i][l] << " ";
            }
            l++;
        }
    }
}

int main() {
    int a[3][3] = { {1, 2, 3},
                    {4, 5, 6},
                    {7, 8, 9} };

    int m = 3;  // Number of rows.
    int n = 3;  // Number of columns.

    SpiarlPrint(a, m, n);  
    return 0;
}
```

