class CircularBuffer {
private:
    char* buffer;
    int size;
    int readIndex;
    int writeIndex;
    int totalBytes;

public:
    CircularBuffer(int bufferSize) : size(bufferSize), readIndex(0), writeIndex(0), totalBytes(0) {
        buffer = new char[size];
    }

    ~CircularBuffer() {
        delete[] buffer;
    }

    void peek(char* buffer, int length, int index) {
        for (int i = 0; i < length; i++) {
            buffer[i] = this->buffer[(index + i) % size];
        }
    }

    int total_bytes() {
        return totalBytes;
    }

    int bytes_to_write() {
        return size - totalBytes;
    }

    int bytes_to_read() {
        return totalBytes;
    }

    char* read_ptr() {
        return &buffer[readIndex];
    }

    char* write_ptr() {
        return &buffer[writeIndex];
    }

    void read(char* buffer, int length) {
        for (int i = 0; i < length; i++) {
            buffer[i] = this->buffer[readIndex];
            readIndex = (readIndex + 1) % size;
            totalBytes--;
        }
    }

    void write(const char* data, int length) {
        for (int i = 0; i < length; i++) {
            buffer[writeIndex] = data[i];
            writeIndex = (writeIndex + 1) % size;
            totalBytes++;
        }
    }
};

