Bubble sort algorithm is not typically used to organize elements in a binary search tree because it is inefficient for this kind of data structure. A binary search tree is already a sorted type of data structure.

However, a problem such as sorting an array or a vector can be approached by utilizing the bubble sort algorithm. The following is a simple example of how to implement a bubble sort in C++:

```cpp
#include <iostream>
using namespace std;

void bubbleSort(int arr[], int n) {
   for(int i = 0; i < n-1; i++) {     
       for (int j = 0; j < n-i-1; j++) { 
           if (arr[j] > arr[j+1]) {
              // Swap arr[j] and arr[j+1]
              int temp = arr[j];
              arr[j] = arr[j+1];
              arr[j+1] = temp;
           }
       }
   }
}

void printArray(int arr[], int size) {
   for (int i = 0; i < size; i++)
       cout << arr[i] << " ";
   cout << endl;
}

int main() {
   int arr[] = {64, 34, 25, 12, 22, 11, 90};
   int n = sizeof(arr)/sizeof(arr[0]);
   bubbleSort(arr, n);
   cout<<"Sorted array: \n";
   printArray(arr, n);
   return 0;
}
```

