#include <vector>
#include <queue>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

vector<vector<int>> levelOrderTraversal(TreeNode* root) {
    vector<vector<int>> result;
    if (root == nullptr) {
        return result;
    }

    queue<TreeNode*> q;
    q.push(root);

    while (!q.empty()) {
        int levelSize = q.size();
        vector<int> levelNodes;

        for (int i = 0; i < levelSize; i++) {
            TreeNode* node = q.front();
            q.pop();
            levelNodes.push_back(node->val);

            if (node->left != nullptr) {
                q.push(node->left);
            }
            if (node->right != nullptr) {
                q.push(node->right);
            }
        }

        result.push_back(levelNodes);
    }

    return result;
}
```

The `levelOrderTraversal` function uses a queue to perform a breadth-first traversal of the binary tree. It iterates through each level of the tree, adding the node values to the result vector in the form of a 2D array. The function returns the level order traversal of the given binary tree.

```cpp
template <int subwarp_size, typename ValueType, typename IndexType>
void compute_l_u_factors(syn::value_list<int, subwarp_size>,
                         const ValueType* matrix,
                         IndexType num_rows,
                         IndexType num_cols,
                         ValueType* L,
                         ValueType* U) {
    for (IndexType i = 0; i < num_rows; ++i) {
        for (IndexType j = 0; j < num_cols; ++j) {
            if (j < i) {
                L[i * num_cols + j] = matrix[i * num_cols + j];
                U[i * num_cols + j] = 0;
            } else if (j == i) {
                L[i * num_cols + j] = 1;
                U[i * num_cols + j] = matrix[i * num_cols + j];
            } else {
                L[i * num_cols + j] = 0;
                U[i * num_cols + j] = matrix[i * num_cols + j];
            }
        }
    }

    for (IndexType k = 0; k < num_rows; ++k) {
        for (IndexType i = k + 1; i < num_rows; ++i) {
            L[i * num_cols + k] = U[i * num_cols + k] / U[k * num_cols + k];
            U[i * num_cols + k] = 0;
            for (IndexType j = k + 1; j < num_cols; ++j) {
                U[i * num_cols + j] -= L[i * num_cols + k] * U[k * num_cols + j];
            }
        }
    }
}
```

