Below is a simple program simulating a doubly linked list data structure and a function to reverse the linked list in place. 

```cpp
#include<iostream>
using namespace std;

//node structure
struct node {
    int data;
    node* next;
    node* prev;
};

//initial pointers to head and tail 
node* head = NULL;
node* tail = NULL;

//insert node at the end of list
void insert(int value) {
    node* temp = new node;
    temp->data = value;
    temp->next = NULL;
    temp->prev = NULL;
    if(head == NULL) {
        head = temp;
        tail = temp;
    }
    else {
        tail->next = temp;
        temp->prev = tail;
        tail = tail->next;
    }
}

//function to reverse the doubly linked list
void reverse() {
    node* current = head;
    node* temp = NULL;
    while(current != NULL) {
        temp = current->prev;
        current->prev = current->next;
        current->next = temp;
        current = current->prev;
    }
    //swap the head and tail pointers
    if(temp!=NULL){
        head = temp->prev;
    }
}

//print list
void printList() {
    if(head == NULL)
        cout<<"List is empty!";
    else {
        node* temp = head;
        while(temp != NULL) {
            cout<<(temp->data)<<" ";
            temp = temp->next;
        }
        cout<<"\n";
    }
}

//driver function
int main() {
    //inserting nodes
    insert(1); 
    insert(2); 
    insert(3);  
    cout<<"Original list: ";
    printList();
    reverse();
    cout<<"List after reversal: ";
    printList();
    return 0;
}
```
In this code, we're first defining the node structure and to keep track of start and end of the list, head and tail pointers are used. To add a new node at the end, the function `insert(int val)` is used. The `reverse()` function is the one which actually reverses the linked list in place. It swaps the previous and next pointers for each node and then swaps head and tail pointers. Finally, the `printList()` function prints the entire list.

