    // check if the value is in the memo map
    if (memo.count(n + offset)) {
        return memo[n + offset];
    }
    // base cases
    int result;
    if (n == 0) {
        result = offset;
    } else if (n == 1) {
        result = 1 + offset;
    } else if (n == 2) {
        result = 1 + 2 * offset;
    } else if (n == 3) {
