Below is a sample C++ solution for calculating the harmonic mean of a dynamic collection of integers using a linked list.

```C++
#include <iostream>
using namespace std;

// Node definition
struct node{
    int data;
    node* link;
};

//Initialization of head as NULL
node* head = NULL;

// Insert function
void insert(int val){
    node* temp = new node;
    temp -> data = val;
    temp -> link = NULL;

    if(head == NULL){
        head = temp;
    }
    else{
        node* ptr;
        ptr = head;    
        while(ptr -> link != NULL){
            ptr = ptr->link;
        }
        ptr->link = temp;
    }
} 

// Function to calculate Harmonic Mean 
double harmonicMean() {
    node* temp = head;

    double sum = 0; 
    int length = 0;

    while (temp != NULL){
        if (temp->data == 0) {
            cout << "Harmonic mean undefined as one element is 0" << endl;
            exit(0);  
        }
        sum = sum + (1.0/temp->data);
        length++;
        temp = temp->link;
    } 
    return length/sum;
}

// Driver code
int main(){
    int size, val;
    cout << "Enter the size of the linked list: ";
    cin >> size;

    cout << "Enter elements: ";
    for(int i=0; i<size; i++){
        cin >> val;
        insert(val);
    }
    cout << "Harmonic Mean is " << harmonicMean() << endl;
    return 0;
