class Node {
public:
    int data;
    Node* next;
    Node(int val) : data(val), next(nullptr) {}
};

class RedoDelete {
private:
    Node* top;

public:
    RedoDelete() : top(nullptr) {}

    void redo(int val) {
        Node* newNode = new Node(val);
        newNode->next = top;
        top = newNode;
    }

    void deleteTop() {
        if (top != nullptr) {
            Node* temp = top;
            top = top->next;
            delete temp;
        }
    }

    ~RedoDelete() {
        while (top != nullptr) {
            Node* temp = top;
            top = top->next;
            delete temp;
        }
    }
};

