double calculateGrade(const StudentData &student) {
    double grade = 0;

    if (student.quizScores.size() > 1) {
        int minQuizScore = *min_element(student.quizScores.begin(), student.quizScores.end());
        int quizSum = 0;
        for (int score : student.quizScores) {
            quizSum += score;
        }
        quizSum -= minQuizScore;
        grade += (static_cast<double>(quizSum) / (student.quizScores.size()-1)) * 0.3;
    } else if (!student.quizScores.empty()) {
        grade += (static_cast<double>(student.quizScores[0])) * 0.3;
    }

    if (student.hwScores.size() > 1) {
        int minHwScore = *min_element(student.hwScores.begin(), student.hwScores.end());
        int hwSum = 0;
        for (int score : student.hwScores) {
            hwSum += score;
