#include<vector>
#include<numeric>
#include<math.h>
using namespace std;

// Function for product calculation of vector elements, exclude zeros.
int calculate_product(const vector<int>& numbers){
    int product = 1;
    for (auto num: numbers){
        if (num != 0) {
            product *= num;
        }
    }
    return product;
}

// Function for product calculation of square roots of vector elements higher than 0.
double calculate_product_sqrt(const vector<int>& numbers){
    double product = 1;
    for (auto num: numbers){
        if (num > 0) {
            product *= sqrt(num);
        }
    }
    return product;
