#include <stdio.h>
#include <math.h>
#include <vector>
#include <algorithm>

using namespace std;

// Function to calculate the digit length of a number
int numDigits(int number) {
    if (number == 0) return 1;
    if (number < 0) number = -number; // abs value for negative numbers
    int digits = 0;
    while (number) {
        number /= 10;
        digits++;
    }
    return digits;
}

// Comparison function for sorting
bool compareFunction(int i, int j) {
    int len_i = numDigits(i), len_j = numDigits(j);

    if(len_i == len_j)
        return i < j;

    return len_i < len_j;
}

// Function to sort the vector
vector<int> sort_vector(vector<int> arr) {
    sort(arr.begin(), arr.end(), compareFunction);
    return arr;
}
