using namespace std;

int main() {
    int arr1[5] = {1, 2, 3, 4, 5};
    int arr2[3] = {6, 7, 8};
    int sum[5];

    for (int i=0; i<5; i++) { 
        sum[i] = arr1[i] + arr2[i];
