using namespace std;

bool isPrime(int n) {
    if (n <= 1)
        return false;
    if (n <= 3)
        return true;

    if (n % 2 == 0 || n % 3 == 0)
        return false;

    for (int i=5; i*i<=n; i=i+6)
        if (n % i == 0 || n % (i + 2) == 0)
            return false;

    return true;
}

void sumAndMaxPrimeDivisors(int n) {
    int sum = 0, largest = INT_MIN;
    for (int i=2; i*i<=n; i++) {
        if (n % i == 0) {
            if (isPrime(i)) {
                if (i > largest) {
                    largest = i;
                }
                sum += i;
            }

            int temp = n / i;
            if (temp != i && isPrime(temp)) {
                if (temp > largest) {
                    largest = temp;
                }
                sum += temp;
            }
        }
    }

    // If the number itself is a prime number and greater than 2
    if (n > largest && isPrime(n))
        largest = n;

    cout<<"Sum of Prime Divisors (excluding the number itself):"<<sum;
    cout<<endl<<"Largest Prime Divisor: "<<largest<<endl;
}

