#include <iostream>
#include <vector>
#include <unordered_set>
#include <algorithm>

// Sort the elements in vector using heap sort
std::vector<int> heapify(std::vector<int>& arr) {
    int n = arr.size();

    // Build a max heap
    std::make_heap(arr.begin(), arr.end());

    // One by one extract elements from heap
    for (int i = n - 1; i > 0; i--) {
        // Move the current root to end
        std::pop_heap(arr.begin(), arr.begin() + i + 1);

        // Ensure max heap property is maintained for remaining elements
        std::make_heap(arr.begin(), arr.begin() + i);
    }

    // Reverse to get ascending sorted array because of max-heap
    std::reverse(arr.begin(), arr.end());

    return arr;
}

// Function that gets shared elements in three lists and sorts them
std::vector<int> shared_elements_extended(std::vector<int> list1, std::vector<int> list2, std::vector<int> list3) {
    // Convert vectors to sets to maintain unique elements
    std::unordered_set<int> set1(list1.begin(), list1.end()), 
                            set2(list2.begin(), list2.end()), 
                            set3(list3.begin(), list3.end());

    // Find intersection
    std::vector<int> result;
    for (int item : set1)
        if (set2.find(item) != set2.end() && set3.find(item) != set3.end())
            result.push_back(item);

    // Sort result using heap sort
    heapify(result);

    return result;
}
```
