```cpp
// C++ program for Circular Shift operation
#include<iostream>
using namespace std;

void circularShift(int arr[], int n, int k) {
    // Temporary array of size n
    int temp[n];

    // Copying the array into temp array
    for (int i = 0; i < n; i++)
        temp[i] = arr[i];

    // Shifting the elements
    for (int i = 0; i < n; i++)
        arr[(i + k)%n] = temp[i];

    // Printing the shifted array
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
}

int main() {
    int arr[] = {1, 2, 3, 4, 5 };
    int n = sizeof(arr) / sizeof(arr[0]);
    // Number of times to shift
    int k = 2;

    circularShift(arr, n, k); // Calling the function
    return 0;
}
```

