Your starting language appears to be C++, so here's a solution in C++:

```C++
#include <iostream>
#include <utility>
using namespace std;

// Function to check if a number is prime
bool isPrime(int n) 
{ 
    if (n <= 1) 
        return false; 
    if (n <= 3) 
        return true; 

    if (n % 2 == 0 || n % 3 == 0) 
        return false; 

    for (int i = 5; i * i <= n; i = i + 6) 
        if (n % i == 0 || n % (i + 2) == 0) 
            return false; 

    return true; 
} 

// Function to find the largest prime factor and it's occurrence
pair<int, int> largest_prime_factor(int n){
    int max_prime = -1;
    int count = 0;
    while (n % 2 == 0) {
        max_prime = 2;
        n >>= 1; // equivalent to n /= 2
        count++;
    }

    for (int i = 3; i <= sqrt(n); i += 2) {
        while (n % i == 0) {
      if(i > max_prime){
            max_prime = i;
            count = 1;
      }
      else if(i == max_prime)
            count++;
            n = n/i;
        }
    }

    if (n > 2 && isPrime(n)) {
        if(n > max_prime){
        max_prime = n;
        count = 1;
        }
        else if(n == max_prime) 
        count++;
    }

    return make_pair(max_prime,count);
}

int main() {
    pair<int, int> res;
    res = largest_prime_factor(13195);
    cout << "(" << res.first << ", " << res.second << ")\n";
    res = largest_prime_factor(2048);
    cout << "(" << res.first << ", " << res.second << ")\n";
    return 0;
}
```

Before finding the prime factors, we check if the number is divisible by 2 and keep dividing until it is not anymore. After that, we divide by odd numbers from 3 up to the square root of the number. If the number is still greater than 2 after this process and if it's prime, it becomes the maximum prime without any further checks, else if it's equal with the current prime it increments the count.

