Here's a C++ solution using the built-in string function `rfind()`. This function returns the position of the first character of the last occurrence of the substring in the string. If the substring is not found, it returns `string::npos`.

```C++
#include <iostream>
#include <string>
using namespace std;

bool has_suffix(string str, string suffix){
    // If the suffix is longer than the string, it cannot be the suffix of the string
    if(suffix.size() > str.size())
    	return false;

    // Find the last occurrence of the suffix in the string
    size_t pos = str.rfind(suffix);

    // If the suffix was not found, or if it is not at the end of the string, return false
    if(pos == string::npos || pos != str.size() - suffix.size())
    	return false;

    // Otherwise, the string ends with the suffix
    return true;
}

int main() {
    cout << has_suffix("activity", "ity");    // True
    cout << has_suffix("helloityity", "ity"); // True
    cout << has_suffix("heaven", "ity");      // False
    return 0;
}
```

