In order to calculate the Manhattan Distance between two points in a four-dimensional Cartesian coordinate system, you would first need to know the coordinates of the two points. Manhattan distance for four-dimensional points (x1, y1, z1, w1) and (x2, y2, z2, w2) is calculated by the formula:

distance = |x1-x2| + |y1-y2| + |z1-z2| + |w1-w2|

Here is the C++ code to calculate this:

```C++
#include<iostream>
#include<cmath>
using namespace std;

class Point {
    private:
        int x, y, z, w;

    public:
        Point(int x, int y, int z, int w) {
            this->x = x;
            this->y = y;
            this->z = z;
            this->w = w;
        }

        int getX() const {
            return x;
        }

        int getY() const {
            return y;
        }

        int getZ() const {
            return z;
        }

        int getW() const {
            return w;
        }
};

int manhattanDistance(const Point& p1, const Point& p2) {
    return abs(p1.getX() - p2.getX()) + abs(p1.getY() - p2.getY()) + abs(p1.getZ() - p2.getZ()) + abs(p1.getW() - p2.getW());
}

int main() {
    Point p1(1, 2, 3, 4);
    Point p2(5, 6, 7, 8);
    cout<<"The Manhattan distance between the two points is: "<<manhattanDistance(p1, p2)<<endl;
    return 0;
}
```
