#include <cassert>

template <typename T>
class delegate_ref {
    std::function<T> func;

public:
    delegate_ref(std::function<T> f) : func(f) {}

    T operator()(int arg) {
        return func(arg);
    }

    void operator=(std::function<T> f) {
        func = f;
    }
