    int clusters = 0;
    while (*utf8String) {
        if ((*utf8String & 0x80) == 0) {
            // Single-byte code point
            clusters++;
        } else if ((*utf8String & 0xE0) == 0xC0) {
            // Two-byte code point
            if (isContinuationByte(*(utf8String + 1))) {
                clusters++;
                utf8String++;
            }
        } else if ((*utf8String & 0xF0) == 0xE0) {
            // Three-byte code point
            if (isContinuationByte(*(utf8String + 1)) && isContinuationByte(*(utf8String + 2))) {
                clusters++;
                utf8String += 2;
            }
        } else if ((*utf8String & 0xF8) == 0xF0) {
            // Four-byte code point
            if (isContinuationByte(*(utf8String + 1)) && isContinuationByte(*(utf8String + 2)) && isContinuationByte(*(utf8String + 3))) {
                clusters++;
                utf8String += 3;
            }
        }
        utf8String++;
    }
    return clusters;
}
