```cpp
bool isSymmetric(TreeNode* root) {
    if (root == NULL) {
        return true; // An empty tree is symmetric
    }
    return isMirror(root->left, root->right);
}

bool isMirror(TreeNode* leftSub, TreeNode* rightSub) {
    if (leftSub == NULL && rightSub == NULL) {
        return true; // Both subtrees are empty, so they are symmetric
    }
    if (leftSub == NULL || rightSub == NULL) {
        return false; // One subtree is empty while the other is not, so they are not symmetric
    }
    if (leftSub->val != rightSub->val) {
        return false; // Values at the current nodes are different, so they are not symmetric
    }
    return isMirror(leftSub->left, rightSub->right) && isMirror(leftSub->right, rightSub->left);
}
```

The `isSymmetric` function first checks if the tree is empty, in which case it is symmetric. Otherwise, it calls the `isMirror` function to check if the left and right subtrees are mirrors of each other. The `isMirror` function recursively checks if the left and right subtrees are symmetric by comparing their values and their children's values. If any asymmetry is found, it returns `false`, otherwise, it returns `true`.

```cpp
#include <utility>

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

pair<TreeNode*, TreeNode*> convert(TreeNode* root) {
    if (root == nullptr) {
        return {nullptr, nullptr};
    }

    if (root->left != nullptr) {
        pair<TreeNode*, TreeNode*> leftPart = convert(root->left);
        root->left = nullptr;
        root->right = leftPart.first;
        if (leftPart.second != nullptr) {
            return {root, leftPart.second};
        }
    }

    if (root->right != nullptr) {
        pair<TreeNode*, TreeNode*> rightPart = convert(root->right);
        root->right = rightPart.first;
        return {root, rightPart.second};
    }

    return {root, root};
}
```

The `convert` function recursively processes the left and right subtrees of each node, modifies the tree according to the rules, and returns the pair of pointers as required.

