Sure, here is a generic C++ implementation of the Selection Sort algorithm which works both on integer and string arrays.

```c++
#include <iostream>
#include <string>

using namespace std;

template <typename T>
void swap(T *xp, T *yp) {
    T temp = *xp;
    *xp = *yp;
    *yp = temp;
}

template <typename T>
void selectionSort(T arr[], int n) {
    int i, j, min_idx;

    for(i = 0; i < n - 1; i++) {
        min_idx = i;

        for(j = i + 1; j < n; j++)
          if(arr[j] < arr[min_idx])
            min_idx = j;

        swap(&arr[min_idx], &arr[i]);
    }
}

template <typename T>
void printArray(T arr[], int size) {
    for(int i = 0; i < size; i++)
        cout << arr[i] << " ";
    cout << endl;
}

int main() {
    int arr[] = { 7, 4, 3, 1, 9 };
    string strArr[] = { "banana", "apple", "grape", "peach", "kiwi" };
    int nI = sizeof(arr) / sizeof(arr[0]);
    int nS = sizeof(strArr) / sizeof(strArr[0]);

    cout << "Array before sorting: \n";
    printArray(arr, nI);

    selectionSort(arr, nI);

    cout << "Array after sorting: \n";
    printArray(arr, nI);

    cout << "String array before sorting: \n";
    printArray(strArr, nS);

    selectionSort(strArr, nS);

    cout << "String array after sorting: \n";
    printArray(strArr, nS);

    return 0;
}
```

