        for (int i = 0; i < dt1.month - 1; i++)
            n1 += monthDays[i];
        n1 += countLeapYears(dt1);
        long int n2 = dt2.year * 365 + dt2.day;
        for (int i = 0; i < dt2.month - 1; i++)
            n2 += monthDays[i];
        n2 += countLeapYears(dt2);
        return (n2 - n1);
    }
};

int monthDays[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

