#include <iostream>
#include <vector>
#include <algorithm>
#include <math.h>

std::vector<float> derivative(const std::vector<float>& xs){
  std::vector<float> result(xs.size());
  // iterate over each element of the source vector,
  // perform operation and store result in destination vector
  std::transform(xs.begin(), xs.end(), result.begin(), [n = 0](float x) mutable { return ++n * exp(1/n) * x; });
