```C++
#include<iostream>
using namespace std;

bool isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return false;
    }
    return true;
}

int largest_prime_divisor(int n){
    if (n <= 1) return -1;
    for (int i = n - 1; i >= 2; i--) {
        if (n % i == 0 && isPrime(i)) {
            return i;
        }
    }
    return -1;
}

