You can accomplish this in C++ using the in-built sort function provided by the `algorithm` library. We can provide a custom comparator function to the sort function to enforce our own sorting criteria. 

In the custom comparator function, we will compare two strings character by character. If we find a pair of characters where one is capital and one is lower-case, we will give priority to the capital letter. If both characters are of the same case, we will compare them normally.

Here is an example implementation:

```cpp
#include<iostream>
#include<algorithm>
#include<vector>
#include<cctype>

// Custom comparator function.
bool caseSensitiveCompare(const std::string &a, const std::string &b){
    auto itA = a.begin(), itB = b.begin();
    while (itA != a.end() && itB != b.end()){
        char upperA = toupper(*itA), upperB = toupper(*itB);
        if (upperA != upperB)
            return upperA < upperB;
        else if (*itA != *itB)
            return *itA < *itB;
        ++itA;
        ++itB;
    }
    return a.size() < b.size();
}

int main(){
    std::vector<std::string> strList = {"Apple", "banana", "Cherry", "apple", 
                                        "Banana", "cherry", "donkey", "Elephant"};

    // Sort the list using our custom comparator function.
    std::sort(strList.begin(), strList.end(), caseSensitiveCompare);

    // Print out the sorted list.
    for(const auto& str : strList){
        std::cout << str << std::endl;
    }

    return 0;
}
```

