The C++ language does not have a built-in solution for generating prime numbers or combinations, unlike Python. However, you can implement these functions manually. Here is a C++ solution that resembles the Python algorithm given:

```cpp
#include <algorithm>
#include <cmath>
#include <vector>
#include <iostream>

std::vector<int> generate_primes(int n) {
    std::vector<bool> prime(n + 1, true);
    prime[0] = prime[1] = false;
    for (int p = 2; p * p <= n; p++) {
        if (prime[p] == true) {
            for (int i = p * p; i <= n; i += p)
                prime[i] = false;
        }
    }
    std::vector<int> primes;
    for (int i = 2; i <= n; i++)
        if (prime[i])
            primes.push_back(i);
    return primes;
}

bool is_multiply_prime(int n) {
    std::vector<int> primes = generate_primes(std::sqrt(n));
    for (int i = 0; i < primes.size(); i++) {
        for (int j = i + 1; j < primes.size(); j++) {
            for (int k = j + 1; k < primes.size(); k++) {
                for (int l = k + 1; l < primes.size(); l++) {
                    if (primes[i] * primes[j] * primes[k] * primes[l] == n)
                        return true;
                }
            }
        }
    }
    return false;
}

int main() {
    int n;
    std::cout << "Enter a number: ";
    std::cin >> n;
    if(is_multiply_prime(n)) {
        std::cout << "True\n";
    } else {
        std::cout << "False\n";
    }
    return 0;
}
```
In this program, the `generate_primes` function is used to generate all primes up to the square root of n, using the Sieve of Eratosthenes algorithm. The `is_multiply_prime` function then checks all distinct combinations of these primes to see if any combination multiplies to give the original number. These combinations are generated by using four nested loops.

