```cpp
#include <string.h>

class Student {
public: 
    char* firstName;
    char* lastName;
    int* age;

    // Default Constructor
    Student() : firstName(new char[1]), lastName(new char[1]), age(new int(0)) {
        this->firstName[0] = '\0';
        this->lastName[0] = '\0';
    }

    // Parameterized Constructor
    Student(const char* firstName, const char* lastName, int age) : firstName(new char[strlen(firstName)+1]), lastName(new char[strlen(lastName)+1]), age(new int(age)) {
        strcpy(this->firstName, firstName);
        strcpy(this->lastName, lastName);
    }

    // Copy Constructor
    Student(const Student &s) : firstName(new char[strlen(s.firstName)+1]), lastName(new char[strlen(s.lastName)+1]), age(new int(*(s.age))) {
        strcpy(this->firstName, s.firstName);
        strcpy(this->lastName, s.lastName);
    }

    // Move Constructor
    Student(Student &&s) noexcept : firstName(s.firstName), lastName(s.lastName), age(s.age) {
        s.firstName = nullptr;
        s.lastName = nullptr;
        s.age = nullptr;
    }

    // Destructor
    ~Student() {
        delete[] firstName;
        delete[] lastName;
        delete age;
    }

    // Move Assignment Operator
    Student& operator=(Student &&s) noexcept {
        if (this != &s) {
            delete[] firstName;
            delete[] lastName;
            delete age;
            firstName = s.firstName; 
            lastName = s.lastName; 
            age = s.age;
            s.firstName = nullptr; 
            s.lastName = nullptr; 
            s.age = nullptr;
        }
        return *this;
    }

    // Copy Assignment Operator
    Student& operator=(const Student &s) {
        if (this != &s) {
            delete[] firstName;
            delete[] lastName;
            delete age;
            firstName = new char[strlen(s.firstName)+1];
            lastName = new char[strlen(s.lastName)+1];
            age = new int(*(s.age));
            strcpy(this->firstName, s.firstName);
            strcpy(this->lastName, s.lastName);
        }
        return *this;
    }

    // Equality Operator
    bool operator==(const Student &s) const {
        return strcmp(firstName, s.firstName) == 0 &&
               strcmp(lastName, s.lastName) == 0 &&
               *age == *(s.age);
    }
};
```

