class ThreadSafeQueue {
private:
    CRITICAL_SECTION _cs;
    std::queue<int> _queue;

public:
    ThreadSafeQueue() {
        InitializeCriticalSection(&_cs);
    }

    ~ThreadSafeQueue() {
        DeleteCriticalSection(&_cs);
    }

    void Enqueue(int value) {
        EnterCriticalSection(&_cs);
        _queue.push(value);
        LeaveCriticalSection(&_cs);
    }

    int Dequeue() {
        EnterCriticalSection(&_cs);
        while (_queue.empty()) {
            SleepConditionVariableCS(&_queueNotEmpty, &_cs, INFINITE);
        }
        int value = _queue.front();
        _queue.pop();
        LeaveCriticalSection(&_cs);
        return value;
    }

    bool IsEmpty() {
        EnterCriticalSection(&_cs);
        bool empty = _queue.empty();
        LeaveCriticalSection(&_cs);
        return empty;
    }
};
```

In the solution, a `ThreadSafeQueue` class is defined, which encapsulates a Win32 critical section and a standard queue. The `Enqueue` operation locks the critical section, adds the value to the queue, and then releases the lock. The `Dequeue` operation waits on a condition variable until the queue is not empty, then locks the critical section, dequeues the value, and releases the lock. The `IsEmpty` operation simply checks if the queue is empty within the critical section.

