class MyCircularQueue {
    public:
        int *que;
        int front, rear, capacity;

        MyCircularQueue(int k) {
            que = new int[k];
            front = -1;
            rear = -1;
            capacity = k;
        }

        bool enQueue(int value) {
            if (isFull()) {
                throw "Queue is full.";
            }
            if (isEmpty()) {
                front = rear = 0;
            } else {
                rear = (rear + 1) % capacity;
            }
            que[rear] = value;
            return true;
        }

        bool deQueue() {
            if (isEmpty()) {
                throw "Queue is empty.";
            }
            if (front == rear) {
                front = rear = -1;
            } else {
                front = (front + 1) % capacity;
            }
            return true;
        }

        int Front() {
            if (isEmpty()) {
                throw "Queue is empty.";
            }
            return que[front];
        }

        int Rear() {
            if (isEmpty()) {
                throw "Queue is empty.";
            }
            return que[rear];
        }

        bool isEmpty() {
            return front == -1;
        }

        bool isFull() {
            return (rear + 1) % capacity == front;
        }

        MyCircularQueue intersect(MyCircularQueue& other) {
            MyCircularQueue intersectQueue(SIZE);

            for (int i = front; i != rear; i = (i + 1) % capacity) {
                for (int j = other.front; j != other.rear; j = (j + 1) % other.capacity) {
                    if (que[i] == other.que[j]) {
                        intersectQueue.enQueue(que[i]);
                        break;
                    }
                }
            }
        return intersectQueue;
        }
};


