#include<string>
#include<cctype>

std::tuple<std::string, std::unordered_map<char, int>, int> invert_case_special(std::string str) {
    std::reverse(str.begin(), str.end());
    std::string modifiedStr;
    int digitSum = 0;
    std::unordered_map<char, int> charCount;
    for (const auto& ch : str) {
