#include<iostream>
using namespace std;

void bubbleSort(int arr[], int n)
{
   for(int i = 0; i < n-1; i++)
   {
        for (int j = 0; j < n-i-1; j++)
        {
           // If current element is greater than the next
           if (arr[j] > arr[j+1])
           {
              // Swap the elements
              int temp = arr[j];
              arr[j] = arr[j+1];
              arr[j+1] = temp;
           }
        }
   }
}

void printArray(int arr[], int size)
{
   for (int i = 0; i < size; i++)
       cout << arr[i] << " ";
   cout << endl;
}

