```C++
#include <iostream>
#include <new> // necessary for std::bad_alloc

int* arr;
int size;
int* prod;

// Function for product calculation
int* calculateProduct(int* arr, int size)
{
    int* prod = new (std::nothrow) int;

    if (!prod) return nullptr; // If allocation failed, return nullptr

    *prod = 1;

    for (int* ptr = arr; ptr < arr + size; ptr++)
    {
        *prod *= *ptr;
    }

    return prod;
}

// Function to release allocated memory
void freeMemory(int* arr, int* prod)
{
    delete[] arr;
    delete prod;
}

