    std::cin >> size;

    // Dynamic memory allocation
    try
    {
        arr = new int[size];
    }
    catch (std::bad_alloc& ba)
    {
        std::cout << ba.what() << "\n";
        return -1;
    }

    std::cout << "Enter array elements: ";
    for (int i = 0; i < size; i++)
    {
        std::cin >> arr[i];
    }

    prod = calculateProduct(arr, size);

    if (!prod)
    {
        std::cout << "Memory allocation for product failed.\n";
        freeMemory(arr, prod);
        return -1;
    }

    std::cout << "Product of array elements: " << *prod << "\n";

    // Free the dynamically allocated memory
