    def __init__(self, name):
        self.name = name

class Rectangle(Shape):
    def __init__(self, name, length, width):
        super().__init__(name)
        self.length = length
        self.width = width

r = Rectangle("Rectangle", 10, 5)
print(r.name)  # Outputs: Rectangle
```

