a:
Here's how you can solve the problem in C++:

```c++
string sort_letters_within_words(string s) {
    size_t start = 0;
    size_t end = s.find(' ');

    while (start < s.size()) {
        if (end == string::npos) // no more spaces found
            end = s.size();

        // sort each word in-place, keeping the case-sensitivity
        string upperPart = "", lowerPart = "";
        for (size_t i = start; i < end; i++) {
            if (isupper(s[i])) 
                upperPart += s[i];
            else 
                lowerPart += s[i];
        }

        sort(upperPart.begin(), upperPart.end());
        sort(lowerPart.begin(), lowerPart.end());

        replace(s.begin() + start, s.begin() + end, s.substr(start, end - start), upperPart + lowerPart);

        // find next word
        start = end + 1;
        end = s.find(' ', start);
    }

    return s;
}
```
