#include <iostream>
#include <fstream>
#include <string>

class AltFile {
private:
    std::string filename;
    std::fstream fileStream;
    bool isOpen;

public:
    AltFile(const std::string& filename) : filename(filename), isOpen(false) {}

    bool open() {
        fileStream.open(filename, std::ios::in | std::ios::out | std::ios::app);
        isOpen = fileStream.is_open();
        return isOpen;
    }

    void write(const std::string& data) {
        if (isOpen) {
            fileStream << data;
        } else {
            std::cerr << "Error: File is not open for writing." << std::endl;
        }
    }

    std::string read() {
        std::string content;
        if (isOpen) {
            fileStream.seekg(0, std::ios::beg);
            std::getline(fileStream, content, '\0');
        } else {
            std::cerr << "Error: File is not open for reading." << std::endl;
        }
        return content;
    }

    void close() {
        if (isOpen) {
            fileStream.close();
            isOpen = false;
        } else {
            std::cerr << "Error: File is not open for closing." << std::endl;
        }
    }
};

int main() {
    AltFile file("test.tmp");
    if (file.open()) {
        file.write("Hello, World!");
        std::cout << "File content: " << file.read() << std::endl;
        file.close();
    } else {
        std::cerr << "Failed to open the file." << std::endl;
    }
    return 0;
}
```

