// Function to check whether a number is prime
bool isPrime(int n) {
    if (n <= 1 || (n % 2 == 0 && n > 2)) 
        return false;
    for (int i = 3; i <= sqrt(n); i += 2) {
        if (n % i == 0) 
            return false;
    }
