Here is a low level solution that works without utilizing inbuilt functions to handle the task of sorting and unifying. This code first removes duplicates in the vector by comparing each element with every other element. Then it sorts the vector using a simple selection sort.

```cpp
#include<stdio.h>
#include<vector>

using namespace std;

vector<int> unique(vector<int> l)
{
    //Code for removing duplicates
    for(int i=0; i<l.size(); i++) 
    {
         for(int j = i+1; j<l.size();) 
         {
             if(l[j]==l[i])
             {
                 l.erase(l.begin()+j);
             }
             else
             {
                j++;
             }
         } 
    }

    //Code for sorting
    for (int i = 0; i < l.size(); i++) 
    {
        int min = i;
        for (int j = i + 1; j < l.size(); j++)
            if (l[j] < l[min])
                min = j;
        if (min != i)
        {
            int temp = l[i];
            l[i] = l[min];
            l[min] = temp;
        }
    }
    return l;
}
```

This code will effectively remove all duplicate elements from the vector and then sort the remaining unique elements. The runtime complexity is relatively high due to the duplicate removal approach, it is O(n^2). If allowed to use Data Structures like Set or Map, we can reduce the time complexity significantly.

