#include <iostream>
#include <string>

template <class T>
class Node {
public:
    T data;
    Node* next;

    Node(T val) : data(val), next(nullptr) {}
};

template <class T>
class Stack {
private:
    Node<T>* topNode;

public:
    Stack() : topNode(nullptr) {}

    void push(T val) {
        Node<T>* newNode = new Node<T>(val);
        newNode->next = topNode;
        topNode = newNode;
    }

    void pop() {
        if (topNode != nullptr) {
            Node<T>* temp = topNode;
            topNode = topNode->next;
            delete temp;
        }
    }

    T top() {
        if (topNode != nullptr) {
            return topNode->data;
        }
        throw std::out_of_range("Stack is empty");
    }

    bool empty() {
        return topNode == nullptr;
    }

    ~Stack() {
        while (topNode != nullptr) {
            Node<T>* temp = topNode;
            topNode = topNode->next;
            delete temp;
        }
    }
};

int main() {
