```C++
#include <vector>
#include <set>
#include <string>

// This function returns either "Positive", "Negative", or "Zero" depending on the 
// product of distinct non-zero integers in the input array. If the product is larger
// than zero it returns "Positive", if it is less than zero it returns "Negative",
// and if it equals zero it returns "Zero".
std::string prod_signs(std::vector<int> arr)
{
    // use a set to remove duplicates from the input array
    std::set<int> s(arr.begin(), arr.end());

    // create a new vector from the set to remove zeros
    std::vector<int> arr2;
    for(const auto& num : s)
        if(num != 0)
            arr2.push_back(num);

    // if the new vector is empty, return "Zero"
    if(arr2.empty())
        return "Zero";

    // calculate the product of the non-zero distinct integers
    long long product = 1; // use long long to avoid overflow
    for(const auto& num : arr2)
        product *= num;

    // return "Positive", "Negative", or "Zero" based on the product value
    if(product > 0)
        return "Positive";
    else if(product < 0)
        return "Negative";
    else
        return "Zero";
}
