Applying Fourier Transform to a sequence of complex numbers is a fundamental concept in fields like image processing, data transmission etc. Here is a C++ code that implements a basic version of the Discrete Fourier Transform (DFT) on an array of complex numbers.

```cpp
#include <complex>
#include <vector>
#include <cmath>

// Define complex number type
typedef std::complex<double> Complex;

// Function to compute DFT
std::vector<Complex> DFT(const std::vector<Complex>& input) {
    int N = input.size();
    double theta;
    std::vector<Complex> output(N);
    for (int k = 0; k < N; k++) {
        Complex sum(0.0, 0.0);
        for (int n = 0; n < N; n++) {
            theta = -2 * M_PI * k * n / N;
            Complex exp_part(cos(theta), sin(theta));
            sum += input[n] * exp_part;
        }
        output[k] = sum;
    }
    return output;
}

int main() {
    // Initialize complex number array
    std::vector<Complex> B = {Complex(1,2), Complex(3,4), Complex(5,6)};

    // Compute and print DFT
    std::vector<Complex> transformed = DFT(B);
    for (int i = 0; i < transformed.size(); i++) {
        std::cout << transformed[i] << std::endl;
    }
    return 0;
}
```

