Here is the equivalent algorithm to check for prime numbers in C++:

```c++
#include <cmath>

// Function to check for prime
bool check_prime(int n) {
    // If number is less than or equal to 1, it is not prime
    if (n <= 1)
        return false;

    // The numbers 2 and 3 are prime
    else if (n <= 3)
        return true;

    // If number is divisible by 2 or 3, it is not prime
    else if (n % 2 == 0 || n % 3 == 0)
        return false;

    // Start from 5, if it is divisible by i or i+2, then it is not prime
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0)
            return false;
    }

    // After all those checks, if we didn't return false, then the number is prime
    return true;
}
