#include <vector>
#include <string>

std::vector<std::vector<int>> locate_str(std::vector<std::vector<std::string>> data, std::string x) {
    std::vector<std::vector<int>> indexes;
    for (int i = 0; i < data.size(); ++i) {
        for (int j = 0; j < data[i].size(); ++j) {
            if (data[i][j] == x) {
