Yes, C++ provides a mechanism called SFINAE (Substitution Failure Is Not An Error) where you can put some checks on the type of template parameter, and if it fails to match the expected type, then the compiler ignores that declaration/definition. Here's an example:

```cpp
#include<iostream>

class Animal
{
public:
    void walk() const
    {
        std::cout << "Animal walking\n";
    }
};

template <typename T>
class MyGenericClass
{
public:
    void doSomething()
    {
        Animal obj = static_cast<T>(*this);
        obj.walk();
    }
};

class Dog : public Animal
{
};

class Person
{
};

int main()
{
     MyGenericClass<Dog> obj1;
     obj1.doSomething();

     //MyGenericClass<Person> obj2; // Uncomment this and you will get a compile-time error
     //obj2.doSomething();
}
```

