bool isPalindrome(std::string input) {
    int begin = 0;
    int end = input.size() - 1;

    while (begin < end) {
        if (input[begin] != input[end]) {
            return false;
        }
        begin++;
        end--;
    }

    return true;
}

// function to find the longest palindrome substring
std::string longestPalindrome(std::string input) {
    int length = input.size();
    std::string longest = "";

    // searching for palindrome from the biggest possible size to the smallest
    for (int i = length; i > 0; i--) {
        for (int j = 0; j <= length - i; j++) {
            std::string temp = input.substr(j, i);
            if (isPalindrome(temp) && temp.size() > longest.size()) {
                longest = temp;
            }
        }
    }

    return longest;
}

