#include <iostream>

struct Node {
  int data;
  Node* next;
};

// Function to add node at the end of the list
void insertNode(Node** head, int newData) {
  Node* newNode = new Node();
  newNode->data = newData;
  newNode->next = NULL;

  if (*head == NULL) {
    *head = newNode;
    return;
  }

  Node* last = *head;
  while (last->next) {
    last = last->next;
  }

  last->next = newNode;
}

// Function to reverse the list
void reverseList(Node** head) {
  Node* prev = NULL;
  Node* current = *head;
  Node* next = NULL;

  while (current) {
    next = current->next;
    current->next = prev;
    prev = current;
    current = next;
  }

  *head = prev;
}

// Function to print the list
void printList(Node* head) {
  while (head) {
    std::cout << head->data << " ";
    head = head->next;
  }

  std::cout << "\n";
}

int main() {
  Node* head = NULL;

  insertNode(&head, 10);
  insertNode(&head, 20);
  insertNode(&head, 30);
  insertNode(&head, 40);

  std::cout << "Original list: ";
  printList(head);

  reverseList(&head);

  std::cout << "Reversed list: ";
  printList(head);

  return 0;
}
```

