complex<double> poly(const vector<complex<double>>& coeff, const complex<double>& x) {
  if (coeff.empty()) {
    throw invalid_argument("Degree of polynomial can't be zero.\n");
  }
  complex<double> val = coeff[0];
  for (int i = 1; i < coeff.size(); i++) {
    val += coeff[i] * pow(x, i);
  }
  return val;
}

complex<double> find_zero(const vector<complex<double>>& coeff) {
  if (coeff.size() < 2) {
    throw invalid_argument("For solutions, Degree of polynomial must be greater than zero.\n");
  }
  if (coeff[coeff.size() - 1] == complex<double>(0, 0)) {
    throw invalid_argument("The leading coefficient can't be zero.\n");
  }
  for (complex<double> x(0, 0); x.imag() < 10000.0; x += complex<double>(0.01, 0.01)) {
    if (abs(poly(coeff, x)) < 1e-5) {
