#include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* next;

    Node(int val) : data(val), next(nullptr) {}
};

class Stack {
private:
    Node* top;

public:
    Stack() : top(nullptr) {}

    void push(int val) {
        Node* newNode = new Node(val);
        newNode->next = top;
        top = newNode;
    }

    void pop() {
        if (top == nullptr) {
            cout << "Stack underflow" << endl;
            return;
        }
        Node* temp = top;
        top = top->next;
        delete temp;
    }

    void display() {
        Node* temp = top;
        while (temp != nullptr) {
            cout << temp->data << " ";
            temp = temp->next;
        }
    }

    void reverse() {
        Node *prev = nullptr, *current = top, *next = nullptr;
        while (current != nullptr) {
            next = current->next;
            current->next = prev;
            prev = current;
            current = next;
        }
        top = prev;
    }
};

int main() {
    int n, val;
    Stack* s = new Stack();

    cout << "Enter the number of elements : ";
    cin >> n;

    cout << "Enter the elements : ";
    while (n--) {
        cin >> val;
        s->push(val);
    }

    cout << "Original Stack" << endl;
    s->display();
    cout << endl;

    s->reverse();

    cout << "Reversed Stack" << endl;
    s->display();

    return 0;
}
