Here's a simple blueprint for a bisynchronous-list data structured in C++. In this context, "bisynchronous" is taken to refer to a doubly-linked list, where each node is linked with both its preceding and following node, allowing for optimized retrieval operations.

The structure of the node is described first:

```cpp
struct Node {
    int data;
    Node* next;
    Node* prev;
};
```
The BisyncList class with the prioritized retrieval operations:

```cpp
class BisyncList {
private:
    Node* head;
    Node* tail;
public:
    BisyncList() : head(nullptr), tail(nullptr) {}

    void addToFront(int);
    void addToBack(int);
    int retrieveFront();
    int retrieveBack();
    void display();
};
```

And then we implement the methods:

```cpp
void BisyncList::addToFront(int data) {
    Node* node = new Node();
    node->data = data;
    node->next = head;
    node->prev = nullptr;

    if(head != nullptr) {
        head->prev = node;
    }
    if(tail == nullptr) {
        tail = head;
    }
    head = node;
}

void BisyncList::addToBack(int data) {
    Node* node = new Node();
    node->data = data;
    node->prev = tail;
    node->next = nullptr;

    if(tail != nullptr) {
         tail->next = node; 
    }
    if(head == nullptr) {
        head = tail;
    }
    tail = node;
}

int BisyncList::retrieveFront() {
    if(head == nullptr) throw std::runtime_error("List is empty");

    int data = head->data;
    Node* node = head;
    head = node->next;

    if(head != nullptr) {
        head->prev = nullptr;
    }
    else {
        tail = nullptr;
    }

    delete node;
    return data;
}

int BisyncList::retrieveBack() {
    if(tail == nullptr) throw std::runtime_error("List is empty");

    int data = tail->data;
    Node* node = tail;
    tail = node->prev;

    if(tail != nullptr) {
        tail->next = nullptr;
    }
    else {
        head = nullptr;
    }

    delete node;
    return data;
}

void BisyncList::display() {
    Node* temp = head;
    while(temp != nullptr) {
        std::cout << temp->data << " ";
        temp = temp->next;
    }
    std::cout << std::endl;
}
```
The retrieval operations retrieveFront and retrieveBack prioritise retrieval from the front and back respectively, before adjusting the next and prev pointers as necessary for the remaining elements in the list.

