```cpp
#include <vector>
#include <stack>
#include <limits>

namespace elang {
    namespace {
        typedef std::vector<int> IntVector;

        class MinStack {
        private:
            std::stack<int> dataStack;
            std::stack<int> minStack;

        public:
            void push_back(int val) {
                dataStack.push(val);
                if (minStack.empty() || val <= minStack.top()) {
                    minStack.push(val);
                }
            }

            void pop_back() {
                if (dataStack.top() == minStack.top()) {
                    minStack.pop();
                }
                dataStack.pop();
            }

            int get_min() {
                return minStack.top();
            }
        };
    }
}
```
The `MinStack` class is implemented using two stacks: `dataStack` to store the actual elements and `minStack` to keep track of the minimum value at any point. The `push_back` operation adds the element to `dataStack` and updates `minStack` if the added element is smaller or equal to the current minimum. The `pop_back` operation removes the top element from both stacks if necessary. The `get_min` operation retrieves the top element from `minStack`, which represents the current minimum value in the stack. All operations have O(1) time complexity.

