A BST (Binary Search Tree) is a tree data structure in which each parent node has at most two children, which are referred to as the left child and the right child. By property, the left child has a lesser value than its parent node and the right child has a greater value.

To find the maximum value in a BST, we just need to go to the rightmost node because BST property ensures that the node's values are increasing as we move right. Here's the recursive approach to solve the problem:

```C++
// A BST node
struct Node
{
    int data;
    struct Node *left, *right;
};

// Function to create a new node
Node* new_node(int data)
{
    Node* temp = new Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

// Function to insert in Binary Search Tree
Node* insert(Node* node, int data)
{
    if (node == NULL)
        return new_node(data);

    if (data < node->data)
        node->left  = insert(node->left, data);
    else if (data > node->data)
        node->right = insert(node->right, data);

    return node;
}

// Function to find maximum value in BST
int find_max(Node* node)
{
    if(node == NULL)
        return -1;  // or INT_MIN if you want to handle empty tree specifically
    else if(node->right == NULL)
       return node->data;
    else
       return find_max(node->right);
}

// Driver Code
int main()
{
    Node* root = NULL;
    root = insert(root, 20);
    insert(root, 10);
    insert(root, 30);
    insert(root, 5);
    insert(root, 15);
    insert(root, 25);
    insert(root, 35);

    cout << "Maximum value in BST is " << find_max(root);

    return 0;
}
```

Here, we first insert values into our BST and then call function `find_max` to find maximum value in the BST. `find_max` function is recursive and keeps going right until it finds a node which does not have right child and returns its value.

