1. `CircularBuffer(int size)`: Constructor that initializes the circular buffer with the given size.
2. `void write(int value)`: Method to write a value to the circular buffer. If the buffer is full, the oldest value should be overwritten.
3. `int read()`: Method to read the oldest value from the circular buffer and remove it from the buffer. If the buffer is empty, return -1.

You should implement the circular buffer using an array and keep track of the current read and write positions.

Your task is to complete the implementation of the `CircularBuffer` class and its methods.

```cpp
#include <iostream>
using namespace std;

class CircularBuffer {
private:
    int *buffer;
    int size;
    int readIndex;
    int writeIndex;
    bool full;

public:
    CircularBuffer(int size) : size(size), readIndex(0), writeIndex(0), full(false) {
        buffer = new int[size];
    }

    void write(int value) {
        buffer[writeIndex] = value;
        writeIndex = (writeIndex + 1) % size;
        if (writeIndex == readIndex) {
            readIndex = (readIndex + 1) % size;
            full = true;
        }
    }

    int read() {
        if (readIndex == writeIndex && !full) {
            return -1; // Buffer is empty
        }
        int value = buffer[readIndex];
        readIndex = (readIndex + 1) % size;
        full = false;
        return value;
    }

    ~CircularBuffer() {
        delete[] buffer;
    }
};

int main() {
    CircularBuffer cb(5);
    cb.write(1);
    cb.write(2);
    cb.write(3);
    cout << cb.read() << endl;  // Output: 1
    cout << cb.read() << endl;  // Output: 2
    cb.write(4);
