class CThreadLocalStorage
{
public:
    CThreadLocalStorage() : m_tlsMap() {}

    ~CThreadLocalStorage()
    {
        for (auto& pair : m_tlsMap)
        {
            delete pair.second;
        }
    }

    template <typename T>
    void Set(T* value)
    {
        std::thread::id this_id = std::this_thread::get_id();
        m_tlsMap[this_id] = value;
    }

    template <typename T>
    T* Get()
