#include <mutex>
#include <stack>

class Uncopyable {
protected:
    Uncopyable() {}
    ~Uncopyable() {}

private:
    Uncopyable(const Uncopyable&);
    Uncopyable& operator=(const Uncopyable&);
};

class CriticalSection {
public:
    void Lock() {
        mutex.lock();
    }

    void Unlock() {
        mutex.unlock();
    }

private:
    std::mutex mutex;
};

class ScopedLock : private Uncopyable {
public:
    ScopedLock(CriticalSection& criticalSection)
        : cs(criticalSection) {
        REF_CHECK(criticalSection);
        cs.Lock();
    }

    ~ScopedLock() {
        cs.Unlock();
    }

private:
    CriticalSection& cs;
};

template <typename T>
class ThreadSafeStack {
public:
    void Push(const T& value) {
        ScopedLock lock(cs);
        data.push(value);
    }

    bool Pop(T& value) {
        ScopedLock lock(cs);
        if (data.empty()) {
            return false;
        }
        value = data.top();
        data.pop();
        return true;
    }

    bool IsEmpty() {
        ScopedLock lock(cs);
        return data.empty();
    }

private:
    std::stack<T> data;
    CriticalSection cs;
};
```

In the solution, the ScopedLock class is used to protect the critical section of the stack operations. The CriticalSection class provides the necessary locking mechanism using a mutex. The ThreadSafeStack class uses the ScopedLock to ensure thread safety for the push, pop, and IsEmpty operations on the stack. The implementation guarantees that concurrent access to the stack does not lead to data corruption or race conditions.

