Here the goal is to remove the duplicates from the array and place them at the end of the array. The following steps can be implemented in a programming language like C++.

1. First of all, sort the array. So array after sorting will be {1,2,2,2,3,3,3,7,11,15}.

2. Iterate over the array and compare the current element with the next one.

3. If they are the same, swap the duplicate element with the element at index (n-1-i) where n is the total number of elements in the array and 'i' is the current index. Also decrease the size of array by 1.

4. If they are not the same then just move to next element.

5. Repeat the above steps until the end of array is reached.

Implementation in C++:

```cpp
#include<bits/stdc++.h>
using namespace std;

void removeDuplicates(int arr[], int n){

  sort(arr, arr + n);

  int res = 1;

  for(int i=1; i<n; i++){
    if(arr[i] != arr[res-1]){
      arr[res] = arr[i];
      res++;
    }
    else{
      swap(arr[i--], arr[--n]);
    }
  }

  for(int i=0; i<res; i++)
    cout<<arr[i]<<' ';
  for(int i=res; i<n; i++)
    cout<<arr[i]<<' ';

}

int main(){

  int arr[] = {2,3,7,3,2,11,2,3,1,15};
  int n = sizeof(arr)/sizeof(arr[0]);

  removeDuplicates(arr, n);

  return 0;
}
```

