#include <vector>
#include <stdexcept>

template <typename T>
class StreamManager {
private:
    std::vector<std::vector<T>> streams;  // Vector of vectors to store streams for each protocol version
public:
    explicit StreamManager(const std::vector<size_t>& maxStreamsPerVersion) {
        for (size_t maxStreams : maxStreamsPerVersion) {
            streams.emplace_back(maxStreams);
        }
    }

    T acquire(size_t version) {
        if (version >= streams.size()) {
            throw std::out_of_range("Invalid protocol version");
        }
        for (T& stream : streams[version]) {
            if (stream == 0) {
                stream = 1;
                return stream;
            }
        }
        throw std::runtime_error("No available streams for the specified protocol version");
    }

    void release(size_t version, T stream) {
        if (version >= streams.size()) {
            throw std::out_of_range("Invalid protocol version");
        }
        if (stream > streams[version].size()) {
            throw std::out_of_range("Invalid stream number");
        }
        streams[version][stream - 1] = 0;
    }
};

int main() {
    std::vector<size_t> maxStreamsPerVersion = {5, 3, 4};  // Maximum streams for each protocol version
    StreamManager<int> streamManager(maxStreamsPerVersion);

    // Acquire and release streams for each protocol version
    for (size_t version = 0; version < maxStreamsPerVersion.size(); ++version) {
        for (size_t i = 0; i < maxStreamsPerVersion[version]; ++i) {
            int stream = streamManager.acquire(version);
            std::cout << "Acquired stream " << stream << " for protocol version " << version << std::endl;
        }
        try {
            int invalidStream = streamManager.acquire(version);
        } catch (const std::runtime_error& e) {
            std::cout << e.what() << std::endl;
        }
        streamManager.release(version, 1);
        std::cout << "Released stream 1 for protocol version " << version << std::endl;
    }

    return 0;
}
```

