bool isLeap(int year) {
    return (((year % 4 == 0) && (year % 100 != 0)) || (year % 400 == 0));
}

bool isValidDate(int year, int month, int day) {
    if (year < 1582 || month < 1 || month > 12 || day < 1 || day > 31) {
        return false;
    }

    if (month == 2) {
        if (isLeap(year)) {
            return (day <= 29);
        } else {
            return (day <= 28);
        }
    }

    if (month == 4 || month == 6 || month == 9 || month == 11) {
        return (day <= 30);
    }

    return true;
}

