    istringstream iss(date_in_str);
    vector<string> date_tokens{istream_iterator<string>{iss}, istream_iterator<string>{}};

    string formatted_date = month_map[date_tokens[0]] + "/" + (atoi(date_tokens[1].c_str()) > 9 
