```cpp
#include <iostream>
using namespace std;

int binarySearch(int arr[], int n, int x) {
    int left = 0;
    int right = n - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        // Check if x is present at mid
        if(arr[mid] == x) 
            return mid;

        // If x is greater than mid, ignore the left half
        if(arr[mid] < x) 
            left = mid + 1;

        // If x is smaller, ignore the right half
        else 
            right = mid - 1;
    }

    // If we reach here, then the element was not present
    return -1;
}

int main() {
    int arr[] = {2, 4, 10, 13, 24, 30};
    int n = sizeof(arr) / sizeof(arr[0]);
    int x = 10;

    int result = binarySearch(arr, n, x);

    (result == -1) ? cout << "Element is not present in array"
                   : cout << "Element is present at index " << result;
    return 0;
}
```

In this code snippet, `binarySearch` function implements the binary search algorithm. It takes an array `arr[]`, its size `n` and the target element `x` as inputs. The function returns the index of the target element if it's found, otherwise, it returns -1 indicating the element is not present in the array.

