void findOutliers(const arma::mat &data){
    mlpack::data::StandardScaler scale;
    arma::mat centeredData;

    // Fit the scaler and transform the data
    scale.Fit(data);
    scale.Transform(data, centeredData);

    // Compute the absolute z-scores, i.e., the deviation in standard deviations
    arma::mat absZScores = arma::abs((data - arma::mean(data, 0)) / arma::stddev(data, 0, 0));

    // Detect outliers as those points where all features have a z-score > 3
