        cout << "Base Class Constructor Called!" << endl;
    }

    virtual void display() {
        cout << "Display Base Class" << endl;
    }

    virtual ~BaseClass(){
        cout << "Base Class Destructor Called!" << endl;
    }
};

// Derived Class
class DerivedClass : public BaseClass {
public:
    // Default Constructor
    DerivedClass(){
        cout << "Derived Class Constructor Called!" << endl;
    }

    // Overloaded Constructor
    DerivedClass(int a){
        cout << "Derived Class Overloaded Constructor Called!" << endl;
    } 

    void display() {
        cout << "Display Derived Class" << endl;
    }

    ~DerivedClass(){
        cout << "Derived Class Destructor Called!" << endl;
    }
};

int main() {
    // Scenario 1: --Creating Base Object--
    BaseClass baseObj;
    baseObj.display();

    // Scenario 2: --Creating Derived Object with Default Constructor--
    DerivedClass derivedObj;
    derivedObj.display();

    // Scenario 2: --Creating Derived Object with Overloaded Constructor--
    DerivedClass derivedObjOverloaded(10);
    derivedObjOverloaded.display();

    // Scenario 4: --Using Base Class Pointers--
    BaseClass* basePtr = new DerivedClass;
    basePtr->display();
    delete basePtr;

    return 0;
}
