#include <iostream>
#include <dlfcn.h> // for Unix-based systems
#include <windows.h> // for Windows systems

class DynamicLoader {
private:
    void* libraryHandle;

public:
    DynamicLoader() : libraryHandle(nullptr) {}

    bool loadLibrary(const std::string& libraryPath) {
        #ifdef _WIN32
            libraryHandle = LoadLibrary(libraryPath.c_str());
        #else
            libraryHandle = dlopen(libraryPath.c_str(), RTLD_LAZY);
        #endif

        if (libraryHandle == nullptr) {
            std::cerr << "Error loading library: " << dlerror() << std::endl;
            return false;
        }
        return true;
    }

    void* getFunction(const std::string& functionName) {
        #ifdef _WIN32
            return GetProcAddress((HMODULE)libraryHandle, functionName.c_str());
        #else
            return dlsym(libraryHandle, functionName.c_str());
        #endif
    }

    void executeFunction(void (*function)()) {
        if (function != nullptr) {
            function();
        } else {
            std::cerr << "Error executing function: Function pointer is null." << std::endl;
        }
    }

    ~DynamicLoader() {
        #ifdef _WIN32
            if (libraryHandle != nullptr) {
                FreeLibrary((HMODULE)libraryHandle);
            }
        #else
            if (libraryHandle != nullptr) {
                dlclose(libraryHandle);
            }
        #endif
    }
};

int main() {
    DynamicLoader loader;
    if (loader.loadLibrary("example.dll")) {
        void (*exampleFunction)() = (void (*)())loader.getFunction("exampleFunction");
        if (exampleFunction != nullptr) {
            loader.executeFunction(exampleFunction);
        }
    }
    return 0;
}
```

This solution provides a complete implementation of the DynamicLoader class with the required methods to load, retrieve, and execute functions from shared libraries at runtime. The platform-specific code is handled using preprocessor directives to ensure compatibility with both Windows and Unix-based systems. Error handling is also included to handle cases where the library cannot be loaded or the specified function does not exist. The main function demonstrates how to use the DynamicLoader class to load a library, retrieve a function, and execute it.

