// Function to perform circular shift
void circularShift(std::vector<int> &arr, int k) {
    if (arr.empty()) {
        std::cout << "The array is empty. No shift operation can be performed.\n";
        return;
    }

    if (k < 0) {
        std::cout << "Invalid shift number. Shift number must be greater than or equal to zero.\n";
        return;
    }

    k %= arr.size(); // To handle shift values larger than the size of array

    if (k > 0) {
        // Magic Trick to Save Memory with Time Complexity O(n) and Memory Complexity is O(1)
        std::reverse(arr.begin(), arr.end());
        std::reverse(arr.begin(), arr.begin() + k);
        std::reverse(arr.begin() + k, arr.end());
    }
}

// Function to print the array
void printArray(const std::vector<int> &arr) {
    for(int val : arr) {
        std::cout << val << " ";
    }
    std::cout << "\n";
}

