Here is a simple C++ program using Bubble sort algorithm to sort a multidimensional array of strings.

```cpp
#include <iostream>
#include <string>
#include <vector>
using namespace std;

vector<vector<string>> sortArray(vector<vector<string>>& arr) {
    int n = arr.size();
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n*n; j++) {
            for (int k = 0; k < n*n - j - 1; k++) {
                int row1 = k/n;
                int col1 = k%n;
                int row2 = (k+1)/n;
                int col2 = (k+1)%n;
                if (arr[row1][col1].size() > arr[row2][col2].size() ||
                   (arr[row1][col1].size() == arr[row2][col2].size() && arr[row1][col1] > arr[row2][col2])) {
                    swap(arr[row1][col1], arr[row2][col2]);
                }
            }
        }
   }
   return arr;
}

int main() {
    vector<vector<string>> arr = { {"Hello", "World"}, {"This", "Is"}, {"A", "Test"}, {"An", "Example"}, 
                                   {"Multidimensional", "Array"} };
    try {
        arr = sortArray(arr);
        for (int i = 0; i < arr.size(); i++) {
            for (int j = 0; j < arr[i].size(); j++) {
                cout << arr[i][j] << " ";
            }
            cout << endl;
        }
    } catch (...) {
        cout << "An exception occurred" << endl;
    }
    return 0;
}
```
Above code sorts the multidimensional array by length of strings. If two strings have same length, they get sorted in alphabetical order. Catch blocks in the code are for catching and handling any exceptions that might occur during the execution of the program.

