Here is a C++ version of your code using the C++11 regular expression library:

```c++
#include <string>
#include <regex>

std::string user_password_check(std::string password) {
    if (password.length() < 8 || password.length() > 30) {
        return "Invalid";
    }

    if (!std::regex_search(password, std::regex(".*[a-z].*")) ||
        !std::regex_search(password, std::regex(".*[A-Z].*")) ||
        !std::regex_search(password, std::regex(".*[0-9].*"))) {
        return "Invalid";
    }

    if (!std::regex_search(password, std::regex(".*[@#$%&*].*"))) {
        return "Invalid";
    }

    if (std::regex_search(password, std::regex(".*[0-9]{3,}.*"))) {
        return "Invalid";
    }

    if (std::regex_search(password, std::regex(".*\\s.*"))) {
        return "Invalid";
    }

    for (int i = 0; i < password.length() - 2; i++) {
        if (password[i] == password[i+1] && password[i] == password[i+2]) {
            return "Invalid";
        }
    }

    return "Valid";
}
```

