vector<int> getDivisors(int n) {
    vector<int> divisors;
    for(int i=2; i*i <= n; i++) {
        while(n%i == 0) {
            divisors.push_back(i);
            n = n/i;
        }
    }
    if(n > 1)
        divisors.push_back(n);
    return divisors;
}

bool isSemiPrime(int n) {
    vector<int> divisors = getDivisors(n);
    return divisors.size() == 2 && isPrime(divisors[0]) && isPrime(divisors[1]);
}

