Here is a simple C++ program that uses command line arguments to print the sum of all numbers from 1 to the number supplied as argument.

Make sure to convert the command line argument (which is a string) to integer using `stoi()` function.

```cpp
#include<iostream>
#include<cstdlib> // for std::stoi

int main(int argc, char *argv[]) {
    // Check if number of arguments is correct
    if(argc != 2) {
        std::cerr << "Usage: ./prog <number>" << std::endl;
        return 1;
    }
    // Convert argument to integer
    int number = std::stoi(argv[1]);

    // If number is less than 1, then there's no need to sumup
    if(number < 1) {
        std::cerr << "Number must be positive" << std::endl;
        return 1;
    }

    // Calculate sum
    int sum = 0;
    for(int i = 1; i <= number; ++i) {
        sum += i;
    }

    // Print sum
