    Node* opposite;

    Node(int val = 0, Node* prev = nullptr, Node* next = nullptr, Node* opposite = nullptr) :
        val(val), prev(prev), next(next), opposite(opposite) {}
};

class BiSyncList {
private:
    Node* head;
    Node* tail;

public:
    BiSyncList() : head(nullptr), tail(nullptr) {}

    void add(int value) {
        Node* node = new Node(value);
        if(!head) {
            head = tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
            tail->opposite = head;
            head->opposite = tail;
        }
    }

    int get(int index) {
        int count = 0;
        int last = size()-1;        
        Node* temp = (index > last/2) ? head : tail;
        while(temp){
            if((index > last/2 && count == last-index) || (index <= last/2 && count == index)) {
                return temp->val;
            }
            temp = (index > last/2) ? temp->opposite : temp->next;
            count++;
        }
        return -1;
    }

    int size() {
        int count = 0;
        Node* temp = head;
        while(temp){
            temp = temp->next;
            count++;
        }
        return count;
    }

} // End of BiSyncList

int main() {
    BiSyncList list;
    for (int i = 0; i < 10; i++) {
        list.add(i);
    }
    std::cout << "5th element from beginning: " << list.get(5) << std::endl;
    std::cout << "5th element from end: " << list.get(list.size()-6) << std::endl;
    return 0;
}
```
