Here is an equivalent C++ code for the Python program:

```cpp
#include <string>
#include <cctype>
#include <algorithm>
#include "gtest/gtest.h"

std::string stripNonAlphanumeric(const std::string &str) {
    std::string result;
    for (char c : str) {
        if (std::isalnum(c)) {
            result += std::tolower(c);
        }
    }
    return result;
}

bool isPalindrome(const std::string &str) {
    std::string strippedStr = stripNonAlphanumeric(str);
    std::string reversedStr = strippedStr;
    std::reverse(reversedStr.begin(), reversedStr.end());

    return strippedStr == reversedStr;
}

std::string findPalindromicPostfix(const std::string &str) {
    std::string lowerStr = stripNonAlphanumeric(str);
    for (size_t i = 0; i < lowerStr.size(); ++i) {
        if (isPalindrome(lowerStr.substr(i))) {
            return lowerStr.substr(i);
        }
    }
    return "";
}

std::string makePalindrome(const std::string &str) {
    std::string strippedStr = stripNonAlphanumeric(str);
    std::string postfix = findPalindromicPostfix(strippedStr);
    std::string prefix = strippedStr.substr(0, strippedStr.size() - postfix.size());

    std::reverse(prefix.begin(), prefix.end());
    return strippedStr + prefix;
}

