#include <iostream>
#include <unordered_map>
#include <locale>

std::unordered_map<char, int> countLetters(const std::string& text) {
    // Initialize the map with keys as lowercase letters and count of each letter as 0
    std::unordered_map<char, int> count_map;
    for(char c='a';c<='z';c++)
            count_map[c] = 0;

    std::locale loc;
    // Iterate through the string
