#include <iostream>
using namespace std;

// Function to perform cyclic permutation
void cyclePermutation(int arr[], int n)
{
    // Save the last element of array
    int last = arr[n - 1];
    // Shift all elements of the array to the right
    for (int i = n - 1; i > 0; i--)
    {
        arr[i] = arr[i - 1];
    }
    // Replace first element with the last saved
    arr[0] = last;
}

// Function to print array
void printArray(int arr[], int n)
{
    for (int i = 0; i < n; i++)
    {
        cout << arr[i] << " ";
    }
    cout << endl;
}

// Driver code
int main()
{
    int arr[] = {1, 2, 3, 4, 5};
    int n = sizeof(arr)/sizeof(arr[0]);

    cout << "Original Array is: ";
    printArray(arr, n);

    cyclePermutation(arr, n);

    cout << "Array after cyclic permutation: ";
    printArray(arr, n);

    return 0;
}
```

This code basically takes the last element of the array and inserts it at the front, moving all other array elements one position to the right. This operation is done in place, therefore is more memory efficient. This function works in O(n) time complexity. If we have to perform this operation k times, it will take O(k*n) time complexity. 

