#include <iostream>

int largestDivisorOrPrime(int n)
{
    // Prime numbers always start at 1, hence largestDivisor starts at 1
    int largestDivisor = 1;
    // The smallest prime number is 2, so we initialize largestPrime as 2
    int largestPrime = 2;

    // Start iterating from 2 and continue till square root of n
    // This is because a larger factor of a number must be a multiple of smaller factor that has already been checked
    for(int i = 2; i*i <= n; i++)
    {
        // If n is divisible by i, then it means that i is a divisor of n
