                largestDivisor = i > largestDivisor ? i : largestDivisor;

                // If n is divisible by i then decrease the value of n until it is no longer divisible by i and update the value of largestPrime
                while(n % i == 0)
                {
                    largestPrime = i;
                    n = n / i;
                }
        }
    }

    // If n is greater than 1 then n is the largest prime otherwise take the maximum of largestPrime and largestDivisor
    if (n > 1)
