Here is a solution in C++:

```cpp
#include<iostream>
#include<vector>
#include<string>
#include<sstream>
using namespace std;

vector<int> parse_nested_parens(string paren_string){
    vector<int> depths;
    stringstream ss(paren_string);
    string paren_group;

    while(getline(ss, paren_group, ' ')) { // splitting the string by space
        int current_depth = 0;
        int max_depth = 0;
        for(size_t i = 0; i < paren_group.size(); ++i){
            if (paren_group[i] == '(') {
                current_depth++;
                if (current_depth > max_depth) {
                    max_depth = current_depth;
                }
            } else if(paren_group[i] == ')') {
                current_depth--;
            }
        }

        // At this point, max_depth has the maximum depth of parenthetical nesting
        depths.push_back(max_depth);
    }

    return depths;
}

int main() {
    vector<int> depths = parse_nested_parens("(()()) ((())) () ((())()())");
    for(int depth : depths){
        cout << depth << " ";
    }
    return 0;
}
