To build a function that integrates two sorted singly linked lists in ascending order, firstly, we have to create the structure for node representation in singly linked list and then build the function to merge the linked lists. Here's a simple implementation in C++ using a recursive function:

```cpp

#include<bits/stdc++.h>
using namespace std;

struct Node
{
    int data;
    Node* next;
};

Node* SortedMerge(Node* a, Node* b)
{
    Node* result = NULL;

    /* Base cases */
    if (a == NULL)
        return(b);
    else if (b==NULL)
        return(a);

    /* Pick either a or b, and recur */
    if (a->data <= b->data)
    {
        result = a;
        result->next = SortedMerge(a->next, b);
    }
    else
    {
        result = b;
        result->next = SortedMerge(a, b->next);
    }
    return(result);
}

/* Function to insert a node at the end of the linked list */
void Append(Node** head_ref, int new_data)
{
   Node* new_node = new Node();
    Node *last = *head_ref; 
    new_node->data = new_data;
    new_node->next = NULL;

    if (*head_ref == NULL)
    {
        *head_ref = new_node;
        return;
    }

    while (last->next != NULL)
        last = last->next;
    last->next = new_node;
    return;
}

/* Function to print nodes in a given linked list */
void printList(Node *node)
{
    while (node!=NULL)
    {
        cout<<node->data<<" ";
        node = node->next;
    }
}

/* Driver program to test above functions*/
int main()
{
    Node* res = NULL;
    Node* a = NULL;
    Node* b = NULL;

    /* Let us create two sorted linked lists to test
     the functions Created lists, a: 5->10->15, b: 2->3->20 */
    Append(&a, 5);
    Append(&a, 10);
    Append(&a, 15);

    Append(&b, 2);
    Append(&b, 3);
    Append(&b, 20);

    res = SortedMerge(a, b);

    cout << "Merged Linked List is: \n";
    printList(res);

    return 0;
}

```
In this code, a linked list is represented as a pointer to the first node (head). The head pointer points to the first node in the linked list. Each node has an additional field next that points to the next node in the list. If the next pointer of a node is NULL, then it is the last node in the list.

