```c++
#include<iostream>
using namespace std;

// The function which swaps the elements.
void swap(int array1[], int array2[], int idx1, int idx2) {
    // Two integers are swapped by XORing them. The XOR of two numbers x and y gives a number
    // which has all the different bits of x and y set. So, if we XOR x and y, and store it in x,
    // x actually becomes x XOR y. The same value when XORed with y (we get (x XOR y) XOR y, 
    // which is x) gives x and when XORed with x (we get (x XOR y) XOR x, which is y) gives y.
    array1[idx1] = array1[idx1] ^ array2[idx2];
    array2[idx2] = array1[idx1] ^ array2[idx2];
    array1[idx1] = array1[idx1] ^ array2[idx2];
}

// Testing the swap function.
int main() {
    // creating two arrays
    int array1[] = {1,2,3,4,5};
    int array2[] = {6,7,8,9,10};

