    for(int i:array1)
        cout<< i << " ";
    cout<<endl;
    for(int i:array2)
        cout<< i << " ";

    // Swapping first elements.
    swap(array1, array2, 0, 0);

    cout<<"\nAfter swapping: "<<endl;
    for(int i:array1)
        cout<< i << " ";
    cout<<endl;
    for(int i:array2)
        cout<< i << " ";
    return 0;
}
```

