#include <iostream>
#include <map>

class MapPoint {
public:
    virtual const MapPoint* next_entry() const = 0;
    virtual ~MapPoint() {}
};

class MapHelper {
public:
    static std::map<int, const MapPoint*> mapPoints;

    static void addPoint(int enid, const MapPoint* point) {
        mapPoints[enid] = point;
    }

    static const MapPoint* getPoint(int enid) {
        return mapPoints[enid];
    }
};

class MapPointImpl : public MapPoint {
private:
    int enid;

public:
    MapPointImpl(int id) : enid(id) {}

    const MapPoint* next_entry() const override {
        auto it = MapHelper::mapPoints.find(enid);
        if (it != MapHelper::mapPoints.end()) {
            auto nextIt = std::next(it);
            if (nextIt != MapHelper::mapPoints.end()) {
                return nextIt->second;
            }
        }
        return nullptr;
    }
};

