Here's a simple C++ program which uses the Kadane's algorithm to solve this problem. Kadane's algorithm is a dynamic programming algorithm that can solve this problem in O(n) time complexity:

```C++
#include<iostream>
#include<vector>
using namespace std;

pair<int, pair<int, int>> maxSubArraySum(vector<int> a) {
    int size = a.size();
    int max_so_far = INT_MIN, max_ending_here = 0;
    int start = 0, end = 0, s=0;

    for (int i=0; i< size; i++ )
    {
        max_ending_here += a[i];

        if (max_so_far < max_ending_here)
        {
            max_so_far = max_ending_here;
            start = s;
            end = i;
        }

        if (max_ending_here < 0)
        {
            max_ending_here = 0;
            s = i + 1;
        }
    }
    return make_pair(max_so_far, make_pair(start, end));
}

// Function to print the array
void printArray(vector<int> arr, int start, int end) {
    for (int i = start; i <= end; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
}

int main()
{
    vector<int> a = {-2, -3, 4, -1, -2, 1, 5, -3};
    auto result = maxSubArraySum(a);
    cout << "Maximum contiguous sum is " << result.first << endl;
    cout << "Starting index " << result.second.first 
         << "\nEnding index " << result.second.second << endl;
    cout << "And the sub-array is: ";
    printArray(a, result.second.first, result.second.second);
    return 0;
}
```
The above-mentioned program will handle all types of arrays including empty arrays, arrays containing only negative numbers, regular arrays etc. in O(n) time complexity. The algorithm works by looking for all positive contiguous segments of the array (max_ending_here is used for this). And it keeps track of maximum sum contiguous segment among all positive segments (max_so_far is used for this). Each time when we get a positive sum we compare it with max_so_far and update max_so_far if it is greater than max_so_far.

