The following code uses an approach with a time complexity of O(n*m) and space complexity of O(n*m), n and m being the lengths of the two strings. For this, we build a 2D dynamic programming table, dp.

In solving the problem for multiple strings, we adopt pair-wise comparison i.e., we first find the longest common substring for the first two strings, and then find the longest common substring for the result and the next string. This continues until all strings have been considered.

```cpp
#include<bits/stdc++.h>
using namespace std;

// Function to find the longest common substring of strings `X[0…m-1]` and `Y[0…n-1]`
string LCS(string X, string Y, int m, int n)
{
    int maxLength = 0;    // stores the max length of LCS
    int endingIndex = m;  // stores the ending index of LCS in `X`

    // `dp[i+1][j+1]` stores the length of LCS of substring `X[0…i]` and `Y[0…j]`
    int dp[m + 1][n + 1];

    // initialization: as when either length of X or Y is 0
    for (int i = 0; i <= m; i++) {
        dp[i][0] = 0;
    }

    for (int j = 0; j <= n; j++) {
        dp[0][j] = 0;
    }

    // fill the lookup table in bottom-up manner
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {

            // if current character of X and Y matches
            if (X[i - 1] == Y[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;

                // update the maximum length and ending index
                if (dp[i][j] > maxLength) {
                    maxLength = dp[i][j];
                    endingIndex = i - 1;
                }
            }

            // else if current character of X and Y don't match
            else {
                dp[i][j] = 0;
            }
        }
    }

    // return longest common substring having length `maxLength`
    return X.substr(endingIndex - maxLength + 1, maxLength);
}

// main function
int main()
{
    int n;
    cout << "Enter no. of strings: ";
    cin >> n;
    vector<string> strings(n);
    cout << "Enter the strings: ";
    for(int i=0; i<n; i++){
        cin >> strings[i];
    }

    string result = strings[0];
    for (int i = 1; i < n; ++i){
        result = LCS(result, strings[i], result.size(), strings[i].size());
    }

    if (result.size() > 0)
        cout << "The longest common Substring is " << result << '\n';
    else
        cout << "No common Substring exist.\n";

    return 0;
}
```
