C++ also doesn't have built-in function to convert number's string representation from one base to another so we have to convert numbers through binary first.
```c++
#include <iostream>
#include <string>
#include <bitset>

class HexBinaryConverter {
public:
    std::string hexToBinary(std::string y) {
        std::string binary_str = "";
        for(unsigned i = 0; i < y.length(); i++) {
            std::string bin = std::bitset<4>(std::stoi(y.substr(i, 1), nullptr, 16)).to_string();
            binary_str += bin;
        }
        return binary_str;
    }

    std::string binaryToHex(std::string x) {
        unsigned int number = std::bitset<32>(x).to_ulong();
        std::stringstream hex_str;
        hex_str << std::hex << std::uppercase << number;
        return hex_str.str();
    }
};
```

