Here you'll find a simplistic C++ program that performs a circular shift to the left or the right on a given 3x3 matrix. It doesn't take an arbitrary size matrix or an arbitrary dimension, but it should give you an idea of how to start implementing a more general function that could accommodate those.

```cpp
#include <iostream>
#include <vector>

using namespace std;

// Function to display the matrix
void print(vector<vector<int>>& matrix) {
    for (auto& row : matrix) {
        for (int& i : row) {
            cout << i << ' ';
        }
        cout << '\n';
    }
}

// Function to shift matrix
void shift(vector<vector<int>>& matrix, int direction, int rotations, int dim) {
    int n = matrix.size();
    int m = matrix[0].size();
    rotations %= (dim == 1 ? n : m);
    if (direction == 1) rotations = (dim == 1 ? n : m) - rotations;
    if (dim == 1) {
        while(rotations--) {
            rotate(matrix.begin(), matrix.begin()+1, matrix.end());
        }
    } 
    else {
        while(rotations--) {
            for(auto &row : matrix)
                rotate(row.begin(), row.begin()+1, row.end());
        }
    }
}

int main() {
    vector<vector<int>> matrix = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    cout << "Original matrix:\n";
    print(matrix); 
    // take input from the user
    int direction, rotations, dim;
    cout << "Enter direction (0 for left, 1 for right): ";
    cin >> direction;
    cout << "Enter number of positions to shift: ";
    cin >> rotations;
    cout << "Enter dimension to shift (1 or 2): ";
    cin >> dim;

    // perform shifting
    shift(matrix, direction, rotations, dim); 

    cout << "Shifted matrix:\n";
    print(matrix);  
    return 0;
}
```

This implementation uses the STL rotate algorithm to do the shifting. The rotate function changes the position of elements within the range [first, last) so that the element pointed by middle becomes the new first element. When shifting by the first dimension (rows), it swaps entire rows. When shifting by the second dimension (columns), it performs the rotation on a column-by-column basis.

