Certainly, here is a sample C++ program that uses a binary search algorithm and handles exceptions to find the nth root of a given positive number.

Please note for simplicity and usability, this code could only handle positive numbers and the root must be bigger than zero.

```cpp
#include<iostream>
#include<cmath>
#include<stdexcept>
using namespace std;

double nthRoot(double number, int root, double precision = 0.00001) {
    if(number < 0) {
        throw invalid_argument("Negative number cannot have a real root.");
    }
    if(root <= 0) {
        throw invalid_argument("Root must be a positive integer.");
    }

    double low, high;
    if(number >= 1) {
        low = 1;
        high = number;
    } else {
        low = number;
        high = 1;
    }

    double guess = (low + high) / 2;
    while(abs(pow(guess, root) - number) >= precision) {
        if(pow(guess, root) > number) {
            high = guess;
        } else {
            low = guess;
        }
        guess = (low + high) / 2;
    }

    return guess;
}

int main() {
    double number = 3.14;
    int root = 2;

    try {
        double result = nthRoot(number, root);
        cout << "The " << root << "th root of " << number << " is " << result << endl;
    } catch(invalid_argument &e) {
        cerr << "Caught Exception: " << e.what() << endl;
    } catch(...) {
        cerr << "Caught unknown exception." << endl;
    }

    return 0;
}
```

