    // MergeSort algorithm for sorting
    Node<T>* SortedMerge(Node<T>* a, Node<T>* b) {
        Node<T>* result = NULL;

        // Base cases
        if (a == NULL)
            return (b);
        else if (b == NULL)
            return (a);

        if (a->data <= b->data) {
            result = a;
            result->next = SortedMerge(a->next, b);
            if(result->next){
                result->next->prev = result;
            }
        } else {
            result = b;
            result->next = SortedMerge(a, b->next);
            if(result->next) {
                result->next->prev = result;
            }
        }
        return result;
    }

    void FrontBackSplit(Node<T>* source, Node<T>** frontRef, Node<T>** backRef) {
        Node<T>* fast;
        Node<T>* slow;
        if (source == NULL || source->next == NULL) {
            *frontRef = source;
            *backRef = NULL;
        } else {
            slow = source;
            fast = source->next;
            while (fast != NULL) {
                fast = fast->next;
                if (fast != NULL) {
                    slow = slow->next;
                    fast = fast->next;
                }
            }
            *frontRef = source;
            *backRef = slow->next;
            slow->next = NULL;
            (*backRef)->prev = NULL;
        }
    }

    void MergeSort(Node<T> **headRef) {
        Node<T>* head = *headRef;
        Node<T>* a;
        Node<T>* b;

        if ((head == NULL) || (head->next == NULL)) {
            return;
        }

        FrontBackSplit(head, &a, &b);

        MergeSort(&a);
        MergeSort(&b);
        *headRef = SortedMerge(a, b);
    }

