The logic of solution is based on the Fundamental Theorem of Arithmetic, which states that every integer greater than 1 either is a prime number itself or can be written as a product of prime numbers, and this factorization is unique, up to the order of the factors. We have to be sure that 'a' number can be factorized by exactly 3 primes numbers.

Assuming the language being used is C++, here's the solution:

```cpp
#include<iostream>
#include<vector>

using namespace std;

vector<int> getPrimefactors(int n) {
    vector<int> primefactors;
    // Print the number of 2s that divide n
    while (n % 2 == 0) {
        primefactors.push_back(2);
        n = n / 2;
    }

    // n must be odd at this point, thus skip of 2 (i = i + 2) can be used
    for (int i = 3; i * i <= n; i = i + 2) {
        // while i divides n, print i and divide n
        while (n % i == 0) {
            primefactors.push_back(i);
            n = n / i;
        }
    }

    // This condition is to handle the case when n is a prime number
    // greater than 2
    if (n > 2)
        primefactors.push_back(n);

    return primefactors;
}

bool is_multiply_prime(int a){
    vector<int> primefactors = getPrimefactors(a);
    if (primefactors.size() == 3){
        return true;
    }
    return false;
}

int main(){
    int n = 30;
    if(is_multiply_prime(n))
        cout<< n << " is a product of 3 primes" <<endl;
    else
        cout<< n << " is not a product of 3 primes" <<endl;
    return 0;
}
```

Here, the function `getPrimefactors` generates all prime factors of the input number `a`, by dividing it by 2 and then by all odd integers starting from 3.

The complexity here is O(sqrt(n)), where n is the input number. This is because in the worst case, we're checking till sqrt(n) to find all prime factors.

