struct TLVElement {
    uint8_t type;
    size_t length;
    const uint8_t* value;
};

class Decoder {
private:
    const uint8_t* data;
    size_t size;
    size_t position;

public:
    Decoder(const uint8_t* data, size_t size) : data(data), size(size), position(0) {}

    const uint8_t* begin() const {
        return data;
    }

    const uint8_t* end() const {
        return data + size;
    }

    TLVElement next() {
        assert(position < size);

        uint8_t type = data[position++];
        size_t length = data[position++];
        const uint8_t* value = &data[position];
        position += length;

        return {type, length, value};
    }
};

int main() {
    // Example usage
    std::vector<uint8_t> wire1({0x01, 0x04, 0x61, 0x62, 0x63, 0x64});  // TLV-encoded data: Type=0x01, Length=4, Value=0x61 0x62 0x63 0x64
    Decoder decoder1(wire1.data(), wire1.size());

    TLVElement element = decoder1.next();
    std::cout << "Type: " << std::hex << static_cast<int>(element.type) << std::endl;
    std::cout << "Length: " << element.length << std::endl;
    std::cout << "Value: ";
    for (size_t i = 0; i < element.length; ++i) {
        std::cout << std::hex << static_cast<int>(element.value[i]) << " ";
    }
    std::cout << std::endl;

    return 0;
}
