#include <iostream>
#include <cstdlib>

int main(int argc, char* argv[]) {
    int day, month, year;

    if (argc > 1) {
        day = std::atoi(argv[1]);
    } else { 
        std::cout << "Enter day: ";
        std::cin >> day;
    }

    std::cout << "Enter month: ";
    std::cin >> month;

    std::cout << "Enter year: ";
    std::cin >> year;

