```c++
#include <string>
#include <iostream>
#include "exprtk.hpp" // include exprtk library previously downloaded

double calculateExpression(const std::string& expression_str) {
    typedef exprtk::symbol_table<double> symbol_table_t;
    typedef exprtk::expression<double>     expression_t;
    typedef exprtk::parser<double>             parser_t;

    double result = 0.0;

    symbol_table_t symbol_table;
    symbol_table.add_variable("x", result);
    symbol_table.add_constants();

    expression_t expression;
    expression.register_symbol_table(symbol_table);

    parser_t parser;

    if (!parser.compile(expression_str, expression)) {
        std::cout << "Compilation error in expression: " << parser.error() << std::endl;
        return 0.0;
    }

    double y = expression.value();

    return y;
}

int main() {
