Here is a simple implementation of Circular Queue in C++.

```c++
#include<iostream>
using namespace std;

#define MAX_SIZE 10

class CircularQueue{
   private:
   int front, rear;
   int arr[MAX_SIZE];

   public:
   CircularQueue(){
      front = -1;
      rear = -1;
   }

   //check if queue is full
   bool isFull(){
      if((rear+1)%MAX_SIZE == front){
         return true;
      }
      return false;
   }

   //check if queue is empty
   bool isEmpty(){
      if(front == -1)return true;
      return false;
   }

   //for adding elements to queue
   void enqueue(int data){
      if(isFull()){
         cout << "Queue is full.\n";
         return;
      }else if (isEmpty()){
         front = rear = 0;
      }else{
         rear = (rear+1)%MAX_SIZE;
      }
      arr[rear] = data;
      cout << "Inserted " << data << " in queue.\n";
   }

   //for deleting elements from queue
   int dequeue(){
      int data = -1;
      if(isEmpty()){
         cout << "Queue is empty.\n";
      }else if(front == rear){
         data = arr[front];
         front = rear = -1;   
      }else{
         data = arr[front];
         front = (front+1)%MAX_SIZE;
      }
      return data;
   }

   //returns the first/front element of Circular Queue
   int getFront(){
      if(isEmpty()){
         cout << "Queue is empty.\n";
         return -1;
      }
      return arr[front];
   }

   //returns the last/rear element of Circular Queue
   int getRear(){
      if(isEmpty()){
         cout << "Queue is empty.\n";
         return -1;
      }
      return arr[rear];
   }
};


int main(){
   CircularQueue q;
   q.enqueue(1);
   q.enqueue(2);
   q.enqueue(3);
   q.enqueue(4);
   q.enqueue(5);
   cout << "Front: " << q.getFront()<< endl;
   cout << "Rear: " << q.getRear()<< endl;
   q.dequeue();
   q.dequeue();
   cout << "Front: " << q.getFront()<< endl;
   return 0;
}
```

In this code, `enqueue` method is used for adding items to the queue, which checks if queue is full before insertion. `dequeue` method is used for removing items from queue, it also checks if queue is empty before deletion. `getFront` method returns front element of queue and `getRear` method returns rear element of queue. We check if queue is full using `isFull` method, which checks if next increment of rear would point it to front, indicating queue is full.

