Sure, the provided JavaScript code is implementation of the Fibonacci sequence where each number in the sequence is the sum of the previous 5 numbers (not typical Fibonacci sequence which is the sum of previous two). Here's the equivalent C++ code:

```c++
#include <iostream>
#include <cmath> // For abs() function
#include <vector> // For vector data structure

int fib5(int n) { // function to get nth term in sequence
    // Use std::abs to handle negative numbers
    n = std::abs(n);

    if (n == 0) return 0; // if n is zero return 0

    // Create a vector to store the computed sequence values
    std::vector<int> values = {0, 0, 2, 0, 1, 1}; // initial vector with base cases

    // If n is more than 5, calculate sequence up to n
    if(n > 5) {
      // If n is more than length of values vector, resize the vector
      if(n > values.size()) {
        values.resize(n + 1); 
      }

      for (int i = 5; i <= n; i++) {
          // Compute the current number as the sum of the previous 5 numbers
          values[i] = values[i-1] + values[i-2] + values[i-3] + values[i-4] + values[i-5];
      }
    }

    // Return the nth number in the sequence
    return values[n];
}

