```cpp
#include <iostream>
#include <unordered_map>
#include <vector>

class MemoryManager {
private:
    std::vector<bool> memorySpace;  // Represents the memory space, true for allocated, false for free
    std::unordered_map<int, int> allocationMap;  // Maps unique identifiers to memory block sizes

public:
    MemoryManager(int totalMemorySize) : memorySpace(totalMemorySize, false) {}

    int allocate(int size) {
        for (int i = 0; i <= memorySpace.size() - size; ++i) {
            if (!memorySpace[i]) {
                bool canAllocate = true;
                for (int j = i + 1; j < i + size; ++j) {
                    if (memorySpace[j]) {
                        canAllocate = false;
                        i = j;  // Skip to the next free block
                        break;
                    }
                }
                if (canAllocate) {
                    for (int j = i; j < i + size; ++j) {
                        memorySpace[j] = true;
                    }
                    static int id = 0;
                    allocationMap[id] = size;
                    return id++;
                }
            }
        }
        return -1;  // Allocation failed
    }

    void deallocate(int id) {
        if (allocationMap.find(id) != allocationMap.end()) {
            int start = 0;
            for (auto &entry : allocationMap) {
                if (entry.first == id) {
                    break;
                }
                start += entry.second;
            }
            for (int i = start; i < start + allocationMap[id]; ++i) {
                memorySpace[i] = false;
            }
            allocationMap.erase(id);
        }
    }

    void defragment() {
        int freeIndex = 0;
        for (int i = 0; i < memorySpace.size(); ++i) {
            if (!memorySpace[i]) {
                std::swap(memorySpace[i], memorySpace[freeIndex]);
                ++freeIndex;
            }
        }
    }
};

int main() {
    MemoryManager manager(20);  // Initialize memory manager with 20 units of memory
    int id1 = manager.allocate(5);  // Allocate 5 units of memory
    int id2 = manager.allocate(7);  // Allocate 7 units of memory
    manager.deallocate(id1);  // Deallocate the first allocation
    manager.defragment();  // Defragment the memory space
    int id3 = manager.allocate(4);  // Allocate 4 units of memory after defragmentation
    return 0;
}
```

In this solution, the `MemoryManager` class maintains a vector `memorySpace` to represent the memory space, where each element indicates whether the corresponding memory unit is allocated or free. The `allocationMap` is used to map unique identifiers to the sizes of allocated memory blocks.

The `allocate` method searches for a contiguous block of free memory to allocate and returns a unique identifier if successful. The `deallocate` method frees the memory block identified by the given unique identifier. The `defragment` method rearranges the memory space to move all allocated memory blocks to one end, freeing up the remaining space for future allocations.

