template <typename T>
class FenwickTree {
private:
    std::vector<T> d;
    int n;

public:
    FenwickTree(int size) : n(size), d(size + 1, 0) {}

    void add(int i, T x = 1) {
        for (i++; i <= n; i += i & -i) {
            d[i] += x;
        }
    }

    T sum(int i) {
        T x = 0;
        for (i++; i; i -= i & -i) {
            x += d[i];
        }
        return x;
    }
};

