#include<stdio.h>

bool is_prime(long long n){
    if(n<=1) return false; // 1 is not a prime
    if(n==2) return true;  // 2 itself is a prime
    if(n%2==0) return false; // Check if n is a multiple of 2
    for(long long i=3; i*i<=n; i+=2) { // Start from 3, check up to sqrt(n), increment by 2
        if(n%i==0)
            return false; // If n is divisible by some other number, it's not a prime
    }
    return true;
}

int main() {
    long long number;
    printf("Enter a number: ");
    scanf("%lld", &number);
    if (is_prime(number))
        printf("%lld is a prime number.", number);
    else
        printf("%lld is not a prime number.", number);
    return 0;
}
```

This function works by first checking if the input number is less than or equal to one, in which case we return 'false', as these are not prime numbers. It then checks if the number is two, in which case we return 'true', as two is a prime number. 

If these special cases do not apply, the function then checks whether the number is divisible by two (i.e., if it is an even number), in which case we return 'false', as even numbers are not prime (with the exception of two, which we already checked).

