// A Function to test whether a number is prime or not
bool is_prime(int n) {
    // Check if the number is 2 or 3. These are the only two prime numbers that
    // are also even. True is returned in these cases.
    if (n == 2 || n == 3) {
        return true;
    }

    // Check if the number is 1 or an even number other than 2. These numbers
    // are automatically not prime (1 is not prime by definition, and even
    // numbers greater than 2 are always divisible by 2). False is returned in
    // these cases.
    if (n == 1 || n % 2 == 0) {
