    // then it is prime. If it is divisible, then it is not prime. We only need
    // to go up to the square root because a larger factor of the number would
    // be a multiple of smaller factor that has already been checked.
    for (int i = 3; i <= sqrt(n); i += 2) {
        if (n % i == 0) {
            return false;
        }
    }

    // If we've gone through all possible factors up to the square root and found no factors,
    // then the number is prime.
    return true;
}

