#include <string>

// using keyword long long for wider range
long long accumulateProductOddDigitNumbers(std::vector<long long> num, int p) {
  long long product = 1;
  for(int i = 0; i < p; i++) {
    // to_string is used to convert num[i] to a string
    std::string str = std::to_string(num[i]);

    // size() is used to get the length of the string
    // % is the modulus operation. str.size() % 2 is equal to the remainder of the division str.size() / 2
    // If the remainder is not 0, that means the number of digits in the number is odd
    if(str.size() % 2 != 0) {
      // product *= num[i] means multiply the current product by num[i] and store the result in product
      product *= num[i];
    }
  }
  // return the result
  return product;
}
