```cpp
#include <iostream>
#include <vector>
using namespace std;

typedef long long ll;

class SegmentTree {
private:
    ll l, r, dtr;
    SegmentTree *lc, *rc;

public:
    SegmentTree(ll left, ll right, vector<ll>& arr) {
        l = left;
        r = right;
        if (l == r - 1) {
            dtr = arr[l];
        } else {
            ll m = (l + r) / 2;
            lc = new SegmentTree(l, m, arr);
            rc = new SegmentTree(m, r, arr);
            dtr = min(lc->dtr, rc->dtr);
        }
    }

