Below is a C++ program that generates all subsets of size `k` from a given set of `n` elements. The code uses concept of backtracking to form subsets of k from a given set of n elements.

```cpp
#include <iostream>
#include <vector>

using namespace std;

void generateSubsets(vector<int>& set, int k, int startIndex, vector<int>& current, vector<vector<int>>& result) {
    if (current.size() == k) {
        result.push_back(current);
        return;
    }

    for (int i = startIndex; i < set.size(); i++) {
        current.push_back(set[i]);  
        generateSubsets(set, k, i + 1, current, result); 
        current.pop_back();  
    }
}

int main() {
    vector<int> set = {1, 2, 3, 4};
    int k = 2;
    vector<vector<int>> result;
    vector<int> current;

    generateSubsets(set, k, 0, current, result);

    for (int i = 0; i < result.size(); i++) {
        for (int j = 0; j < result[i].size(); j++)
            cout << result[i][j] << ' ';
        cout << endl;
    }

    return 0;
}
```

This program generates all the subsets of a set of size `k`. First, it checks if the current subset is of size `k`, if it is then it adds the subset into the `result`. Then, it starts from the `startIndex` and checks each element, adds that element into the `current subset`, and makes a recursive call to generate all possible subsets using this element. After the recursion, it removes the added element from the `current subset` to generate subsets without this element.

