class CustomQueue {
private:
    queue<int> q;
    const unsigned int maxSize;

public:
    CustomQueue(unsigned int size) : maxSize(size) {}

    // enqueue operation
    void enqueue(int x) {
        if(q.size() == maxSize) {
            cout << "Error: Queue overflow. No room to add more elements.\n";
            return;
        }
        q.push(x);
    }

