        if(q.empty()) {
            cout << "Error: Queue underflow. No elements to remove.\n";
            return;
        }
        q.pop();
    }

    // wipeout operation
    void wipeout() {
        while(!q.empty()) {
            q.pop();
        }
    }
};

void wipeout(queue<int> &q) {
    while(!q.empty()) {
        q.pop();
    }
}

