int unique_sum_mult(std::vector<int> arr) {
    // Check if array is empty
    if(arr.empty()) {
        return 0;
    }

    // Store unique positive and negative numbers
    std::unordered_set<int> pos, neg;
    for(auto x: arr) {
        if(x > 0) {
            pos.insert(x);
        } else if(x < 0) {
            neg.insert(x);
        }
    }

    // Compute sum of unique numbers
    int total_sum = 0;
    for(auto x: pos) {
        total_sum += x;
    }
    for(auto x: neg) {
        total_sum += x;
    }

    // Compute product of counts of unique positive and negative integers
    int total_mult = pos.size() * ((neg.empty()) ? 1 : neg.size());

    // Return the result
    return total_sum * total_mult;
}
