```cpp
#include <vector>
#include <algorithm>

using namespace std;

bool compare(pair<int, int> a, pair<int, int> b) {
    return a.first < b.first;
}

vector<int> efficientSort(vector<int> arr) {
    int n = arr.size();
    pair<int, int> pairt[n];

    for (int i = 0; i < n; i++) {
        pairt[i].first = arr[i];
        pairt[i].second = i;
    }

    sort(pairt, pairt+n, compare);

    vector<int> sorted_arr(n), idx(n);

    for (int i = 0; i < n; i++) {
        sorted_arr[i] = pairt[i].first;
        idx[i] = pairt[i].second;
    }

    return sorted_arr, idx;
}
```

This function sorts the array and returns a pair of sorted array and original indices in sorted array. It utilizes pair data structure to keep track of the original indices and then sorts the pairs based on the value. After sorting, it separates the values and their indices into two separate lists.

