public class MaxSumOfSquares {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the value of Nt: ");
        int Nt = scanner.nextInt();

        int[] results = new int[Nt];
        for (int nt = 0; nt < Nt; nt++) {
            results[nt] = sumOfSquares(nt + 1);
        }

        int max = results[0];
        for (int i = 1; i < Nt; i++) {
            if (results[i] > max) {
                max = results[i];
            }
        }

        System.out.println("Maximum value obtained: " + max);
    }

    public static int sumOfSquares(int n) {
        int sum = 0;
        for (int i = 1; i <= n; i++) {
            sum += i * i;
        }
        return sum;
    }
}
