To implement the `pop()` operation for the priority queue, we can use the following approach:

1. Swap the root node (element with the highest priority) with the last node in the heap.
2. Remove the last node from the heap.
3. Restore the heap property by "sinking down" the new root node to its correct position in the heap.

Here's a sample implementation in Python:

```python
class PriorityQueue:
    def __init__(self):
        self.heap = []

    def push(self, val):
        self.heap.append(val)
        self._sift_up(len(self.heap) - 1)

    def pop(self):
        if len(self.heap) == 0:
            raise IndexError("pop from an empty priority queue")
        if len(self.heap) == 1:
            return self.heap.pop()
        root = self.heap[0]
        self.heap[0] = self.heap.pop()
        self._sift_down(0)
        return root

    def top(self):
        if len(self.heap) == 0:
            raise IndexError("top from an empty priority queue")
        return self.heap[0]

    def empty(self):
        return len(self.heap) == 0

    def _sift_up(self, index):
        while index > 0:
            parent_index = (index - 1) // 2
            if self.heap[parent_index] < self.heap[index]:
                self.heap[parent_index], self.heap[index] = self.heap[index], self.heap[parent_index]
                index = parent_index
            else:
                break

    def _sift_down(self, index):
        while index * 2 + 1 < len(self.heap):
            left_child_index = index * 2 + 1
            right_child_index = index * 2 + 2 if index * 2 + 2 < len(self.heap) else left_child_index
            max_child_index = left_child_index if self.heap[left_child_index] > self.heap[right_child_index] else right_child_index
            if self.heap[index] < self.heap[max_child_index]:
                self.heap[index], self.heap[max_child_index] = self.heap[max_child_index], self.heap[index]
                index = max_child_index
            else:
                break
```

This implementation of the `pop()` operation maintains the max-heap property and correctly removes and returns the element with the highest priority from the priority queue.

