#include<iostream>
using namespace std;

void rotate(int a[], int n, int k) {
   int temp[k];

   // copy first k elements of array to a temp[] array
   for(int i=0; i<k; i++){
       temp[i] = a[i];
   }

   // shift the rest of the array elements to the left
   for(int i=0; i<n-k; i++){
       a[i] = a[i+k];
   }

   // copy back the temp[] array elements to the original array
   for(int i=0; i<k; i++){
       a[n-k+i] = temp[i];
   }
}

void printArray(int a[], int n) {
    for(int i=0; i<n; i++){
        cout<< a[i] <<" ";
    }
    cout<< "\n";
}

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    int n = sizeof(arr)/sizeof(arr[0]);

    // number of positions to shift
    int k = 2;

    cout<< "Original Array:" <<"\n";
    printArray(arr, n);

    rotate(arr, n, k);

    cout<< "\nShifted Array by "<< k <<" position(s):\n";
    printArray(arr, n);

    return 0;
}
