using namespace std;

bool is_balanced(vector<int> v) {
  vector<int> reversed_v = v;
  reverse(reversed_v.begin(), reversed_v.end());
  return v == reversed_v;
}

int get_total_weight(vector<int> v) {
  int total = 0;
  for (int i = 0; i < v.size(); i++) {
    total += v[i];
  }
  return total;
}

float will_it_fly(vector<int> obj, int capacity, float gravity, pair<string, int> wind){
  float probability = 0.0;
  if (!is_balanced(obj)) {
    probability -= 0.1;
  }
  int total_weight = get_total_weight(obj);
  if (total_weight > capacity) {
    probability -= float(total_weight - capacity) / 10;
  }

  string wind_direction = wind.first;
  int wind_speed = wind.second;

  if (wind_direction == "North" || wind_direction == "South") {
    probability -= float(wind_speed) / 10;
  }
  else if (wind_direction == "East" || wind_direction == "West") {
    probability += float(wind_speed) / 10;
  }

  return max(float(0), probability / gravity);
}
```
In the function `will_it_fly`, I start by assuming the object will not fly (`probability = 0.0`). Then I check if the object is balanced. If not, I decrease the probability by 0.1 as a penalty. Then if the object is too heavy, I decrease the probability by `(total_weight - capacity) / 10`.

Next, depending on wind direction, I either increase or decrease the probability by `wind_speed / 10`.

Finally, I return the probability adjusted for gravity. If the result is negative, I return zero (since the probability of an event cannot be less than zero).

