    bio = BIO_new(BIO_s_mem());
    bio = BIO_push(b64, bio);
    BIO_write(bio, res.c_str(), res.length());
    BIO_flush(bio);
    BIO_get_mem_ptr(bio, &bufferPtr);
    BIO_set_close(bio, BIO_CLOSE);
    BIO_free_all(bio);
    return std::string((*bufferPtr).data, (*bufferPtr).length);
