// This function updates a record in a PostgreSQL table.
// table_name: The name of the table
// condition: SQL WHERE clause defining which row(s) to update
// new_data: SQL SET clause containing the new data for the row(s)
int update_record(const std::string &table_name, const std::string &condition, const std::string &new_data)
{
    // Create a connection to the PostgreSQL server
    pqxx::connection con("dbname=mydatabase user=user password=pass host=localhost port=5432");

    // Change to non-transactional mode to automatically commit changes.
    con.set_autocommit(true);

    // Begin a transaction on the connection
    pqxx::nontransaction tx(con);

    // Create a SQL update statement
    std::string stmt = "UPDATE " + table_name + " SET " + new_data + " WHERE " + condition;

    // Execute the update statement
    pqxx::result r = tx.exec(stmt);

    // Commit the transaction and close the connection
    tx.commit();

    // Return the number of updated rows
	return r.affected_rows();
}

