```cpp
#include<iostream>
#include<vector>

// Function to perform the pivot partitioning process of QuickSort
int partition(std::vector<int>& input, int low, int high){
    int pivot = input[high]; // use last element as pivot
    int i = (low - 1);  // index of smaller element
    for (int j = low; j <= high - 1; j++){
        // if current element is smaller than the pivot
        if (input[j] < pivot){
            i++; // increment index of smaller element
            std::swap(input[i], input[j]);
        }
    }
    std::swap(input[i + 1], input[high]);
    return (i + 1);
}

// Function to perform QuickSort on the array/vector
void quicksort(std::vector<int>& input, int low, int high){
    if (low < high){
        // Here pi is partitioning index, input[p] is now at right place
        int pi = partition(input, low, high);
        // recursively performs QuickSort on the two partitions
        quicksort(input, low, pi - 1); // Before pi
        quicksort(input, pi + 1, high); // After pi
    }
}

// Main function to test above
int main(){
    std::vector<int> data = {10, 7, 8, 9, 1, 5};
    quicksort(data, 0, data.size()-1);
    std::cout << "Sorted array: \n";
    for(int i = 0; i < data.size(); i++){
        std::cout << data[i] << " ";
    }
    return 0;
}
```

