To solve this problem, we can create a C++ function that takes a string as an input, then checks whether each character in the string is not only a digit but a unique digit.

We'll use two techniques to accomplish this:

1. Checking a char is digit or not: 
    Using ASCII values, the ASCII value of digit 0 is 48, and for digit 9 is 57, so if ASCII value a character falls in between 48 and 57, it is a digit.

2. Checking uniqueness of digits: 
    For making sure the digits are non-repeating, we'll keep a boolean array of size 10 (as there are 10 possible digits 0 - 9). As we encounter a digit, we'll mark the corresponding index, if at any time we find the index already marked, we know that digit is repeating, hence we can stop there.

Here's the C++ function implementing this approach:

```cpp
#include<iostream>
#include<cstring>
using namespace std;

bool isValid(string str) {
    if (str.length() > 10)  // max possible unique digits is 10 (0-9)
        return false;

    bool digits[10];  // to mark the encountered digits
    memset(digits, false, sizeof(digits));

    for (int i = 0; i < str.length(); i++) {
        // if character is not a digit return false
        if (str[i] < 48 || str[i] > 57)
            return false;

        // if digit is not unique return false
        if (digits[str[i] - '0'] == true)
            return false;

        // mark the digit as encountered
        digits[str[i] - '0'] = true;
    }
    // if all characters are unique digits
    return true;
}

int main() {
    string str;
    cout << "Enter a string: ";
    cin >> str;

    if(isValid(str))
        cout << "String contains unique digits only." << endl;
    else
        cout << "String does not contain unique digits or contains non-digit characters." << endl; 

    return 0;
}
```

