#include <stdio.h>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<string> sorted_list_sum(vector<string> lst, string delimiter) {
    //eliminate the string containing the delimiter or has odd length
    lst.erase(remove_if(lst.begin(), lst.end(), [&](const string &s) {
