```cpp
#include<iostream>

int fibonacci(int n) {
    if(n <= 0) {
        return 0;
    } else if(n == 1) {
        return 1;
    }
    int first = 0;
    int second = 1;
    int res;
    for(int i = 2; i <= n; i++) {
        res = first + second;
        first = second;
        second = res;
    }
    return second;
}

int main() {
    int n;
    std::cout<<"Enter n: ";
    std::cin>>n;
    std::cout<<"Fibonacci number is: "<<fibonacci(n)<<"\n";
