    def inorder_traversal(node, result):
        if node:
            inorder_traversal(node.left, result)
            result.append(node.val)
            inorder_traversal(node.right, result)

    values = []
    inorder_traversal(root, values)
    min_diff = float('inf')
    for i in range(1, len(values)):
