```cpp
#include <deque>
#include <mutex>

template <typename T>
class ThreadSafeWorkQueue {
private:
    std::deque<T*> _works;
    std::mutex _work_lock;

public:
    void add(T* item) {
        _work_lock.lock();
        _works.push_back(item);
        _work_lock.unlock();
    }

    T* get() {
        _work_lock.lock();
        T* item = _works.front();
        _works.pop_front();
        _work_lock.unlock();
        return item;
    }

    void rest(T* t) {
        _work_lock.lock();
        for (typename std::deque<T*>::iterator iter = _works.begin(); iter != _works.end(); iter++) {
            if (*iter == t) {
                _works.erase(iter);
                break;
            }
        }
        _work_lock.unlock();
    }

    size_t available() const {
        _work_lock.lock();
        size_t count = _works.size();
        _work_lock.unlock();
        return count;
    }
};
```

