Below is a simple implementation in C++. This code uses the Standard Template Libraries (STL) to simplify the process of sorting and managing the array. Further, for multithreading it uses the standard library's thread functionality, splitting the collection in half and sorting each half in a distinct thread.

Please note that the multithreaded algorithm used here is not the most efficient one for every scenario, but it demonstrates the principle and will perform faster for large collections on a multicore computer.

```cpp
#include <vector>
#include <algorithm>
#include <thread>
#include <mutex>
#include <iterator>

class NumberCollection {
    private:
        std::vector<int> numbers;
        std::mutex mtx;

    public:
        NumberCollection(std::initializer_list<int> init) : numbers(init) { }

        void add_number(int num) {
            std::lock_guard<std::mutex> lock(mtx);
            numbers.push_back(num);
        }

        void remove_number(int num) {
            std::lock_guard<std::mutex> lock(mtx);
            numbers.erase(std::remove(numbers.begin(), numbers.end(), num), numbers.end());
        }

        std::vector<int> return_sorted() {
            std::lock_guard<std::mutex> lock(mtx);
            std::vector<int> sorted(numbers);
            std::sort(sorted.begin(), sorted.end());
            return sorted;
        }

        void sort_multithreaded() {
            std::lock_guard<std::mutex> lock(mtx);

            auto middle = numbers.begin() + numbers.size() / 2;

            std::thread t1([&](std::vector<int>::iterator begin, std::vector<int>::iterator end) {
                std::sort(begin, end);
            }, numbers.begin(), middle);

            std::thread t2([&](std::vector<int>::iterator begin, std::vector<int>::iterator end) {
                std::sort(begin, end);
            }, middle, numbers.end());

            t1.join(); 
            t2.join();

            std::inplace_merge(numbers.begin(), middle, numbers.end());
        }
};

int main() {
    NumberCollection collection{4, -9, 0, 2, -6, -1, 3};

    collection.add_number(5);
    collection.remove_number(4);

    auto sorted = collection.return_sorted();

    collection.sort_multithreaded();

    return 0;
}
```
Remember to compile the program with C++11 or higher as the std::thread library was introduced in C++11. The sort_multithreaded method using two threads sorts the array in two halves and then merges the two halves in proper order. When using this in real-life applications, you would need to check if the overhead of creating threads outweighs the speedup gained from sorting different portions of the array in parallel.

