// Define the type for entity ID
using IdT = int;

// Define the EntityStorage class
class EntityStorage {
public:
    virtual void erase_equal_range(IdT entity) = 0;
    virtual void flush_erase_queue() = 0;
};

// Derived class implementing the EntityStorage
class MyEntityStorage : public EntityStorage {
private:
    std::unordered_map<IdT, bool> entityMap;  // Map to store entities and their deletion status
    std::queue<IdT> eraseQueue;  // Queue to store entities marked for deletion

public:
    // Implement the erase_equal_range method
    void erase_equal_range(IdT entity) override {
        entityMap[entity] = true;  // Mark the entity for deletion
        eraseQueue.push(entity);  // Add the entity to the erase queue
    }

    // Implement the flush_erase_queue method
    void flush_erase_queue() override {
        while (!eraseQueue.empty()) {
            IdT entity = eraseQueue.front();
            eraseQueue.pop();
            if (entityMap[entity]) {
                entityMap.erase(entity);  // Erase the entity from the map
            }
        }
    }
};

int main() {
    // Create an instance of MyEntityStorage
    MyEntityStorage storage;

    // Add entities and mark some for deletion
    storage.erase_equal_range(1);
    storage.erase_equal_range(2);
    storage.erase_equal_range(3);

    // Flush the erase queue to delete marked entities
    storage.flush_erase_queue();

    return 0;
}
```

