#include <vector>
#include <cmath>

bool is_prime(int num) {
    // Check if a number is prime.
    if (num < 2) {
        return false;
    } else {
        for (int i = 2; i <= sqrt(num); ++i) {
            if (num % i == 0){
                return false;
            }
        }
    }
    return true;
