using namespace std;

bool IsPalindrome(string str) {
    int len = str.length();
    for (int i = 0; i < len / 2; i++) {
        if (str[i] != str[len - 1 - i])
            return false;
    }
    return true;
}

string LongestPalindromicSubstring(string str) {
    int len = str.length();
    string longest;
    for (int i = 0; i < len; i++) {
        for (int j = i; j < len; j++) {
            string subStr = str.substr(i, j - i + 1);
            if (IsPalindrome(subStr) && subStr.length() > longest.length()) {
                longest = subStr;
            }
        }
    }
    return longest;
}

int main() {
    vector<string> fruits = {"apple", "banana", "mango", "strawberry"};

    string longestPalindrome;
    for (string fruit : fruits) {
        string currentLongestPalindrome = LongestPalindromicSubstring(fruit);
        if (currentLongestPalindrome.length() > longestPalindrome.length())
            longestPalindrome = currentLongestPalindrome;
    }

    cout << "Longest Palindromic Substring: " << longestPalindrome << endl;

    return 0;
}
```
