Function Signature:
```cpp
void unique(std::vector<int>& v);
```

Example:
```cpp
std::vector<int> v1 = {5, 7, 7, 7, 3};
unique(v1);
// v1 is now {5, 7, 3}

std::vector<int> v2 = {1, 2, 1};
unique(v2);
// v2 remains unchanged as {1, 2, 1}
```

a:
```cpp
void unique(std::vector<int>& v) {
    if (v.size() < 2) {
        return;  // No consecutive duplicates possible
    }

    auto it = v.begin();
    while (it != v.end() - 1) {
        if (*it == *(it + 1)) {
            it = v.erase(it);  // Remove consecutive duplicate
        } else {
            ++it;
        }
    }
}
```

