Below is a basic implementation in C++ language. It uses three classes Point, Tetrahedron and RegularTetrahedron. RegularTetrahedron is derived from Tetrahedron class. Tetrahedron class contains all the logic to calculate the surface area and volume whereas RegularTetrahedron class is used to check if given points form a regular Tetrahedron or not.

This is a console-based C++ program:

```cpp
#include<iostream>
#include<cmath>

class Point {
public:
    double x, y, z;

    Point(double x, double y, double z) {
        this->x = x;
        this->y = y;
        this->z = z;
    }

    double distance(Point another) {
        return sqrt(pow(another.x - x, 2) + pow(another.y - y, 2) + pow(another.z - z, 2));
    }
};

class Tetrahedron {
protected:
    Point *p1, *p2, *p3, *p4;
public:
    Tetrahedron(Point *p1, Point *p2, Point *p3, Point *p4){
        this->p1 = p1;
        this->p2 = p2;
        this->p3 = p3;
        this->p4 = p4;
    };
    double volume(){
        double a = p1->distance(*p2);
        double b = p1->distance(*p3);
        double c = p2->distance(*p3);
        double d = p1->distance(*p4);
        double e = p2->distance(*p4);
        double f = p3->distance(*p4);

        return sqrt(4*a*a*b*b*c*c - a*a*pow(b*b+c*c-d*d, 2) - b*b*pow(a*a+c*c-e*e, 2) - c*c*pow(a*a+b*b-f*f, 2)) / 12;
    };
    double surfaceArea(){
        double a = p1->distance(*p2);
        double b = p1->distance(*p3);
        double c = p2->distance(*p3);
        double d = p1->distance(*p4);
        double e = p2->distance(*p4);
        double f = p3->distance(*p4);

        return sqrt((b*b+f*f-d*d)*(c*c+e*e-a*a) + (a*a+d*d-e*e)*(c*c+f*f-b*b) + (a*a+e*e-c*c)*(b*b+d*d-f*f)) / 4;
    };
};

class RegularTetrahedron : public Tetrahedron {
public:
    RegularTetrahedron(Point *p1, Point *p2, Point *p3, Point *p4) : Tetrahedron(p1, p2, p3, p4) {
        double d1 = p1->distance(*p2);
        double d2 = p2->distance(*p3);
        double d3 = p3->distance(*p1);
        double d4 = p1->distance(*p4);
        double d5 = p2->distance(*p4);
        double d6 = p3->distance(*p4);

        bool regular = (fabs(d1-d2) < 0.001) && (fabs(d2-d3) < 0.001) && (fabs(d3-d4) < 0.001) && (fabs(d4-d5) < 0.001) && (fabs(d5-d6) < 0.001);

        if (!regular)
            throw "Given points do not form regular tetrahedron.";
    };
};

int main(){
    Point p1(0,0,0);
    Point p2(1,0,0);
    Point p3(0.5,sqrt(0.75),0);
    Point p4(0.5,sqrt(0.75)/3,sqrt(0.66));
    try {
        RegularTetrahedron tet(&p1, &p2, &p3, &p4);
        std::cout << "Surface area is: " << tet.surfaceArea() << std::endl;
        std::cout << "Volume is: " << tet.volume() << std::endl;
    } catch (const char* msg) {
        std::cerr << msg << std::endl;
    }
    return 0;
}
```
