```cpp
#include<bits/stdc++.h>
using namespace std;

const int MAX = 20;
bool prime[190];
int num[MAX];
long long int dp[MAX][190][2];

void sieve()
{
    memset(prime, true, sizeof(prime));
    prime[0] = prime[1] = false;
    for (int p=2; p*p<=189; p++)
    {
        if (prime[p] == true)
        {
            for (int i=p*p; i<=189; i += p)
                prime[i] = false;
        }
    }
}

long long int solve(int idx, int sum, int x)
{
    if (idx == -1)
        return prime[sum];
    if (dp[idx][sum][x] != -1)
        return dp[idx][sum][x];
    int k = (x) ? num[idx] : 9;
    long long int ans = 0;
    for (int i = 0; i <= k; i++)
        ans += solve(idx - 1, sum + i, x && (i == num[idx]));
    return dp[idx][sum][x] = ans;
}

long long int solve(string b)
{
    int idx = 0;
    for (int i = b.size()-1; i >= 0; i--)
        num[idx++] = b[i] - '0';
    return solve(idx - 1, 0, 1);
}

int main()
{
    sieve();
    memset(dp, -1, sizeof(dp));
    string a = "0", b;
    cin >> b;
    printf("%lld\n", solve(b) - solve(a));
    return 0;
}

