    return std::abs(prev_index - curr_index) > 1;
}

// Function to calculate max sum of subarray with conditions
int find_maximum_sum(std::vector<int> &arr) {
    std::vector<int> dp(arr.size(), 0);
    dp[0] = arr[0];
    for (int i = 1; i < arr.size(); ++i) {
        dp[i] = arr[i];
        for (int j = 0; j < i - 1; ++j) {
            if (no_adjacent_elements(j, i) && pairwise_coprime(arr, j, i)) 
                dp[i] = std::max(dp[i], dp[j] + arr[i]);
        }
        dp[i] = std::max(dp[i], dp[i-1]);
    }
    return dp.back();
}

int main() {
    std::vector<int> arr1{8, 4, 6, 15, 5};
    std::cout << find_maximum_sum(arr1) << std::endl;  // Output: 23
    std::vector<int> arr2{20, 15, 3, 4, 5, 11, 8};
    std::cout << find_maximum_sum(arr2) << std::endl;  // Output: 39
    return 0;
}
