using namespace std; 

class LeakTest {
public:
    int data;

    LeakTest() 
    { 
        data = 0;
        cout << "Constructor called!" << endl; 
    } 

    ~LeakTest() 
    {
        cout << "Destructor called!" << endl;
    } 
}; 

int main()
