    iom.add_child("substances", "Oxygen5.xml");
    std::cout << iom.find_resource_file("Oxygen5.xml") << std::endl;  // Output: /substances/Oxygen5.xml
    std::cout << iom.find_resource_file("Nonexistent.xml") << std::endl;  // Output: 
