```cpp
#include <iostream>
#include <stack>
#include <sstream>

void reverseWords(std::string &str)
{
    std::stack<std::string> words; 
    std::stringstream ss(str);
    std::string word;

    // Break string into words and push them into stack
    while (ss >> word)
        words.push(word);

    str = ""; 
    // Pop words from stack and append them to string
    while(!words.empty()) {
        str += words.top();
        words.pop();
        if (!words.empty())
            str += " ";
    }
}

int main() {
    std::string str = "This is a sample string";
    reverseWords(str);
    std::cout << str;
}
```
