    int M = pattern.length();
    int N = text.length();

    /* A loop to slide pattern one by one */
    for (int i = 0; i <= N - M; i++) {
        int j;
        /* For current index i, check pattern match */
        for (j = 0; j < M; j++)
            if (text[i + j] != pattern[j])
