#include <algorithm>

std::string missingNumbers(const std::string& str) {
    if (str.empty()) {
        return "0...n";
    }

    std::unordered_set<int> included;
    std::istringstream iss(str);
    std::string temp;
    int val, min = std::numeric_limits<int>::max(), max = std::numeric_limits<int>::min();
    bool first = true;

    while (iss >> temp) {
        try {
            val = std::stoi(temp);
            included.insert(val);
            if (first || val < min) {
                min = val;
            }
            if (first || val > max) {
                max = val;
            }
            first = false;
        } catch (const std::invalid_argument&) {
            // ignore non-integer strings
        }
    }

    if (first) {
        return "None";
    }

    std::vector<std::string> missing;
    for (int i = min; i <= max; i++) {
        if (included.find(i) == included.end()) {
            missing.push_back(std::to_string(i));
        }
    }

    std::stringstream result;
    std::copy(missing.begin(), missing.end() - 1,
        std::ostream_iterator<std::string>(result, " "));
    result << missing.back(); // to avoid extra space at the end

    return result.str();
}
