```cpp
#include <vector>
#include <random>

// Function for comparison
int cmp(int a, int b) {
    if (a < b) return -1;
    else if (a == b) return 0;
    else return 1;
}

// This function takes last element as pivot, places 
// the pivot element at its correct position in sorted 
// array, and places all smaller (smaller than pivot) 
// to left of pivot and all greater elements to right 
// of pivot 
int partition(std::vector<int>& lst, int left, int right, int pivot_index) {
    int pivot_value = lst[pivot_index];
    std::swap(lst[pivot_index], lst[right]);  // Move pivot to end
    int store_index = left;
    for (int i = left; i < right; ++i) {
        if (cmp(lst[i], pivot_value) < 0) {
            std::swap(lst[i], lst[store_index]);
            ++store_index;
        }
    }
    std::swap(lst[right], lst[store_index]);  // Move pivot to its final place
    return store_index;
}

int _select(std::vector<int>& lst, int left, int right, int k) {
    if (left == right) return lst[left];

    // Create a random number generator and generate a random index for pivot
    std::random_device rd;
    std::default_random_engine generator(rd());
    std::uniform_int_distribution<int> distribution(left, right);
    int pivot_index = distribution(generator);

    pivot_index = partition(lst, left, right, pivot_index);
    if (k == pivot_index) return lst[k];
    else if (k < pivot_index) return _select(lst, left, pivot_index - 1, k);
    else return _select(lst, pivot_index + 1, right, k);
}

double median(std::vector<int>& l) {
    int len = l.size();
    if (len % 2 == 1) return _select(l, 0, len - 1, len / 2);
    else {
        return 0.5 * (_select(l, 0, len - 1, len / 2 - 1) + 
                      _select(l, 0, len - 1, len / 2));
    }
}
