    delete[] Q;
}

bool CircularQueue::isFull() {
    if ((rear + 1) % size == front) {
        return true;
    }
    return false;
}

void CircularQueue::enqueue(int element) {
    if (isFull()) {
        cout << "Queue is Full\n";
    }
    else {
        rear = (rear + 1) % size;
        Q[rear] = element;
    }
}

int CircularQueue::dequeue() {
    int x = -1;
    if (front == rear) {
        cout << "Queue is Empty\n";
    }
    else {
        front = (front + 1) % size;
        x = Q[front];
    }
    return x;
}

int CircularQueue::getFront() {
    if (front == rear) {
        return -1;
    }
    return Q[front];
}

int CircularQueue::getRear() {
    if (front == rear) {
        return -1;
    }
    return Q[rear];
}
