pair<vector<int>, double> sort_vector(vector<int> array) {
    if (array.empty()) {
        return make_pair(vector<int>(), NAN);
    }
    vector<int> sorted_array(array); 
    sort(sorted_array.begin(), sorted_array.end());
    if ((sorted_array.front() + sorted_array.back()) % 2 == 0) {
