In C++, you can use the `random` library to generate random numbers. To prevent generating the same number more than twice in a row, you can keep track of the last two generated numbers and re-generate if the new number matches.

Let's see below pseudo random number generator and the way to prevent the generation of identical number more than two times:

```cpp
#include <random>
#include <iostream>

int generateRandomNumber(int min, int max, int exclude1 = -1, int exclude2 = -1){
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(min, max);

    int num;
    while(true) {
        num = dis(gen);
        if(num != exclude1 && num != exclude2)
            break;
    }
    return num;
}

int main() {
    int rand1 = generateRandomNumber(1, 20);
    int rand2 = generateRandomNumber(1, 20, rand1);

    while(true) {
        int rand3 = generateRandomNumber(1, 20, rand1, rand2);

        std::cout << rand3 << " ";

        // Shift the sequence for next iteration
        rand1 = rand2;
        rand2 = rand3;
    }
    return 0;
}
```

