```cpp
#include <vector>
#include <utility>
#include <algorithm>
using namespace std;

class Solution {
public:
    int N;
    vector<vector<int>> visited;
    vector<int> max_path;
    int max_sum = 0;

    vector<pair<int, int>> directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    void dfs(int x, int y, int k, vector<int>& path, vector<vector<int>>& chessboard, int path_sum){
        if (k == 0) {
            if (path_sum > max_sum) {
                max_sum = path_sum;
                max_path = path;
            }
            return;
        }
        for (auto& d : directions) {
            int nx = x + d.first, ny = y + d.second;
            if (0 <= nx && nx < N && 0 <= ny && ny < N && !visited[nx][ny]) {
                visited[nx][ny] = 1;
                path.push_back(chessboard[nx][ny]);
                dfs(nx, ny, k - 1, path, chessboard, path_sum+chessboard[nx][ny]);
                visited[nx][ny] = 0;
                path.pop_back();
            }
        }
    }

    vector<int> maxSumPath(vector<vector<int>>& chessboard, int k) {
        N = chessboard.size();
        visited.resize(N, vector<int>(N, 0));
        visited[N - 1][N - 1] = 1;
        vector<int> path = {chessboard[N - 1][N - 1]};
        dfs(N - 1, N - 1, k - 1, path, chessboard, chessboard[N - 1][N - 1]);
        return max_path;
    }
};
