vector<int> findMissingEdge(int n, vector<pair<int, int>> edges) {
    unordered_map<int, int> p;
    vector<vector<int>> res(n + 1, vector<int>(n + 1, 0));

    for (auto edge : edges) {
        int x = edge.first;
        int y = edge.second;
        p[x]++;
        p[y]++;
        res[x][y] = 1;
        res[y][x] = -1;
    }

    vector<int> missingEdge;
    for (int i = 1; i <= n; i++) {
        for (int j = i + 1; j <= n; j++) {
            if (p[i] < n - 1 && p[j] < n - 1) {
                if (res[i][j] == 0 && res[j][i] == 0) {
                    missingEdge.push_back(i);
                    missingEdge.push_back(j);
                    return missingEdge;
                }
            }
        }
    }
    return missingEdge;
}
