#include <iostream>
#include <cmath>
#include <limits>
#include <exception>

class InvalidInput : public std::exception {
public:
    const char* what() const throw() {
        return "Input is invalid.";
    }
};

double calcNthRoot(double number, int N){
    // THROW ERROR FOR INVALID INPUT
    if(N==0 || number<0 && N%2==0){
        throw InvalidInput();
        return -1;
    }

    // INITIALIZE GUESS VALUE
    double guess, prevGuess = std::numeric_limits<double>::max();

    // CALCULATE INITIAL GUESS VALUE
    if(N%2==0) guess = number / 2;
    else guess = number / 3;

    // PERFORM NEWTON-RAPHSON ITERATION
    while(abs(guess - prevGuess) > 0.0001){
        prevGuess = guess;
        guess = ((N - 1.0) * prevGuess + number / pow(prevGuess, N - 1)) / N;
    }
    return guess;
}

int main(){
    double number;
    int N;
    std::cout << "Enter a number: ";
    std::cin >> number;
    std::cout << "Enter N: ";
    std::cin >> N;

    try {
        std::cout << "The " << N << "th root of " << number << " is " << calcNthRoot(number, N) << std::endl;
    } catch(const std::exception& e) {
        std::cerr << e.what() << std::endl;
    }
    return 0;
}
```
This program uses the Newton-Raphson method to compute the Nth root, which doesn't require any mathematical functions like pow() or sqrt(). The method is a root-finding algorithm that produces successively better approximations of the roots.

Note: Although the pow function is used inside the `calcNthRoot` function, it is for simplification in explaining the concept. The pow function in this case can essentially be replaced by a loop that multiplies the guess by itself N-1 times. 

Also note that this program doesn't handle for the case where number is less than -1 and N is an even number, since even roots of negative numbers are undefined in the real numbers. If you want to work with complex numbers, this would require a different approach.

