Below is a simple example of the Timer Queue that uses C++. It does contain an `enqueue()` method for enqueuing new timer messages, a timing source through `std::chrono`, and a `poll()` method for querying the queue. Each message is a simple Timer Object that implements an interface `onTimer()`. 

Note that mutual exclusion on shared-memory portions is provided by the `std::mutex`, to make sure threads don't perform conflicting operations. 

```c++
#include <chrono>
#include <queue>
#include <mutex> 
#include <thread>

class TimerMessageInterface
{
public:
    virtual void onTimer() = 0;
};

class TimerQueue
{
public:
    void enqueue(std::chrono::time_point<std::chrono::system_clock> time, TimerMessageInterface* msg);
    void poll();
    void start();
    void stop();

private:
    struct TimerMessage
    {
        std::chrono::time_point<std::chrono::system_clock> time;
        TimerMessageInterface* msg;

        bool operator<(const TimerMessage& rhs) const
        {
            return time < rhs.time;
        }
    };

    void threadFunc();

private:
    std::priority_queue<TimerMessage> queue;
    std::mutex mtx;
    std::thread th;
    bool running;
};

void TimerQueue::enqueue(std::chrono::time_point<std::chrono::system_clock> time, TimerMessageInterface* msg)
{
    std::lock_guard<std::mutex> lock(mtx);
    queue.push(TimerMessage{ time, msg });
}

void TimerQueue::poll()
{
    std::lock_guard<std::mutex> lock(mtx);
    while (!queue.empty() && queue.top().time <= std::chrono::system_clock::now())
    {
        queue.top().msg->onTimer();
        queue.pop();
    }
}

void TimerQueue::start()
{
    running = true;
    th = std::thread(&TimerQueue::threadFunc, this);
}

void TimerQueue::stop()
{
    running = false;
    th.join();
}

void TimerQueue::threadFunc()
{
    while (running)
    {
        poll();
        std::this_thread::sleep_for(std::chrono::milliseconds(50)); // Sleep to reduce CPU usage, tweak as needed.
    }
}
```
