```cpp
#include <iostream>
#include <algorithm>
#include <vector>
#include <map>
#include <functional>

using namespace std;

double median(vector<int>& l, function<int(int, int)> cmp_func);

double median(vector<int>& l, function<int(int, int)> cmp_func) {
    if (l.empty())
        return -1; // return impossible value instead of None in Python
    map<int, int> dict_val;
    for (int i : l)
        dict_val[i]++;
    typedef function<bool(pair<int, int>, pair<int, int>)> Comparator;
    Comparator compFunctor = [&cmp_func](pair<int, int> elem1 ,pair<int, int> elem2){
        return cmp_func(0, elem1.first) < cmp_func(0, elem2.first);
    };
    set<pair<int, int>, Comparator> dict_val_set(dict_val.begin(), dict_val.end(), compFunctor);
    int cumulative_sum = 0, median_val = 0;
    for (auto& kv : dict_val_set){
        cumulative_sum += kv.second;
        if (cumulative_sum >= l.size() / 2){
            median_val = kv.first;
            break;
        }
    }
    if (l.size() % 2 == 0){
        if (cumulative_sum - dict_val[median_val] < l.size() / 2){
            return median_val;
        }
	else{
            for (auto& key : dict_val){
                if (cmp_func(key.first, median_val) == 0){
		    return (key.first + median_val) / 2.0;
		}
            }
        }
    }
    else{
        return median_val;
    }
}

int main(){
    vector<int> l1 = {3, 1, 2, 4, 5};
    vector<int> l2 = {-10, 4, 6, 1000, 10, 20};
    vector<int> l3 = {1, 2, 2, 4, 5};
    vector<int> l4 = {};
    vector<int> l5 = {2, 2, 2, 2, 2};
    cout << median(l1, [](int a, int b){ return a - b; }) << "\n";
    cout << median(l2, [](int a, int b){ return a - b; }) << "\n";
    cout << median(l3, [](int a, int b){ return a - b; }) << "\n";
    cout << median(l4, [](int a, int b){ return a - b; }) << "\n";
    cout << median(l5, [](int a, int b){ return a - b; }) << "\n";
    return 0;
}
```

Please note that C++ does not have an exact equivalent of Python's `None`, so in this C++ code, I used `-1` as representative impossible value. So if the input list is empty, the function will return `-1`. You will need to handle this scenario accordingly in your calling function. 

Also please note this demonstrated approach not fully equal with provided Python code in terms of performance. Counting repeated values directly in the map and then sorting this map stay quite high performance operations. For more performance-critical tasks investigating other approaches might be better.

