        tail = (tail + 1) % capacity;
        if (tail == head) {
            head = (head + 1) % capacity;
            full = true;
        }
    }

    int read() {
        if (head == tail && !full) {
            return -1; // Buffer is empty
        }
        int value = buffer[head];
        head = (head + 1) % capacity;
        full = false;
        return value;
    }
};

int main() {
    CircularBuffer cb(5);
    cb.write(1);
    cb.write(2);
    cb.write(3);
    std::cout << cb.read() << std::endl; // Output: 1
    cb.write(4);
    cb.write(5);
    cb.write(6);
    std::cout << cb.read() << std::endl; // Output: 2
    std::cout << cb.read() << std::endl; // Output: 3
    std::cout << cb.read() << std::endl; // Output: 4
    std::cout << cb.read() << std::endl; // Output: 5
    std::cout << cb.read() << std::endl; // Output: 6
    std::cout << cb.read() << std::endl; // Output: -1 (buffer is empty)
