Certainly, calculating Fibonacci seriously for very large numbers can be a significant challenge due to overflow of conventional integer data types and potential for extremely high recursion depths if not optimized properly. And it can be easily solved by Dynamic Programming. 

Here is a simple C++ script that calculates a Fibonacci number using Dynamic Programming and handles it as string to avoid overflow:

```C++
#include<iostream>
#include<vector>
#include<algorithm>
using namespace std;

string addStringNum(string s1, string s2) {
    if (s1.length() > s2.length())
        swap(s1, s2);

    string res = "";
    int n1 = s1.length(), n2 = s2.length();
    int diff = n2 - n1;
    int carry = 0;
    for (int i=n1-1; i>=0; i--) {
        int sum = ((s1[i]-'0') + (s2[i+diff]-'0') + carry);
        res.push_back(sum%10 + '0');
        carry = sum/10;
    }
    for (int i=n2-n1-1; i>=0; i--) {
        int sum = ((s2[i]-'0')+carry);
        res.push_back(sum%10 + '0');
        carry = sum/10;
    }
    if (carry)
        res.push_back(carry+'0');
    reverse(res.begin(), res.end());
    return res;
}

vector<string> fibonacci(10001);
void generateFibonacci() {
    fibonacci[0] = "0";
    fibonacci[1] = "1";
    for (int i=2; i<=10000; i++)
        fibonacci[i] = addStringNum(fibonacci[i-1], fibonacci[i-2]);
}

int main() {
    generateFibonacci();
    int n;
    cout << "Enter the nth Fibonacci number to calculate: ";
    cin >> n;
    cout << "The " << n << "th Fibonacci number is: " << fibonacci[n] << endl;
    return 0;
}
```

This program calculates a table of the first 10001 Fibonacci numbers as strings. The table is calculated using a simple dynamic programming algorithm that sums the last two calculated numbers to find the next one. The sum is done using a custom string addition function that avoids integer overflow. During runtime, it simply fetches the requested number from the generated table. This program can return Fibonacci numbers up to the 10,000th member of the sequence.

Note: This program doesn't handle cases where n < 0 or n > 10000, you should add checks for those if necessary in your use case.

