#include <iostream>
#include <cmath>       // for log10 and floor

void countDigits(long long a, long long b) {
    // check if numbers are distinct and positive
    if(a <= 0 || b <= 0 || a == b || a > 1000000000 || b > 1000000000) {
        std::cout << "Invalid Input\n";
        return;
    }
    // log10(a*b) = log10(a) + log10(b)
    double result = log10(a) + log10(b);

    // count number of digits in multiplication is floor(log10(a*b)) + 1
    int count = floor(result) + 1;

    std::cout << "Multiplication would result in: " << pow(10, result) << "\n";
    std::cout << "Number of digits in result: " << count << "\n";
}

