        return (sortedNumbers[sortedNumbers.size() / 2 - 1] + sortedNumbers[sortedNumbers.size() / 2]) / 2;
    } else {
        return sortedNumbers[sortedNumbers.size() / 2];
    }
}

std::vector<double> mode(const std::vector<double>& numbers) {
    if (numbers.empty()) {
        return std::vector<double>{0};
    }
    std::unordered_map<double, int> frequencyMap;
    for (const auto& num : numbers) {
        frequencyMap[num]++;
    }
    int maxFrequency = 0;
    for (const auto& pair : frequencyMap) {
        maxFrequency = std::max(maxFrequency, pair.second);
    }
    std::vector<double> modes;
    for (const auto& pair : frequencyMap) {
        if (pair.second == maxFrequency) {
            modes.push_back(pair.first);
        }
    }
    return modes;
}
