```c++
#include <iostream>
using namespace std;

// Implementation of binarySearch using recursion
int binarySearch(int arr[], int l, int r, int x) {
    if (r >= l) {
        int mid = l + (r - l) / 2;

        // If the element is present at the middle itself
        if (arr[mid] == x)  
            return mid; 

        // If the element is smaller than the middle, then it can only be present in the left subarray
        if (arr[mid] > x) 
            return binarySearch(arr, l, mid - 1, x); 

        // Else the element is in the right subarray
        return binarySearch(arr, mid + 1, r, x); 
   } 

   // We reach here when the element is not present in the array
   return -1; 
} 


int main(void) {
    int arr[] = {2, 3, 4, 10, 40}; 
    int x; 
    cout<<"Enter number to search: ";
    cin>>x;
    int n = sizeof(arr)/ sizeof(arr[0]); 
    int result = binarySearch(arr, 0, n-1, x); 
    (result == -1)? printf("Element is not present in array"): printf("Element is present at index %d", result); 
    return 0; 
}
```
