public boolean checkRules(List<String> rules, String input) {
    for (String rule : rules) {
        String[] lines = rule.split("}");
        boolean ruleSatisfied = false;
        for (String line : lines) {
            if (line.contains("if")) {
                String condition = line.substring(line.indexOf("(") + 1, line.indexOf(")"));
                if (condition.contains("input.contains")) {
                    String value = condition.substring(condition.indexOf("(") + 1, condition.indexOf(")"));
                    if (input.contains(value)) {
                        ruleSatisfied = true;
                        break;
                    }
                } else if (condition.contains("input.length()")) {
                    int length = Integer.parseInt(condition.substring(condition.indexOf(">") + 1));
                    if (input.length() > length) {
                        ruleSatisfied = true;
                        break;
                    }
                }
            }
        }
        if (!ruleSatisfied) {
            return false;
        }
    }
    return true;
}
```

