Here is a simple C++ program to construct a single linked list with insert (at end) and delete (by key) operations:

```c++
#include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* next;
};

// Function to create a new Node in heap
Node* newNode(int data)
{
    Node* temp = new Node();
    temp->data = data;
    temp->next = NULL;
    return temp;
}

// Function to insert node at the end of the list
void insertNode(Node** head, int data)
{
    Node* new_node = newNode(data);
    if(*head == NULL)
    {
        *head = new_node;
        return;
    }
    Node* temp = *head;
    while(temp->next != NULL)
    {
        temp = temp->next;
    }
    temp->next = new_node;
}

// Function to delete a node by key
void deleteNode(Node **head, int key)
{
    Node* temp = *head, *prev;
    if(temp != NULL && temp->data == key)
    {
        *head = temp->next;
        delete temp;
        return;
    }
    while(temp != NULL && temp->data != key)
    {
        prev = temp;
        temp = temp->next;
    }
    if(temp == NULL)
    {
        cout << "Element not found in the list\n";
        return;
    }
    prev->next = temp->next;
    delete temp;
}

// Function to print the linked list
void printList(Node* node)
{
    while (node != NULL) {
        cout << " " << node->data;
        node = node->next;
    }
}

int main()
{
    Node* head = NULL;
    insertNode(&head, 1);
    insertNode(&head, 2);
    insertNode(&head, 3);
    insertNode(&head, 4);
    insertNode(&head, 5);
    cout<<"Linked list is :";
    printList(head);
    cout<<endl;
    deleteNode(&head, 3);
    cout<<"Linked list after deletion of 3 :";
    printList(head);
    return 0;
}
```
