double findMedian(std::vector<double> &numArray, int size) { 
    // First we sort the array 
    std::sort(numArray.begin(), numArray.end()); 

    // Check if the number of elements is even or odd
    if (size % 2 != 0) 
        // If odd, the median is the middle number
        return (double)numArray[size/2]; 

