#include <map>

std::string convertDateFormat(const std::string& date)
{
   std::map<std::string, std::string> months{
        {"January", "01"},
        {"February", "02"},
        {"March", "03"},
        {"April", "04"},
        {"May", "05"},
        {"June", "06"},
        {"July", "07"},
        {"August", "08"},
        {"September", "09"},
        {"October", "10"},
        {"November", "11"},
        {"December", "12"},
    };

    std::string month = date.substr(0, date.find(' ')); 
    std::string day_year = date.substr(date.find(' ')+1); 
    std::string day = day_year.substr(0, day_year.find(',')); 
    std::string year = day_year.substr(day_year.find(' ')+1);

    std::string newFormat =  months[month] + "/" + day + "/" + year;
    return newFormat;
}

