unsigned int Shader::compileSingleShader(const char* shaderStr, GLenum shaderEnum) {
    int success;
    char infoLog[512];

    unsigned int shader = glCreateShader(shaderEnum);
    glShaderSource(shader, 1, &shaderStr, NULL);
    glCompileShader(shader);

