#include<bits/stdc++.h>
using namespace std;
const int MAX = 1000;

vector<int> generatePrimes(int n) {
    vector<bool> prime(n+1, true);
    prime[0] = prime[1] = false;
    for (int p = 2; p*p <= n; p++) {
        if (prime[p] == true) {
            for (int i = p*p; i <= n; i += p)
                prime[i] = false;
        }
    }
    vector<int> primes;
    for (int i = 2; i <= n; i++) {
        if (prime[i])
            primes.push_back(i);
    }
    return primes;
}

int numOfWays(int n) {
    vector<int> primes = generatePrimes(n);
    int count = 0;
    for (int i = 0; i < primes.size(); i++) {
        for (int j = i; j < primes.size(); j++) {
            for (int k = j; k < primes.size(); k++) {
                if (primes[i] + primes[j] + primes[k] == n)
                    count++;
            }
        }
    }
    return count;
}

int main() {
    int n;
    cout << "Enter the number: ";
    cin >> n;
    cout << "Number of ways to represent " << n << " as sum of 3 primes is: " << numOfWays(n) << "\n";
    return 0;
}
```

