Here is a simple C++ code snippet showing how you could design a class for a sparse matrix. In this snippet, we implement main methods to fill the matrix, display it and do addition operation. 

```cpp
#include<iostream>
using namespace std;

class SparseMatrix
{
private:
    int **data;
    int row, col, len;
public:
    SparseMatrix(int r, int c, int l)
    {
        data = new int*[l+1];
        for(int i=0; i<l+1; i++)
        {
            data[i] = new int[3];
        }
        row = r;
        col = c;
        len = l;
    }

    void fillMatrix()
    {
        cout<<"\nEntering non-zero values of the Matrix:";
        data[0][0] = row;
        data[0][1] = col;
        data[0][2] = len;
        for(int i=1; i<=len; i++)
        {
            cout<<"\nEnter row, column, value: ";
            cin>>data[i][0]>>data[i][1]>>data[i][2];
        }
    }

    void display()
    {
        cout<<"\nSparse Matrix representation:";
        for(int i=0; i<=len; i++)
        {
            cout<<"\n"<<data[i][0]<<" "<<data[i][1]<<" "<<data[i][2];
        }
    }

    SparseMatrix operator +(SparseMatrix &s)
    {
       if(row!=s.row || col!=s.col)
       {
           // As we can't add matrices, if both matrices don't have the same dimensions.
           return *this;
       }
       int l = len + s.len;
       SparseMatrix result(row, col, l);

       int i=1, j=1, k=1;
       while(i<=len && j<=s.len)
       {
           if(data[i][0] < s.data[j][0] || (data[i][0] == s.data[j][0] && data[i][1] < s.data[j][1]))
           {
               result.data[k][0] = data[i][0];
               result.data[k][1] = data[i][1];
               result.data[k][2] = data[i][2];
               i++;
           }
           else if(data[i][0] > s.data[j][0] || (data[i][0] == s.data[j][0] && data[i][1] > s.data[j][1]))
           {
               result.data[k][0] = s.data[j][0];
               result.data[k][1] = s.data[j][1];
               result.data[k][2] = s.data[j][2];
               j++;
           }
           else
           {
               result.data[k][0] = data[i][0];
               result.data[k][1] = data[i][1];
               result.data[k][2] = data[i][2] + s.data[j][2];
               i++;
               j++;
           }
           k++;
       }
       while(i<=len)
       {
           result.data[k][0] = data[i][0];
           result.data[k][1] = data[i][1];
           result.data[k][2] = data[i][2];
           i++;
           k++;
       }

       while(j<=s.len)
       {
           result.data[k][0] = s.data[j][0];
           result.data[k][1] = s.data[j][1];
           result.data[k][2] = s.data[j][2];
           j++;
           k++;
       }

       return result;
    }
};
```

