Solving the problem in C++ involves utilizing the Shunting Yard algorithm for parsing mathematical expressions specified in infix notation and then evaluating those expressions. Note though, this is a complex problem and considering all edge cases would require a code longer than a simplified version presented here. 

Here is a basic example, recursive descent parser, to parse and calculate a formula with +, -, * /, ( ).

```cpp
#include <cctype>
#include <cstdlib>
#include <iostream>
#include <sstream>
#include <string>

char token;  // current token
std::string tokenString;
std::istringstream tokenStream;

void getToken() {  // fetch the next token
    while (tokenStream >> token) {
        if (std::isdigit(token) || token == '(' || token == ')' || token == '+' ||
            token == '-' || token == '*' || token == '/') {
            return;
        }
    }
    token = 0;  // token stream is exhausted
}

double number() {  // process a number
    double result = std::digit(token);
    getToken();  // consume the number
    return result;
}

double factor();  // declaration required for mutual recursion

double term() {  // process a term
    double result = factor();
    while (token == '*' || token == '/') {
        if (token == '*') {
            getToken();  // consume '*'   
            result *= factor();
        } else {
            getToken();  // consume '/'
            double divisor = factor();
            if (divisor == 0)
                throw std::runtime_error("Divide by zero");
            result /= divisor;
        }
    }
    return result;
}

double expr() {  // process an expression
    double result = term();
    while (token == '+' || token == '-') {
        if (token == '+') {
            getToken();  // consume '+'
            result += term();
        } else {
            getToken();  // consume '-'
            result -= term();
        }
    }
    return result;
}

double factor() {  // process a factor
    if (token == '(') {
        getToken();  // consume '('
        double result = expr();
        if (token != ')')
            throw std::runtime_error("Expected ')'");
        getToken();  // consume ')'
        return result;
    } else
        return number();
}

int main() {
    try {
        std::string s;
        while (std::getline(std::cin, s)) {
            tokenStream.str(s);
            tokenStream.clear();
            getToken();
            if (!tokenStream)
                return 1;
            std::cout << expr() << "\n";
            if (token)
                std::cerr << "Unexpected '" << token << "'\n";
        }
    } catch (std::exception &e) {
        std::cerr << "Error: " << e.what() << "\n";
    } catch (...) {
        std::cerr << "ERROR: unknown..\n";
    }
    return 0;
}
```

Remember, this is a basic version. It does not handle malformed expressions, unary minus and other more complex issues. This works well for perfectly formatted mathematical expressions, but should be seen as a starting point for larger, more robust solutions.

