    int center = 0, right = 0;
    int max_len = 0, res = 0;

    for (int i = 1; i+1 < n; i++) {
        p[i] = right > i ? min(right - i, p[2 * center - i]) : 0;

        while (s[i + 1 + p[i]] == s[i - 1 - p[i]]) {
            p[i]++;
        }

        if (i + p[i] > right) {
            center = i;
            right = i + p[i];
