Here is a function in C++ that does exactly what you ask. To perform a rotation, it uses a combination of left and right shifts. It also makes use of the `bitset` library to convert integers to binary. Importantly, bit rotation only makes sense for unsigned integers, so shift is implemented as negative, positive or zero.

```c++
#include <iostream>
#include <string>
#include <bitset>
#include <stdexcept>
using namespace std;

string circular_shift(int x, int shift) {
    // Ensure that 'x' is non-negative.
    if (x < 0) {
        throw invalid_argument("Input 'x' must be non-negative");
    }

    // Ensure that 'shift' is valid.
    if (abs(shift) > 32) {
        throw invalid_argument("Shift amount must be between -32 and 32");
    }

    unsigned int unsigned_x = static_cast<unsigned int>(x);
    int bin_length = 32; // For 32-bit integers

    // Handle 'shift' larger than binary length.
    shift %= bin_length;

    if (shift < 0) {
        // Left rotation
        shift = abs(shift);   
        return bitset<32>((unsigned_x << shift) | (unsigned_x >> (bin_length - shift))).to_string();
    } else {
        // Right rotation
        return bitset<32>((unsigned_x >> shift) | (unsigned_x << (bin_length - shift))).to_string();
    }
}

