// Function to get the next prime number
int next_prime(int n)
{
    // If number is smaller than 2, increment it
    if (n <= 1)
        n+=2;
    else
        n++;

    while (1)
    {
         int i;
         for (i = 2; i <= sqrt(n); i++) 
            if (n % i == 0) 
                break;

         // 'n' is a prime number if no divisor found
         if (i == n)
            return n;

         // Try the next number
         n++;
    }
