int fib(int n)
{
    static vector<int> fibCache = { 0, 1 };
    if (n < fibCache.size())
        return fibCache[n];
    else {
        fibCache.push_back(fibCache.back() + *(fibCache.end() - 2));
        return fib(n);
    }
}

