#include <algorithm>

std::vector<int> get_odd_collatz(int n) {
    std::vector<int> collatz;
    while(n ! = 1) {
        if(n % 2 != 0) { //If n is odd
            collatz.push_back(n); //add it to the vector
        }
        //Apply the steps of the collatz conjecture
        n = n % 2 == 0 ? n / 2 : (3*n) + 1;
