std::vector<std::vector<int>> combine(const std::vector<std::vector<int>>& vv, unsigned int level, unsigned int nfs) {
    std::vector<std::vector<int>> result;
    if (level == 0) {
        result.push_back(std::vector<int>());
        return result;
    }

