#include <cstdint>

class Byte {
public:
  explicit Byte(const std::uint8_t* data) : data_(data) {}

  int32_t get_byte(int start_bit, int num_bits) const {
    int32_t result = 0;
    for (int i = start_bit; i < start_bit + num_bits; ++i) {
      result <<= 1;
      result |= (data_[i / 8] >> (7 - (i % 8))) & 1;
    }
    return result;
  }

private:
