```cpp
#include<iostream>
#include<string>

using namespace std;

// Function to print permutations of string 
// Here the string is taken as str and starting index of string is s and end is e.

void permute(string str, int s, int e)
{
    // Base case
    if (s == e)
        cout << str << endl;
    else
    {
        // Permutations made by swapping
        for (int i = s; i <= e; i++)
        {
            // Swapping done
            swap(str[s], str[i]);

            // Recursion called
            permute(str, s+1, e);

            // Swap back to restore the original string
            swap(str[s], str[i]);
        }
    }
}

// Driver Code
int main()
{
    string str = "ABC";
    int n = str.size();
    // Function call to print permutations
    permute(str, 0, n-1);
    return 0;
}
```

