Here is a simple implementation of a Hash Table in C++ as per your request:

```cpp
#include<vector>
#include<list>
#include<iostream>
using namespace std;

template<typename Key, typename Value>
class HashTable{
private:
    double threshold = 0.75;  // load factor threshold
    int capacity = 50;        // initial capacity of hash table
    int size = 0;             // current size of hash table

    // hash table represented as an vector of lists (for chaining)
    vector<list<pair<Key, Value>>> table;

    // hashing function (using simple modulus with table's capacity)
    int hash(Key key){
        return key % capacity;
    }

    // function to resize table
    void resize(){
        if (loadFactor() > threshold){
            // store a copy of the old table
            auto oldTable = table;

            // double the capacity
            capacity *= 2;
            size = 0;

            // create a new double sized table
            table = vector<list<pair<Key, Value>>>(capacity);

            // copy all elements from the old table to the new table
            for (auto &chain : oldTable){
                for (auto &entry : chain){
                    insert(entry.first, entry.second);
                }
            }
        }
    }

public:
    HashTable(){
       table = vector<list<pair<Key, Value>>>(capacity);
    }

    double loadFactor(){
        return (1.0 * size) / capacity;
    }

    void insert(Key key, Value value){
        int index = hash(key);
        for(auto& p : table[index]){
            if(p.first == key){
                p.second = value;
                return;
            }
        }
        table[index].push_back({key, value});
        size++;

        // resize table if necessary
        resize();
    }

    void remove(Key key){
        int index = hash(key);
        for(auto it = table[index].begin(); it != table[index].end(); ++it){
            if(it->first == key){
                table[index].erase(it);
                size--;
                return;
            }
        }
    }

    Value search(Key key){
        int index = hash(key);
        for(auto& p : table[index]){
            if(p.first == key){
                return p.second;
            }
        }
        cout << "\nElement not found!";
        exit(0);
    }
};
```
This HashTable class uses separate chaining to handle collisions. It contains: a hash function, an insert function to add key-value pairs, a remove function to delete key-value pairs based on the key, and a search function to obtain the value of a particular key.

The capacity of the hash table doubles when the load factor (size/table capacity) exceeds 0.75, as defined in the resize() function. The loadFactor() function returns the current load factor.
The implementation uses the STL's list and vector to store the keys and values. The hash function is a simple modulus operation with the table's capacity.

Please note that this is a simple implementation which assumes the keys are integer type and the hash function can be improved for better performance.

This code only provides a basic functionality, for full-fledged hash table implementation, there should be more functionalities and error handling cases covered (Like rehashing, handling of negative keys and zero, better hash function which uniformly distributes keys, etc). It is also recommended to write the test cases/utils to check the functionality of implemented hash table.

