std::unordered_map<std::string, std::string> macroDefinitions;

// Function to expand a single macro
std::string expandMacro(const std::string& macroName, const std::string& args) {
    std::string replacementText = macroDefinitions[macroName];
    std::istringstream argStream(args);
    std::string arg;
    int argIndex = 1;
    while (std::getline(argStream, arg, ',')) {
        std::string param = "RTIMDB_NOTHROW_PARAM_" + std::to_string(argIndex);
        std::string argPlaceholder = "RTIMDB_NOTHROW_ARG_" + std::to_string(argIndex);
        size_t pos = replacementText.find(param);
        while (pos != std::string::npos) {
            replacementText.replace(pos, param.length(), arg);
            pos = replacementText.find(param);
        }
        pos = replacementText.find(argPlaceholder);
        while (pos != std::string::npos) {
            replacementText.replace(pos, argPlaceholder.length(), arg);
            pos = replacementText.find(argPlaceholder);
        }
        argIndex++;
    }
    return replacementText;
}

// Function to expand macros in the token list
std::string expandMacros(const std::string& tokenList) {
    std::istringstream tokenStream(tokenList);
    std::string token;
    std::string expandedTokenList;
    while (std::getline(tokenStream, token, ' ')) {
        if (token.find('(') != std::string::npos) {
            size_t pos = token.find('(');
            std::string macroName = token.substr(0, pos);
            std::string args = token.substr(pos + 1, token.length() - pos - 2);
            std::string expandedMacro = expandMacro(macroName, args);
            expandedTokenList += expandMacros(expandedMacro) + " ";
        } else if (macroDefinitions.find(token) != macroDefinitions.end()) {
            expandedTokenList += expandMacros(macroDefinitions[token]) + " ";
        } else {
            expandedTokenList += token + " ";
        }
    }
    return expandedTokenList;
}

int main() {
    macroDefinitions["SQUARE"] = "(x * x)";
    macroDefinitions["MAX"] = "((a > b) ? a : b)";

    std::string input = "MAX(SQUARE(3), 5)";
    std::string output = expandMacros(input);
    std::cout << output << std::endl;  // Output: "(((3 * 3) > 5) ? (3 * 3) : 5)"

    return 0;
}
```

