The provided function is not completely correct because it does not get rid of trailing spaces. Here is a corrected version of the function. This version will also handle the condition where the string is empty and when there is no space in the string.

```cpp
#include<iostream>
#include<string>
using namespace std;

string removeExtraSpaces(string str) {
    string output = "";
    int i = 0;

    // Ignore leading spaces
    while (str[i] == ' ')
        i++;

    // Copy characters and ignore multiple spaces  
    for (; i < str.length(); i++) {

        // If current character is not ' ' or if it is a space but previous character is not a space, append to the output string
        if (str[i] != ' ' || (str[i] == ' ' && str[i-1] != ' '))
            output += str[i];
    }

    // If there are trailing spaces, remove them
    while (output[output.length()-1] == ' ')
        output = output.substr(0, output.length()-1);

    return output;
}

