```cpp
#include <vector>
#include <algorithm>

std::vector<float> computeLLR(const std::vector<float>& alpha_prime_col, const std::vector<float>& metric_c_col, const std::vector<std::vector<float>>& beta_col, const std::vector<std::vector<int>>& colOutputs, const std::vector<std::vector<int>>& colNextStates, int colEncoder_n, int max_states_col, float den_llr_u) {
    std::vector<float> llr_values;

    for (int state = 0; state < max_states_col; state++) {
        float delta1 = alpha_prime_col[state] + metric_c_col[colOutputs[0][state]] + beta_col[0][colNextStates[0][state]];
        float delta2 = den_llr_u;
        float den_llr_u = std::max(delta1, delta2);

        for (int ii = 0; ii < colEncoder_n; ii++) {
            if (colOutputs[0][state] & (1 << (colEncoder_n - 1 - ii))) {
                delta1 = alpha_prime_col[state] + metric_c_col[colOutputs[0][state]] + beta_col[1][colNextStates[0][state]];
                delta2 = den_llr_u;
                den_llr_u = std::max(delta1, delta2);
            }
        }

        llr_values.push_back(den_llr_u);
    }

    return llr_values;
}
