Here's an example of a simple doubly linked list implementation in C++ where elements are always kept in ascending order. 

First, define Node structure in a DLL:

```cpp
struct Node {
    int value;
    Node* next;
    Node* prev;

    Node(int val) : value(val) {
        next = nullptr;
        prev = nullptr;
    }
};
```

Second, define a class with required functions:

```cpp
class SortedDLL {
  private:
    Node* head;
    Node* tail;

  public:
    SortedDLL() : head(nullptr), tail(nullptr) {}

    // Destructor to clean up memory
    ~SortedDLL() {
        while (head) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    // To insert node in DLL
    void insertNode(int value) {
        Node* newNode = new Node(value);

        if (!head || value <= head->value) {
            newNode->next = head;
            if (head)
                head->prev = newNode;
            head = newNode;
        } else {
            Node* current = head;
            while (current->next && current->next->value < value)
                current = current->next;

            newNode->next = current->next;
            if (current->next)
                current->next->prev = newNode;
            current->next = newNode;
            newNode->prev = current;
        }
    }

    // To remove node from DLL
    void removeNode(int value) {
        Node* nodeToRemove = head;

        while (nodeToRemove && nodeToRemove->value != value)
            nodeToRemove = nodeToRemove->next;

        if (nodeToRemove) {
            if (nodeToRemove->next)
                nodeToRemove->next->prev = nodeToRemove->prev;

            if (nodeToRemove->prev)
                nodeToRemove->prev->next = nodeToRemove->next;
            else
                head = nodeToRemove->next;

            delete nodeToRemove;
        }
    }
};
```

With above C++ doubly linked list, you can perform the required operations. However, note above code doesn't handle some edge cases: it will insert duplicates, and if you try to remove a value that doesn't exist in the list, the function does nothing. You'd need to build in additional checks for those scenarios depending on your exact use-case and requirements.

Also note, real-world doubly linked list implementations would be more robust and carefully manage memory to prevent leaks, especially where exceptions could hindering.

