Yes, this code can indeed be translated into C++. Here is a version in C++:

```c++
#include <unordered_map>
#include <unordered_set>
#include <deque>
#include <string>

using namespace std;

bool is_ecstatic (string s) {

    if (s.length() < 5)
        return false;

    unordered_map<char, int> hash_map;
    unordered_set<char> unique_chars(s.begin(), s.end());
    deque<char> prev_char(s.begin(), s.end());

    for (char c : unique_chars) {
        int count = count(s.begin(), s.end(), c);
        if (count < 3)
            return false;
        hash_map[c] = count;
    }

    prev_char.pop_front();
    prev_char.push_back('\0');
    for (int i = 0; i < s.length(); ++i) {
        if (s[i] == prev_char[i])
            return false;
    }

    for (auto& kv : hash_map) {
        if (kv.second % 3 != 0)
            return false;
    }

    return true;
}
