Here is a simple C++ program that sorts a vector of integers using Bubble Sort:

```C++
#include <iostream>
#include <vector>

using namespace std;

// Function to print vector
void printVector(vector<int> v) {
    for (int i = 0; i < v.size(); i++) {
        cout << v[i] << " ";
    }
    cout << "\n";
}

// Function to implement bubble sort
void bubbleSort(vector<int>& v) {
    for (int i = 0; i < v.size(); i++) {
        for (int j = 0; j < v.size() - i - 1; j++) {
            if (v[j] > v[j + 1]) {
                // Swap elements
                swap(v[j], v[j + 1]);
            }
        }
    }
}

int main() {
    // Initialize vector
    vector<int> myVector = {2, 3, 1, 8, 4, 5, 6};

    // Print unsorted vector
    cout << "Original vector: ";
    printVector(myVector);

    // Sort vector using bubble sort
    bubbleSort(myVector);

    // Print sorted vector
    cout << "Sorted vector: ";
    printVector(myVector);

    return 0;
}
```

The above code prints out:
```
Original vector: 2 3 1 8 4 5 6 
Sorted vector: 1 2 3 4 5 6 8 
