        return r >= 0 && r <= 255 && g >= 0 && g <= 255 && b >= 0 && b <= 255;
    }

    void increaseBrightness(int amount) {
        brightness = std::min(10, brightness + amount);
    }

    void decreaseBrightness(int amount) {
        brightness = std::max(0, brightness - amount);
    }

    void turnOff() {
        brightness = 0;
    }
};

