bool is_palindrome_substring(std::string str) {
    int length = str.length();
    for(int size = 2; size < length + 1; size++) {
        for(int start = 0; start < (length - size) + 1; start++) {
            std::string piece = str.substr(start, size);
            std::string rev = piece;
            std::reverse(rev.begin(), rev.end());
            if(piece == rev) {
