    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}

bool is_special_char(char c) {
    return (c < 'A' || (c > 'Z' && c < 'a') || c > 'z') && !is_vowel(tolower(c));
}

std::vector<std::string> advanced_string_list(std::vector<std::string> lst, bool reverse_length = false, bool reverse_alpha = false) {
    std::vector<std::string> result;

    for(auto word : lst) {
        if(!std::any_of(word.begin(), word.end(), is_vowel) || 
           std::any_of(word.begin(), word.end(), is_special_char) ||
           !is_palindrome_substring(word))
            continue;
        result.push_back(word);
    }

    auto cmp = [](const std::string& l, const std::string& r) {
        if (l.size() != r.size())
            return l.size() < r.size();
        int lv = std::count_if(l.begin(), l.end(), is_vowel),
            rv = std::count_if(r.begin(), r.end(), is_vowel);
        if (lv != rv)
            return lv < rv;
        return l < r;
    };

    std::sort(result.begin(), result.end(), cmp);

    if(reverse_length)
        std::reverse(result.begin(), result.end());

    if(reverse_alpha)
        std::sort(result.rbegin(), result.rend());

    return result;
}

