#include<bits/stdc++.h>
using namespace std;

struct Stats {
    double average;
    int median;
    int mode;
};

void getAverage(int a[], int n, Stats &stats) {
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
    }
    stats.average = sum / n;
}

void getMedian(int a[], int n, Stats &stats) {
    sort(a, a + n);

    if (n % 2 == 0) {
        stats.median = (a[n / 2 - 1] + a[n / 2]) / 2;
    } else {
        stats.median = a[n / 2];
    }
}

void getMode(int a[], int n, Stats &stats) {
    unordered_map<int, int> freq;
    int max_count = -1;
    stats.mode = a[0];

    for (int i = 0; i < n; i++) {
        freq[a[i]]++;

        if (freq[a[i]] > max_count) {
            max_count = freq[a[i]];
            stats.mode = a[i];
        }
    }
}

Stats arrayStats(int a[], int n) {
    Stats stats;
    getAverage(a, n, stats);
    getMedian(a, n, stats);
    getMode(a, n, stats);
    return stats;
}

int main() {
    int arr[] = {5, 8, 2, 9, 5};
    int n = sizeof(arr) / sizeof(arr[0]);

    Stats stats = arrayStats(arr, n);

    cout << "The average is: " << stats.average << endl;
    cout << "The median is: " << stats.median << endl;
    cout << "The mode is: " << stats.mode << endl;

    return 0;
}
