    {10, 0, 20, 0},
    {15, 10, 25, 30},
    {8, 25, 15, 55}
};
std::size_t totalSize = CalculateTotalMemorySize(parts, 3);
// totalSize should be 24 bytes (3 instances * 8 bytes per instance)
