    Point(double x_in, double y_in) : x(x_in), y(y_in) {}

    Point() {
        srand(static_cast<unsigned>(time(0)));
        x = static_cast<double>((rand() % 21) - 10); 
        y = static_cast<double>((rand() % 21) - 10); 
    }

