        return sqrt(x*x + y*y);
    }

    double distanceFromPoint(const Point &p) {
        double dx = x - p.x;
        double dy = y - p.y;
        return sqrt(dx*dx + dy*dy);
    }

    bool operator==(const Point &p) const {
        return x == p.x && y == p.y;
    }

    void print() const {
        std::cout << "(" << x << ", " << y << ")";
    }

