We can find the middle element of a doubly linked list by using two pointers. Initially, both pointers point to the start of the list. We move one pointer one step at a time and another pointer two steps at a time. When the fast pointer reaches the end, the slower pointer will be at the middle of the linked list.

Then, to swap the values of the nodes, we simply need to save the value of the last node, replace its value with the middle node's value, and then put the saved value into the middle node. 

Here is a C++ code to find and swap the middle and last node:

```c++
#include<iostream>
using namespace std;

struct Node {
    int data;
    Node* prev;
    Node* next;
};

//To add new node at the end of list
void push(Node** head_ref, int new_data) {
    Node* new_node = new Node;
    new_node->data = new_data;
    new_node->next = *head_ref;
    new_node->prev = NULL;
    if ((*head_ref) != NULL) (*head_ref)->prev = new_node ;
    *head_ref = new_node;
}

//Swaps middle node value with last node value
void swap(Node** head_ref) {
    Node* slow = *head_ref;
    Node* fast = *head_ref;
    Node* current = NULL;

    //finding the middle and the last element
    while (fast != NULL && fast->next != NULL) {
        fast = fast->next->next;
        slow = slow->next;
        current = (current == NULL) ? *head_ref : current->next;
    }

    //Swapping the values
    int temp = current->data;
    current->data = slow->data;
    slow->data = temp;
}

//To print the list
void printList(Node* node) {
    while (node != NULL) {
        cout << node->data << " ";
        node = node->next;
    }
}

int main() {
    Node* head = NULL;

    push(&head, 7);
    push(&head, 6);
    push(&head, 5);
    push(&head, 4);
    push(&head, 3);
    push(&head, 2);
    push(&head, 1);

    cout << "Original linked list \n";
    printList(head);

    swap(&head);

    cout << "\nLinked list after swapping \n";
    printList(head);
    return 0;
}
```

