Here is a simple function to check if the passed string has the correct bracketing or not. The function uses a stack to keep track of the brackets and check if they are properly nested.

This code is written in C++:

```c++
#include<algorithm>
#include<stack>
#include<iostream>
using namespace std;

bool correct_bracketing(string str)
{
    //stack to keep track of brackets
    stack<char> s;
    for(int i = 0; i<str.length(); i++)
    {
        if(str[i] == '<' || str[i] == '{' || str[i] == '[' || str[i] == '(')
        {
           s.push(str[i]);
        }
        else
        {
            if(s.empty())
            return false;

            char top = s.top();
            s.pop(); 
            switch(str[i])
            {
            case '>': if(top != '<') return false; break;
            case '}': if(top != '{') return false; break;
            case ']': if(top != '[') return false; break;
            case ')': if(top != '(') return false; break;
            }
        }
    }

    //if stack is empty then brackets are properly nested
    if(s.empty())
    return true;
    else
    return false;
}

int main()
{
    string str = "<<><>>";
    if(correct_bracketing(str))
    cout<<"The brackets in string are properly nested\n";
    else
    cout<<"The brackets in string are not properly nested\n";
    return 0;
}
```

In this C++ code:
- A stack (s) is created to handle the brackets.
- For each character in string str, 
  - it checks if it is an opening bracket '<', '{', '[' or '(' then pushes it to the stack.
