    void LoadResource(const std::string& name) {
        if (!pGraphicsContext || !pFileSystem) {
            std::cerr << "Missing dependencies for resource loading" << std::endl;
            return;
        }

        auto it = resources.find(name);
        if (it != resources.end()) {
