    ht.insert("apple", 5);
    ht.insert("banana", 10);
    ht.insert("orange", 7);

    std::cout << ht.get("apple") << std::endl;  // Output: 5
    std::cout << ht.get("banana") << std::endl; // Output: 10
    std::cout << ht.get("grape") << std::endl;  // Output: -1

    ht.remove("banana");
    std::cout << ht.get("banana") << std::endl; // Output: -1

    return 0;
}
```

