int Prim::mst_add_lowest_edge(Graph *g, Graph *mst)
{
    int min_weight = INT_MAX;
    int min_vertex1, min_vertex2;

    for (const auto &entry : priority_queue)
    {
        int vertex1 = entry.first;
        for (const auto &edge : entry.second)
