#include<bits/stdc++.h>
using namespace std;

bool isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i = i + 6) 
        if (n % i == 0 || n % (i + 2) == 0) 
            return false;
    return true;
}

bool isComposite(int n) {
    if (n <= 1) return false;
    for (int i = 2; i <= sqrt(n); i++) 
        if (n % i == 0) 
            return true;
    return false;
}

int main() {
    int count = 0;
    for (int i = 5; count < 8; i+=2) { //start from the smallest odd number that can be prime (i.e., 5)
        if (isPrime(i)) {
            for (int j = 9; j < i; j+=2) { //start from smallest odd composite number (i.e., 9)
                if(isComposite(j) && isComposite(i-j)) {
                    printf("%d = %d + %d\n", i, j, i-j);
                    count++;
                    break;
                }
            }
        }
    }
    return 0;
}
```

This program fulfills the problem statement by computing the sum of two odd composite numbers with the goal of finding prime numbers for the first 8 prime numbers. 

The function `isPrime` checks if a number is prime, and the function `isComposite` checks if a number is a composite. With `isPrime` and `isComposite`, we test odd numbered integers starting from 5, until we found the first 8 such prime numbers.

