double calculateStandardDeviation(std::vector<int> vec) {
    int sum = std::accumulate(vec.begin(), vec.end(), 0.0);
    double mean =  sum / vec.size();

    double sq_sum = std::inner_product(vec.begin(), vec.end(), vec.begin(), 0.0);
