To solve this problem, we are going to use a "std::unordered_map" to generate adjacency lists for each vertex of the graph. A data structure like "std::unordered_map" is an excellent choice in this context for two reasons: it provides constant time average complexity for search, insert, and delete operations and it can handle collisions efficiently. 

Below is a c++ code snippet:

```c++
#include <unordered_map>
#include <vector>
#include <iostream>

void LaplacianToAdjacencyList(std::vector<std::vector<int>> &laplacian) {
    if (laplacian.empty()) {
        std::cout << "Input Laplacian matrix cannot be empty" << std::endl;
        return;
    } 
    int size = laplacian.size();
    std::unordered_map<int, std::vector<std::pair<int, int>>> adjacencyList;
    for (int i = 0; i < size; i++) {
        for (int j = i; j < size; j++) { 
            if (laplacian[i][j] < 0) {
                adjacencyList[i + 1].push_back({j + 1, -laplacian[i][j]});
                adjacencyList[j + 1].push_back({i + 1, -laplacian[i][j]});
            }
        }
    }
    for (int i = 1; i <= size; i++) {
        std::cout << "Vertex " << i << ": ";
        for (auto &j : adjacencyList[i])
            std::cout << "(" << j.first << ", " << j.second << ") ";
        std::cout << std::endl;
    }
}

int main() {
    std::vector<std::vector<int>> laplacian = {{2, -1, 0, -3}, {-1, 3, -2, -1}, {0, -2, 1, 1}, {-3, -1, 1, 2}};
    LaplacianToAdjacencyList(laplacian);
    return 0;
}
```
The function "LaplacianToAdjacencyList" accepts a 2D array as input and verifies if it's not empty. Then, it iterates over the Laplacian matrix via two nested loops and, wherever a negative entry is encountered, an edge is added to the adjacency list of both vertices (since the graph is non-bidirectional), with the edge's weight being the absolute value of said negative entry.
These adjacency lists are then printed out for each vertex in the form (vertex, weight).

