using namespace std;

float custom_max_element(vector<float> l){
    // if the vector is empty, return 0
    if(l.empty()) return 0;

    int negativeFlag = 1;
    // initially set the max number to the lowest possible of float
    float max_num = std::numeric_limits<float>::lowest();

    for(float num : l){
        // check whether there exists positive numbers
        if(num >= 0){ 
