import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class TimeRangeManager {
    private final Lock lock = new ReentrantLock();
    private final Condition unprotectedCondition = lock.newCondition();
    private long protectedTime = Long.MIN_VALUE;

    public TimeRangeManager() {
        // Constructor implementation
    }

    public void protectTimeRange(long t_min) {
        lock.lock();
        try {
            if (t_min > protectedTime) {
                protectedTime = t_min;
            }
        } finally {
            lock.unlock();
        }
    }

    public void unprotectTimeRange(long t_min) {
        lock.lock();
        try {
            if (t_min <= protectedTime) {
                protectedTime = Long.MIN_VALUE;
                unprotectedCondition.signalAll();
            }
        } finally {
            lock.unlock();
        }
    }

    public void runWhenUnprotected(long t) {
        lock.lock();
        try {
            while (t <= protectedTime) {
                unprotectedCondition.await();
            }
            // Perform the action when the time range is unprotected
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            lock.unlock();
        }
    }
}
```

In the `TimeRangeManager` class, a `ReentrantLock` is used to ensure thread safety. The `protectTimeRange` method updates the protected time if the specified time is greater than the current protected time. The `unprotectTimeRange` method resets the protected time and signals all waiting threads when the specified time is less than or equal to the current protected time. The `runWhenUnprotected` method waits until the specified time is greater than the protected time before performing the action.

