std::vector<std::string> DemarcateBracketClusters(std::string inputString) {
    // Declare vector of strings to store bracket clusters
    std::vector<std::string> bracketClusters;

    // Remove white spaces from the string.
    inputString.erase(remove(inputString.begin(), inputString.end(), ' '), inputString.end());

    // Initialize the cluster depth variable for tracking the depth of the clusters
    int clusterDepth = 0;

    // Declare an empty string to build bracket clusters
    std::string clusterString = "";

    // Iterate over each character of the input string
    for(char character: inputString) {
        if(character == '(') {
            // Increase the cluster depth if character is '('
            clusterDepth++;
        } else if(character == ')') {
            // Decrease the cluster depth if character is ')'
            clusterDepth--;
        }

        // Append the current character to cluster string
        clusterString += character;

        // When the depth returns to 0, it indicates the end of a cluster
        if(clusterDepth == 0) {
            // Add this cluster string to our final clusters vector
            bracketClusters.push_back(clusterString);
            // Empty the cluster string to be ready for next potential cluster
            clusterString = "";
        }
    }

    // Return the bracket clusters
    return bracketClusters;
}

