class Trie:
    CHAR_START = ord('a')

    def __init__(self):
        self.n = 0
        self.s = []
        self.len = [0] * 1000
        self.fail = [0] * 1000
        self.node = [[0] * 26 for _ in range(1000)]

    def new_node(self, length):
        self.len[self.n] = length
        self.fail[self.n] = 0
        for i in range(26):
            self.node[self.n][i] = 0
        return self.n

    def get_fail(self, x):
        while self.s[self.n - self.len[x] - 1] != self.s[self.n]:
            x = self.fail[x]
        return x

    def add(self, string):
        for ch in string:
            c = ord(ch) - self.CHAR_START
            self.s.append(c)
            self.n += 1
            cur = self.get_fail(self.n - 1)
            if not self.node[cur][c]:
                now = self.new_node(self.len[cur] + 2)
                self.fail[now] = self.node[self.get_fail(self.fail[cur])][c]
                self.node[cur][c] = now

    def query(self, string):
        p = 0
        for ch in string:
            c = ord(ch) - self.CHAR_START
            if not self.node[p][c]:
                return False
            p = self.node[p][c]
        return True
```

