#include <string>
#include <unordered_map>
using namespace std;

string minWindowSubstring(string s1, string s2) {
    unordered_map<char, int> target, window;
    for (char c : s2) target[c]++;

    int left = 0, right = 0, count = 0, minLen = INT_MAX, minStart = 0;

    while (right < s1.size()) {
        char c = s1[right];
        if (target.find(c) != target.end()) {
            window[c]++;
            if (window[c] <= target[c]) count++;
        }
        right++;

        while (count == s2.size()) {
            if (right - left < minLen) {
                minLen = right - left;
                minStart = left;
            }
            char c2 = s1[left];
            if (target.find(c2) != target.end()) {
                window[c2]--;
                if (window[c2] < target[c2]) count--;
            }
            left++;
        }
    }

    return minLen == INT_MAX ? "" : s1.substr(minStart, minLen);
}
