```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
#include <stdexcept>

std::mutex mtx;

void calcFibonacci(int n, std::vector<unsigned long long>& fibSeries) {
    std::lock_guard<std::mutex> guard(mtx);
    try {
        fibSeries[0] = 0;
        if(n > 0) {
            fibSeries[1] = 1;
            for(int i = 2; i <= n; ++i) {
                fibSeries[i] = fibSeries[i-1] + fibSeries[i-2];
                if(fibSeries[i] < fibSeries[i-1]) {
                    throw std::overflow_error("Detected overflow!");
                }
            }
        }
    } catch(const std::overflow_error& oe) {
        std::cerr << "Overflow error: " << oe.what() << '\n';
    }
}

int main() {
    const int N = 50; // number of terms to compute in the Fibonacci series
    std::vector<unsigned long long> fibSeries(N+1, 0); // initially fill with zeros
    std::thread fibonacci_thread(calcFibonacci, N, std::ref(fibSeries));
    fibonacci_thread.join();

    for(int i = 0; i <= N; ++i) {
        std::cout << "fib(" << i << ") = " << fibSeries[i] << std::endl;
    }

    return 0;
}
```

This code launches a thread to compute N terms of the Fibonacci series. It stores the results in a std::vector. The std::mutex ensures that only one thread can access and modify the vector at a same time to avoid race conditions. 

If a term in the Fibonacci sequence is less than its previous term, it indicates an overflow. In this case, we throw a std::overflow_error exception.

Please note that this code is only an example and may need to be adjusted for a particular use case. Fibonacci sequence grows rapidly, so even with unsigned long long data type, overflow will happen relatively quickly.

