        if(arr[mid] == target)
            return mid;
        if(arr[mid] < target)
            l = mid + 1;
        else
            r = mid - 1;
    }
    return -1;
}

// main function
int main() {
    vector<int> nums = {2, 4, 8, 6, 8, 10};
    int target = 8;

    // sort the numbers
    sort(nums.begin(), nums.end());

    // find the first occurrence of the target
    int index = binarySearch(nums, target);

    if(index == -1) {
        cout << "Target not found" << '\n';
        return 0;
    }

    // find duplicate entries
    vector<int> duplicates;
    int left = index, right = index;  // initialize as current index
    while(left > 0 && nums[left-1] == target) {
        duplicates.push_back(--left);
    }
    while(right < nums.size()-1 && nums[right+1] == target) {
        duplicates.push_back(++right);
    }

    // print all positions where the target is found
    cout << "Target found at positions: " << '\n';
    for(int pos: duplicates) {
        cout << pos << " ";
    }

    return 0;
}
```

In terms of complexity:
- Time complexity: Since we're using a sorting algorithm (O(n log n)), then a binary search (O(log n)), our overall time complexity will be O(n log n).
- Space complexity: We're using a temporary vector to store the positions. In the worst-case scenario (the entire sequence is full of the target integer), the space complexity will be O(n).

