Here is a C++ program that calculates all prime numbers up to a number given by user using the Sieve of Eratosthenes algorithm. The program uses OpenMP to parallelize the calculation and measures the computation time. All prime numbers are written to a text file named 'primes.txt'.

```C++
#include <iostream>
#include <vector>
#include <fstream>
#include <omp.h>
#include <cmath>
#include <chrono>

using namespace std;

// function to implement Sieve of Eratosthenes algorithm
vector<int> SieveOfEratosthenes(int n) {
    vector<bool> prime(n+1, true);

    prime[0] = prime[1] = false;
    int m = sqrt(n);

    #pragma omp parallel for schedule(dynamic)
    for (int p=2; p<=m; p++) 
    {
        if (prime[p] == true) 
        {
            // mark all multiples of a prime number as non prime
            for(int i=p*p; i<= n; i+= p)
                prime[i] = false;
        }
    }

    vector<int> prime_numbers;
    for(int i = 0; i< prime.size(); i++)
        if(prime[i])
            prime_numbers.push_back(i);

    return prime_numbers;
}

int main() {
    int n;
    cout << "Enter a number: ";
    cin >> n;

    auto start = chrono::high_resolution_clock::now();
    vector<int> primes = SieveOfEratosthenes(n);
    auto end = chrono::high_resolution_clock::now();

    // write prime numbers to a file
    ofstream out_file("primes.txt");
    for(int prime : primes)
        out_file << prime << endl;
    out_file.close();

    // calculate execution time
    chrono::duration<double> diff = end-start;
    cout << "Time taken to calculate primes upto " << n << " is " << diff.count() << " seconds" << endl;

    return 0;
}
```

Please note that the performance of multi-threaded code using OpenMP may vary depending on your system's hardware and the number of available cores. In some cases, the overhead of creating and managing threads could make the parallel version slower than the serial version. In this specific implementation, we are using dynamic scheduling to distribute work among threads, which tends to provide better load balancing when the work cannot be evenly divided among threads.

