Here is a C++ implementation of merge sort that also sorts a 2D array in row-major order. In the row-major order the elements in each individual row (from top to bottom), following the elements in that row (from left to right).

```cpp
#include<iostream>
#include<vector>
#define ROW 5
#define COL 5

using namespace std;

// Function to merge two halves
void merge(int* arr, int l, int m, int r) {
    int i, j, k;
    int n1 = m - l + 1;
    int n2 =  r - m;

    /* create temp arrays */
    int L[n1], R[n2];

    /* Copy data to temp arrays L[] and R[] */
    for (i = 0; i < n1; i++)
        L[i] = arr[l + i];
    for (j = 0; j < n2; j++)
        R[j] = arr[m + 1+ j];

    /* Merge the temp arrays */
    i = 0; 
    j = 0; 
    k = l; 
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            arr[k] = L[i];
            i++;
        }
        else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }

    /* Copy the remaining elements of L[], if there
    are any */
    while (i < n1) {
        arr[k] = L[i];
        i++;
        k++;
    }

    /* Copy the remaining elements of R[], if there
    are any */
    while (j < n2) {
        arr[k] = R[j];
        j++;
        k++;
    }
}

// Merge sort function
void mergeSort(int* arr, int l, int r){
    if (l < r) {
        int m = l+(r-l)/2;
        mergeSort(arr, l, m);
        mergeSort(arr, m+1, r);
        merge(arr, l, m, r);
    }
}

// Function to convert 2D array to 1D
void convert(int* arr[], int n, int m, int newArr[]){
    int idx = 0;
    for(int i = 0; i < n; i++)
        for(int j = 0; j < m; j++)
            newArr[idx++] = arr[i][j];
}

// Function to print 2D array
void print2DArr(int arr[], int n, int m){
    for(int i = 0; i < n * m; i++){
        if(i % m == 0)
            printf("\n");
        printf("%d ", arr[i]);
    }
}

// Main function
int main(){
    int arr[ROW][COL] = {
        {2, 5, 7, 8, 9},
        {0, 1, 3, 4, 6},
        {22, 18, 19, 17, 21},
        {12, 14, 15, 11, 13},
        {25, 23, 26, 24, 20}
    };

    int newRowArr[ROW*COL];
    convert(arr, ROW, COL, newRowArr);

    mergeSort(newRowArr, 0, ROW*COL - 1);

    print2DArr(newRowArr,ROW,COL);

    return 0;
}
```

The 'convert' function is created to convert the 2D array into a 1D array because it's more convenient to deal with sorting.
The 'mergeSort' function is used to sort 1D array.
Finally, 'print2DArr' function is used to print out the result in 2D format (row-major order).
The input can be set in the 'main' function.

Remember to modify ROW and COL macros in the preprocessor directives (#define) to change the dimensions of the 2D array. Also, ROW * COL should not exceed the limit of an integer data type in C++.

A sparse matrix is a matrix that is comprised of mostly zero values. Sparse matrices are distinct from matrices with mostly non-zero values, which are referred to as dense matrices. The challenge with sparse matrix is that if you store them in the normal way in memory, they take a lot of extra space for storing zeros which is not only inefficient for storage but also computation. 

Hence, we can use a map in C++ STL which can be an efficient data structure to store a sparse matrix. Ordered map of ordered maps i.e., map of maps, in which first key will denote row and second key will denote column, would be an ideal choice as the operations will have a time complexity of O(logn). 

Here is a demo C++ program which performs operations like addition, multiplication, transpose on sparse matrix using map of maps.

```C++
#include<iostream>
#include<map>
using namespace std;

// Function to conduct the transpose of the sparse matrix
map<int,map<int,int>> transpose(map<int,map<int,int>>& a)
{
    map<int,map<int,int>> ans;
    for(auto i=a.begin();i!=a.end();i++)
    {
        for(auto j=(i->second).begin();j!=(i->second).end();j++)
        {
            ans[j->first][i->first]+=(j->second);
        }
    }
    return ans;
}

// Function to multiply two sparse matrices
map<int,map<int,int>> multiply(map<int,map<int,int>>& a, map<int,map<int,int>>& b)
{
    b=transpose(b);
    map<int,map<int,int>> mult;
    for(auto i=a.begin();i!=a.end();i++)
    {
        for(auto j=b.begin();j!=b.end();j++)
        {
            int sum=0;
            for(auto k=(i->second).begin();k!=(i->second).end();k++)
            {
                sum+=(k->second)*(j->second)[k->first];
            }
            if(sum!=0) mult[i->first][j->first]=sum;
        }
    }
    return mult;
}

// Function to perform Addition of two Sparse Matrices 
map<int,map<int,int>> addition(map<int,map<int,int>>& a, map<int,map<int,int>>& b)
{
    map<int,map<int,int>> add;
    for(auto &x:a)
    {
        for(auto& y : x.second)
        {
            add[x.first][y.first]+=y.second;
        }
    }
    for(auto &x:b)
    {
        for(auto& y : x.second)
        {
            add[x.first][y.first]+=y.second;
        }
    }
    return add;
}
```

Finding a determinant of a sparse matrix using 'map of maps' in C++ would be difficult. So, it would be a good idea to convert the sparse matrix into a 2-Dimensional vector and then proceed for finding determinant.

This is an optimal approach for handling sparse matrices. It ensures that zero values do not take up unnecessary space thereby optimising memory use.

Note: This solution uses simple CSR (Compressed Sparse Row) concept but multiple other techniques exists like using three one-dimensional arrays to keep track of row indices, column indices and non-zero values etc. or using Linked Lists or using two-dimensional Lists with special Nodes as per the requirements and scenarios. The best fit has to decided as the situation demands.

