using namespace std;

// Function to print the longest increasing subsequence
void printLIS(vector<int>& arr) {
    vector<vector<int> > LIS(arr.size());

    // Initializing first subsequence
    LIS[0].push_back(arr[0]);

    for (int i = 1; i < arr.size(); i++) {
        for (int j = 0; j < i; j++) {
            if ((arr[i] > arr[j]) && (LIS[i].size() < LIS[j].size() + 1)) {
                LIS[i] = LIS[j];
            }
        }
        LIS[i].push_back(arr[i]);
    }

    vector<int> max = LIS[0];

    // Get longest increasing subsequence
    for (vector<int> x : LIS) {
        if (x.size() > max.size()) {
            max = x;
        }
    }

    for (int i = 0; i < max.size(); i++) {
        cout << max[i] << " ";
    }
    cout << endl;
}

