```cpp
#include <bits/stdc++.h>
using namespace std;
using pi = pair<int, int>;

pair<bool, vector<pi>> advanced_sort(vector<int> numbers) {
    assert(all_of(numbers.begin(), numbers.end(), [](int i){ return i >= 1 && i <= int(1e7);}));

    vector<pi> pairs(numbers.size());
    for (int i = 0; i < numbers.size(); ++i) {
        pairs[i] = {numbers[i], i};
    }
    sort(pairs.begin(), pairs.end());

    vector<vector<pi>> buckets(5);

    for (auto & [num, pos] : pairs) {
        bool bucked = false;
        for (auto & bucket : buckets) {
            if (bucket.empty() || bucket.back().second <= pos ) {
                bucket.push_back({num, pos});
                bucked = true;
                break;
            }
        }
        if (!bucked) {
            throw false;
        }
    }
    vector<pi> seq;
    for (int i = 0; i < buckets.size(); ++i) {
        auto & bucket = buckets[i];
        if (!(i % 2)) {
            seq.insert(seq.end(), bucket.begin(), bucket.end());
        } else {
            seq.insert(seq.end(), bucket.rbegin(), bucket.rend());
        }
    }
    vector<int> range(seq.size());
    for (int i = 0; i < seq.size(); ++i) {
        range[i] = seq[i].second;
    }
    for (bool swapped = true; swapped; ) {
        swapped = false;
        for (int i = 0; i < numbers.size() - 1; ++i) {
            if (range[i] > range[i + 1]) {
                swap(range[i], range[i + 1]);
                swapped = true;
                break;
            }
        }
        if (!swapped) {
            return {true, seq};
        }
    }
    return {true, seq};
}

int main() {
    vector<int> numbers{1, 2, 3, 6, 5};
    auto result = advanced_sort(numbers);
    for (auto & p : result.second) {
        cout << '(' << p.first << ',' << p.second << "),";
    }
    return 0;
}
