    cv::calcHist(&part2, 1, 0, cv::Mat(), hist2, 1, &histSize, &histRange, uniform, accumulate);

    // Calculate histogram intersection similarity
    double similarity = 0;
    for (int i = 0; i < histSize; i++) {
        similarity += std::min(hist1.at<float>(i), hist2.at<float>(i));
    }

    return similarity;
}

