#include<string>
#include<unordered_set>
#include<sstream>

bool compareWordSets(const std::string& phrase1, const std::string& phrase2) 
{
    std::unordered_set<std::string> c1, c2;
    std::string buf; 

    // split phrase 1 into words and store in c1
    std::stringstream ss1(phrase1); 
    while (ss1 >> buf)
        c1.insert(buf);
    buf.clear();

    // split phrase 2 into words and store in c2
