    if (num == 2 || num == 3) return true;
    if (num % 2 == 0 || num == 1) return false;
    for (int i = 3; i * i <= num; i += 2)
        if (num % i == 0)
            return false;
    return true;
}

int main() {
    int count = 0, sum = 0, num = 2;

    while (count < 10) {
        if (isPrime(num)) {
            sum += num;
            count++;
        }
        num++;
