Here is the C++ program using the selection sort algorithm. This program sorts the array in ascending order and prints the array after each iteration:

```C++
#include <iostream>
using namespace std;

void selectionSort(int arr[], int n) {
    int i, j, minIndex, temp;

    for (i = 0; i < n - 1; i++) {
        minIndex = i;

        for (j = i + 1; j < n; j++)
            if (arr[j] < arr[minIndex])
                minIndex = j;

        temp = arr[minIndex];
        arr[minIndex] = arr[i];
        arr[i] = temp;

        // Printing array after each pass
        cout << "After pass " << i + 1 << ": ";
        for (int k = 0; k < n; k++)
            cout << arr[k] << " ";
        cout << "\n";
    }
}

int main() {
    int arr[] = {2, 7, 4, 1, 5, 3};
    int n = sizeof(arr) / sizeof(arr[0]);

    cout << "Initial array: ";
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
    cout << "\n";

    selectionSort(arr, n);
    return 0;
}
```

The output of this program is:
```
Initial array: 2 7 4 1 5 3
After pass 1: 1 7 4 2 5 3
After pass 2: 1 2 4 7 5 3
After pass 3: 1 2 3 7 5 4
After pass 4: 1 2 3 4 5 7
After pass 5: 1 2 3 4 5 7
```
The selection sort works by repeatedly finding the minimum element from the unsorted part and putting it at the start. After each pass, the minimum element from the unsorted part is moved to its correct position.

