struct TrieNode{
    TrieNode* children[26];
    bool isEndOfWord;
};

TrieNode *getNode(void){
    TrieNode *node = new TrieNode;
    node -> isEndOfWord = false;
    for(int i = 0; i<26; i++){
        node -> children[i] = NULL;
    }
    return node;
}

// If not present, inserts key into trie, if the key is prefix of trie node, just marks leaf node
void insert(TrieNode *root, string key){
    transform(key.begin(), key.end(), key.begin(), ::tolower);
    TrieNode *node = root;
    for(int i = 0; i<key.length(); i++){
        int index = key[i]-'a';
        if(!node -> children[index]){
            node -> children[index] = getNode();
        } 
        node = node -> children[index];
    }
    node -> isEndOfWord = true;
}

void searchPrefixWord(TrieNode* root, string str){
    TrieNode* node = root;
    for(int i = 0; i<str.length(); i++){
        if(node -> children[str[i]-'a'] == NULL){
            return;
        }
        node = node->children[str[i]-'a'];
    }

    queue<pair<TrieNode*, string> > q;
    q.push({node, str});

    while(!q.empty()){
        pair<TrieNode*, string> p = q.front();
        q.pop();

        if(p.first->isEndOfWord){
            cout << p.second << endl;
        }

        for(int i = 0; i<26; i++){
            TrieNode* child = p.first -> children[i];
            if(child){
                q.push({child, p.second + (char)('a'+i)});
            }
        }
    }
}

