#include <iostream>
#include <cmath>

class Vector3D {
public:
    double x, y, z;

    // Constructor
    Vector3D(double x = 0, double y = 0, double z = 0)
    : x(x), y(y), z(z) {}

    // Add vectors
    Vector3D operator+(const Vector3D& vec) const {
        return Vector3D(x + vec.x, y + vec.y, z + vec.z);
    }

    // Subtract vectors
    Vector3D operator-(const Vector3D& vec) const {
        return Vector3D(x - vec.x, y - vec.y, z - vec.z);
    }

    // Cross product
    Vector3D crossProduct(const Vector3D& vec) const {
        return Vector3D(y * vec.z - z * vec.y, z * vec.x - x * vec.z, x * vec.y - y * vec.x);
    }

    // Distance between two points
    double distanceTo(const Vector3D& vec) const {
        return sqrt(pow(x - vec.x, 2) + pow(y - vec.y, 2) + pow(z - vec.z, 2));
    }

    // Equality check considering floating point precision
    bool operator==(const Vector3D& vec) const {
        return (fabs(x - vec.x) < 1e-9 && fabs(y - vec.y) < 1e-9 && fabs(z - vec.z) < 1e-9);
    }
};

int main() {
    Vector3D vec1(1.0, 2.0, 3.0);
    Vector3D vec2(1.0, 2.0, 3.0);

    Vector3D vec3 = vec1 + vec2;
    Vector3D vec4 = vec1 - vec2;
    Vector3D vec5 = vec1.crossProduct(vec2);
    double dist = vec1.distanceTo(vec2);
    bool equal = vec1 == vec2;

    std::cout << "Addition: (" << vec3.x << ", " << vec3.y << ", " << vec3.z << ")\n";
    std::cout << "Subtraction: (" << vec4.x << ", " << vec4.y << ", " << vec4.z << ")\n";
    std::cout << "Cross Product: (" << vec5.x << ", " << vec5.y << ", " << vec5.z << ")\n";
    std::cout << "Distance: " << dist << "\n";
    std::cout << "Equality: " << std::boolalpha << equal << "\n";    

    return 0;
}
```
